# --- HTML parser selection ---------------------------------------------------
# Prefer lxml over the stdlib html.parser when it's installed: lxml is a C
# parser that's typically 5-10x faster and noticeably reduces CPU pressure on
# the crawler's hot path (every successful page fetch parses a soup + we
# parse a second soup later for non-email extractors). We probe at import
# time so we pay the import cost ONCE rather than on every parse.
try:
    import lxml  # type: ignore  # noqa: F401
    _HTML_PARSER: str = "lxml"
except ImportError:
    _HTML_PARSER = "html.parser"


def _make_soup(content, parser: Optional[str] = None) -> "BeautifulSoup":
    """Construct a ``BeautifulSoup`` using the fastest available parser.

    Falls back to ``html.parser`` if (a) ``lxml`` isn't installed, or
    (b) the chosen parser raises on the input (extremely defensive --
    BeautifulSoup itself almost never raises since it dispatches to a
    permissive tree builder, but we don't want a malformed page to
    crash the entire crawl).
    """
    chosen = parser or _HTML_PARSER
    try:
        return BeautifulSoup(content, chosen)
    except Exception as e:
        if chosen != "html.parser":
            logger.debug("[soup] %s parser failed (%s); falling back to html.parser", chosen, e)
            return BeautifulSoup(content, "html.parser")
        raise


def _append_domains_log(processed_log_path, domains):
    """Atomically append domains to the processed log with file locking."""
    import fcntl as _fcntl
    with open(processed_log_path, 'a', encoding='utf-8') as f:
        _fcntl.flock(f.fileno(), _fcntl.LOCK_EX)
        try:
            for domain in domains:
                f.write(f"{domain}\n")
            f.flush()
            os.fsync(f.fileno())
        finally:
            _fcntl.flock(f.fileno(), _fcntl.LOCK_UN)


# --- File-descriptor limit bump (Unix) ---------------------------------------
# At --concurrency 300+ we routinely have hundreds of TCP sockets in flight
# (SMTP probes, Gravatar HEADs) plus database connections, log files, and
# proxy sockets. Default Linux soft RLIMIT_NOFILE is 1024 -- easy to cross,
# and crossing it produces [Errno 24] Too many open files which the daemon
# cannot recover from. We try to raise the soft limit toward the hard limit
# (which usually does not require root) at startup. Best-effort: if the
# kernel refuses, we log and continue rather than abort.
def _raise_open_file_limit(target: int = 4096) -> Tuple[int, int, str]:
    """Try to raise the per-process soft RLIMIT_NOFILE to ``target``.

    Returns (new_soft, hard, status) where ``status`` is one of
    ``"raised"``, ``"unchanged"``, ``"unsupported"``, or ``"failed"``.
    Safe to call multiple times; subsequent calls become no-ops.
    """
    if sys.platform == "win32":
        return (0, 0, "unsupported")
    try:
        import resource  # POSIX only
    except ImportError:
        return (0, 0, "unsupported")
    try:
        soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    except Exception:
        return (0, 0, "failed")
    if soft >= target:
        return (soft, hard, "unchanged")
    new_soft = min(target, hard) if hard != resource.RLIM_INFINITY else target
    if new_soft <= soft:
        return (soft, hard, "unchanged")
    try:
        resource.setrlimit(resource.RLIMIT_NOFILE, (new_soft, hard))
        return (new_soft, hard, "raised")
    except (ValueError, OSError):
        # Non-root processes can't raise above hard; some sandboxes deny
        # even soft raises. Continue with whatever the kernel allowed.
        return (soft, hard, "failed")

