def _log_exception(module: str, exc: BaseException) -> None:
    """Engineering-level exception logging with module attribution."""
    logger.error(
        "[%s] %s: %s\n%s",
        module,
        exc.__class__.__name__,
        exc,
        traceback.format_exc(),
    )


# Characters Excel / LibreOffice / Google Sheets interpret as the start of a
# formula. Without escaping, an attacker-controlled string of the form
# ``=cmd|'/c calc'!A1`` opens calc.exe when an analyst double-clicks the CSV
# in Excel ("CSV injection" / "formula injection" / CWE-1236).
_CSV_FORMULA_PREFIXES = ("=", "+", "-", "@", "\t", "\r")


# Default connectivity-probe endpoints used by the outage detector.
# Diversified across multiple operators so a single provider's outage
# doesn't masquerade as a "we lost the internet" event, and using URLs
# that don't double as identity-fingerprints (Google specifically tracks
# unauthenticated HEAD probes; using ``1.1.1.1`` / ``9.9.9.9`` keeps the
# operator's identity isolated). The probe goes through the configured
# stealth session, which means it inherits the active proxy chain.
_DEFAULT_CONNECTIVITY_PROBES = (
    "https://1.1.1.1/",
    "https://9.9.9.9/",
    "https://www.cloudflare.com/cdn-cgi/trace",
)


def _csv_safe_value(v):
    """Return ``v`` with any leading formula-trigger character neutralised.

    Pure pass-through for non-string values (numbers, booleans, ``None``).
    For strings that start with one of ``= + - @ \\t \\r`` we prepend a
    single quote -- which Excel / LibreOffice both treat as "this is a
    literal string, not a formula" and silently strip on display, but
    which downstream tooling (pandas, csv.DictReader) preserves verbatim
    without ill effect.

    Toggleable via the module-global ``CSV_INJECTION_GUARD`` (default on).
    """
    if not CSV_INJECTION_GUARD:
        return v
    if not isinstance(v, str) or not v:
        return v
    if v[0] in _CSV_FORMULA_PREFIXES:
        return "'" + v
    return v


def _csv_safe_row(row):
    """List-of-cells variant of :func:`_csv_safe_value`."""
    if not CSV_INJECTION_GUARD:
        return row
    return [_csv_safe_value(c) for c in row]


def _csv_safe_dict(row_dict):
    """Dict-of-cells variant of :func:`_csv_safe_value`."""
    if not CSV_INJECTION_GUARD:
        return row_dict
    return {k: _csv_safe_value(v) for k, v in row_dict.items()}


class _SafeCsvWriter:
    """Thin wrapper around ``csv.writer`` that scrubs every cell for
    CSV-injection prefixes before forwarding to the underlying writer.
    Drop-in: exposes ``writerow`` / ``writerows``.
    """

    def __init__(self, underlying):
        self._w = underlying

    def writerow(self, row):
        return self._w.writerow(_csv_safe_row(list(row)))

    def writerows(self, rows):
        return self._w.writerows([_csv_safe_row(list(r)) for r in rows])


class _SafeCsvDictWriter:
    """Thin wrapper around ``csv.DictWriter`` that scrubs every cell for
    CSV-injection prefixes. Drop-in: exposes ``writeheader`` / ``writerow``
    / ``writerows`` and forwards every other attribute to the underlying
    writer.
    """

    def __init__(self, underlying):
        self._w = underlying

    def writeheader(self):
        return self._w.writeheader()

    def writerow(self, row_dict):
        return self._w.writerow(_csv_safe_dict(row_dict))

    def writerows(self, rows):
        return self._w.writerows([_csv_safe_dict(r) for r in rows])

    def __getattr__(self, name):
        return getattr(self._w, name)


