def random_browser_headers() -> Dict[str, str]:
    """Return a dict of headers that look like a normal browser request.

    Rotates User-Agent + Accept-Language each call. Used by the crawler to
    avoid the "every request has identical headers" fingerprint.
    """
    return {
        "User-Agent": random.choice(_USER_AGENT_POOL),
        "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/webp,*/*;q=0.8",
        "Accept-Language": random.choice(_ACCEPT_LANGUAGES),
        "Accept-Encoding": "gzip, deflate, br",
        "Cache-Control": "max-age=0",
        "Upgrade-Insecure-Requests": "1",
        "Sec-Fetch-Dest": "document",
        "Sec-Fetch-Mode": "navigate",
        "Sec-Fetch-Site": "none",
        "Sec-Fetch-User": "?1",
    }


def _diagnose_tls() -> None:
    """Print the JA3 / TLS fingerprint Tier-1 will present.

    Used by --diagnose-tls. We hit two passive TLS-fingerprint endpoints
    (tls.peet.ws/api/all and ja3er.com) using the actual stealth session
    so the operator sees exactly what their target sees: User-Agent,
    JA3 hash, JA3N hash, client-hints, ALPN list. If curl_cffi is missing
    or the impersonation is broken, the JA3 will be the giveaway Python
    requests fingerprint -- which is the whole point of running this
    diagnostic.
    """
    try:
        sess = _StealthSession()
    except Exception as e:  # pragma: no cover -- only on broken installs
        print(f"[!] Could not construct stealth session: {e}")
        return
    print(f"[diagnose-tls] backend = {sess.kind}")
    try:
        for url in (
            "https://tls.peet.ws/api/all",
            "https://ja3er.com/json",
        ):
            print(f"[diagnose-tls] -> {url}")
            try:
                with sess.get(url, timeout=15, headers=random_browser_headers()) as resp:
                    print(f"  status = {resp.status_code}")
                    body = (resp.text or "")[:1500]
                    print(f"  body (truncated 1500B):\n{body}\n")
            except Exception as e:
                print(f"  error = {e!r}")
    except Exception:
        pass
    finally:
        sess.close()


# --- Internet speed test + adaptive tuning -----------------------------------

def measure_internet_speed(timeout: float = 4.0) -> Dict[str, float]:
    """Probe outbound bandwidth and latency without third-party services.

    Downloads a small static file from Cloudflare's public speedtest endpoint
    (no API key required, no analytics, no paid tier). Returns:

      {
        "ok"         : bool,
        "rtt_ms"     : float,   # round-trip time
        "mbps"       : float,   # measured download throughput
        "bytes"      : int,     # bytes downloaded
        "elapsed"    : float,   # seconds taken
      }

    Designed to be cheap (~100 KB download). Falls back gracefully on any
    network error.
    """
    # 100 KB sample. Cloudflare speedtest endpoint is free, public, and unlogged
    # for individual probes.
    url = "https://speed.cloudflare.com/__down?bytes=100000"
    out = {"ok": False, "rtt_ms": 0.0, "mbps": 0.0, "bytes": 0, "elapsed": 0.0}
    try:
        t0 = time.time()
        with requests.Session() as _sess:
            with _sess.get(url, timeout=timeout, headers=random_browser_headers()) as resp:
                elapsed = max(time.time() - t0, 0.0001)
                n = len(resp.content)
                if resp.ok and n > 0:
                    mbps = (n * 8 / 1_000_000) / elapsed
                    out.update({
                        "ok": True,
                        "rtt_ms": elapsed * 1000.0,
                        "mbps": mbps,
                        "bytes": n,
                        "elapsed": elapsed,
                    })
    except Exception as e:
        logger.info("[speedtest] probe failed: %s -- assuming low-bandwidth defaults", e)
    return out


def autotune_concurrency(measured: Dict[str, float], cli_threads: Optional[int] = None) -> Dict[str, int]:
    """Pick threads/concurrency values appropriate for the measured link.

    Returns ``{"threads": int, "verifier_concurrency": int}``.

    Heuristic (free, non-paid):
      - <  5  Mbps   : threads=10,  verifier=30
      - <  20 Mbps   : threads=20,  verifier=50
      - <  50 Mbps   : threads=30,  verifier=80
      - <  150 Mbps  : threads=50,  verifier=120
      - >= 150 Mbps  : threads=80,  verifier=200

    Latency penalises the throughput band by one tier (slow round-trips imply
    head-of-line blocking, so adding more threads doesn't help).
    """
    if cli_threads is not None:
        # Caller explicitly chose a value; respect it but still scale verifier.
        # Cap at 300 simultaneous SMTP connections so a high crawler thread
        # count (e.g. -t 200 -> 800 SMTP connections) doesn't trip mass
        # SMTP server rate limits / blacklists. 300 is a safer ceiling
        # observed in practice across major mail providers.
        return {
            "threads": cli_threads,
            "verifier_concurrency": max(50, min(cli_threads * 4, 300)),
        }
    mbps = measured.get("mbps", 0.0) if measured.get("ok") else 0.0
    rtt = measured.get("rtt_ms", 0.0) if measured.get("ok") else 0.0

    if mbps < 5:
        threads, verifier = 10, 30
    elif mbps < 20:
        threads, verifier = 20, 50
    elif mbps < 50:
        threads, verifier = 30, 80
    elif mbps < 150:
        threads, verifier = 50, 120
    else:
        threads, verifier = 80, 200

    # High RTT -> the network is the bottleneck, not the CPU; clamp down.
    if rtt > 800:
        threads = max(8, threads // 2)
        verifier = max(20, verifier // 2)
    return {"threads": threads, "verifier_concurrency": verifier}


# --- Sitemap.xml parsing -----------------------------------------------------

# Words that signal a contact-discovery URL; used to filter sitemap output to
# only the high-yield URLs (avoid crawling 50,000 product pages).
_CONTACT_KEYWORDS = (
    "contact", "about", "team", "staff", "people", "leadership", "careers",
    "jobs", "press", "media", "investors", "support", "help", "imprint",
    "legal", "privacy", "gdpr", "dpa", "security", "vulnerability",
    "responsible-disclosure", "bug-bounty", "disclosure", "abuse",
    "newsroom", "company", "founders", "executives", "officers", "office",
    "locations", "branches", "regional", "vendors", "procurement",
    "partners", "resellers", "distributors", "franchise",
)


def filter_sitemap_urls(urls: List[str], host_filter: Optional[str] = None) -> List[str]:
    """Filter a list of sitemap URLs down to the contact-discovery subset.

    Keeps URLs whose path contains any of the well-known contact / about /
    legal / press keywords. Optionally restricts to a single host so that
    sitemap_index.xml entries pointing off-domain are dropped.
    """
    keep: List[str] = []
    seen = set()
    for u in urls:
        if not u:
            continue
        u = u.strip()
        if not u or u in seen:
            continue
        seen.add(u)
        try:
            parsed = urlparse(u)
        except Exception:
            continue
        if host_filter and parsed.netloc:
            netloc = parsed.netloc.lower()
            if netloc.startswith("www."):
                netloc = netloc[4:]
            if netloc != host_filter:
                continue
        path_l = (parsed.path or "").lower()
        if any(kw in path_l for kw in _CONTACT_KEYWORDS):
            keep.append(u)
    return keep


def parse_sitemap_xml(xml_bytes: bytes) -> Tuple[List[str], List[str]]:
    """Parse sitemap.xml or sitemap_index.xml content.

    Returns (page_urls, child_sitemap_urls). Either may be empty.
    Robust against malformed XML / namespace prefixes / mixed encodings.
    """
    page_urls: List[str] = []
    child_sitemaps: List[str] = []
    if not xml_bytes:
        return page_urls, child_sitemaps
    try:
        soup = BeautifulSoup(xml_bytes, "xml")
    except Exception:
        # Fall back to html parser; sitemap files served as text/html exist.
        try:
            soup = BeautifulSoup(xml_bytes, "html.parser")
        except Exception:
            return page_urls, child_sitemaps

    for sm in soup.find_all("sitemap"):
        loc = sm.find("loc")
        if loc and loc.text:
            child_sitemaps.append(loc.text.strip())
    for url_tag in soup.find_all("url"):
        loc = url_tag.find("loc")
        if loc and loc.text:
            page_urls.append(loc.text.strip())
    return page_urls, child_sitemaps


# --- robots.txt parsing ------------------------------------------------------

class _RobotsRules:
    """Tiny RFC-9309-ish robots.txt parser.

    Parses ``Disallow``, ``Allow``, and ``Crawl-delay`` for the ``*`` user-agent
    only (sufficient for our use case). No external deps -- urllib's
    RobotFileParser is also fine but does not expose Crawl-delay portably.
    """

    __slots__ = ("disallow", "allow", "crawl_delay", "_allow_cache", "_disallow_cache", "_ALLOW_CACHE_CAP", "_DISALLOW_CACHE_CAP")

    def __init__(self) -> None:
        self.disallow: List[str] = []
        self.allow: List[str] = []
        self.crawl_delay: float = 0.0
        self._allow_cache: Dict[str, "re.Pattern"] = {}
        self._disallow_cache: Dict[str, "re.Pattern"] = {}
        self._ALLOW_CACHE_CAP = 2048
        self._DISALLOW_CACHE_CAP = 2048

    @classmethod
    def parse(cls, text: str) -> "_RobotsRules":
        rules = cls()
        active = False
        # Strip UTF-8 BOM if present (RFC 9309 §2.1). Python's str.strip()
        # does NOT remove U+FEFF, so a BOM-prefixed robots.txt would silently
        # drop the first User-agent directive group.
        if text and text.startswith("\ufeff"):
            text = text[1:]
        for line in (text or "").splitlines():
            line = line.split("#", 1)[0].strip()
            if not line:
                continue
            if ":" not in line:
                continue
            key, _, value = line.partition(":")
            key = key.strip().lower()
            value = value.strip()
            if key == "user-agent":
                active = (value == "*")
                continue
            if not active:
                continue
            if key == "disallow" and value:
                rules.disallow.append(value)
            elif key == "allow" and value:
                rules.allow.append(value)
            elif key == "crawl-delay":
                try:
                    rules.crawl_delay = max(rules.crawl_delay, float(value))
                except ValueError:
                    pass
        return rules

    @staticmethod
    def _glob_to_regex(pattern: str) -> "re.Pattern":
        """Convert a robots.txt glob pattern to a compiled regex (RFC 9309).

        ``*`` matches any sequence of characters (including ``/`` and ``?``).
        ``$`` at the end anchors the pattern to the end of the URL path.
        Patterns without ``*`` or ``$`` are prefix-matched (the common case).
        """
        import re as _re
        if "*" not in pattern and "$" not in pattern:
            return _re.compile(_re.escape(pattern))
        parts = []
        i = 0
        while i < len(pattern):
            c = pattern[i]
            if c == "*":
                parts.append(".*")
            elif c == "$" and i == len(pattern) - 1:
                # RFC 9309: $ is only an end-of-path anchor when it appears
                # at the end of the pattern. Mid-pattern $ is literal.
                parts.append("\\Z")
            else:
                parts.append(_re.escape(c))
            i += 1
        return _re.compile("".join(parts))

    def is_allowed(self, path: str) -> bool:
        """Return True if the given path is permitted under these rules.

        ``Allow`` rules win over ``Disallow`` when more specific (longer match).
        Wildcard patterns are matched per RFC 9309 (``*`` matches any sequence).
        """
        path = path or "/"
        best_allow = -1
        best_disallow = -1
        for a in self.allow:
            p = self._allow_cache.get(a)
            if p is None:
                try:
                    p = self._glob_to_regex(a)
                except re.error:
                    continue
                self._allow_cache[a] = p
                if len(self._allow_cache) > self._ALLOW_CACHE_CAP:
                    self._allow_cache.pop(next(iter(self._allow_cache)), None)
            try:
                m = p.match(path)
            except re.error:
                continue
            if m and len(m.group()) > best_allow:
                best_allow = len(m.group())
        for d in self.disallow:
            p = self._disallow_cache.get(d)
            if p is None:
                try:
                    p = self._glob_to_regex(d)
                except re.error:
                    continue
                self._disallow_cache[d] = p
                if len(self._disallow_cache) > self._DISALLOW_CACHE_CAP:
                    self._disallow_cache.pop(next(iter(self._disallow_cache)), None)
            try:
                m = p.match(path)
            except re.error:
                continue
            if m and len(m.group()) > best_disallow:
                best_disallow = len(m.group())
        if best_disallow == -1:
            return True
        return best_allow >= best_disallow


# --- Per-domain token-bucket rate limiter ------------------------------------

class DomainRateLimiter:
    """Per-domain token-bucket so a slow site can't hold back faster ones.

    Each domain gets an independent bucket. Default rate is generous (5 req/s,
    burst 10) but per-domain Crawl-delay from robots.txt overrides it. Thread-
    safe, lock-per-domain.
    """

    __slots__ = ("_default_rps", "_default_burst", "_buckets", "_lock")

    def __init__(self, default_rps: float = 5.0, default_burst: int = 10) -> None:
        self._default_rps = default_rps
        self._default_burst = default_burst
        # domain -> {"tokens", "last", "rps", "burst", "lock"}
        self._buckets: Dict[str, Dict[str, object]] = {}
        self._lock = RLock()

    def configure_domain(self, domain: str, rps: Optional[float] = None, crawl_delay: float = 0.0) -> None:
        """Set the rate for a specific domain. Use ``crawl_delay`` (seconds)
        from robots.txt -- overrides ``rps`` to ``1/crawl_delay``.
        """
        if not domain:
            return
        if crawl_delay and crawl_delay > 0:
            rps = 1.0 / max(crawl_delay, 0.001)
        if rps is None:
            rps = self._default_rps
        with self._lock:
            bucket = self._get_or_create(domain)
        # Acquire the per-bucket lock before mutating rps/burst so that
        # ``acquire`` (which reads these fields under ``bucket["lock"]``)
        # sees a consistent snapshot. Without this, a concurrent ``acquire``
        # call could read ``rps`` mid-refill and compute an incorrect refill
        # token count (old tokens + elapsed * new rps). The per-bucket lock
        # serialises the write against acquire's read of the same fields.
        with bucket["lock"]:
            bucket["rps"] = float(rps)
            bucket["burst"] = max(1, int(rps))

    def _get_or_create(self, domain: str) -> Dict[str, object]:
        bucket = self._buckets.get(domain)
        if bucket is None:
            bucket = {
                "tokens": float(self._default_burst),
                "last": time.monotonic(),
                "rps": float(self._default_rps),
                "burst": int(self._default_burst),
                "lock": RLock(),
            }
            self._buckets[domain] = bucket
        return bucket

    def acquire(self, domain: str, max_wait: float = 30.0) -> bool:
        """Block (in caller thread) until a token is available for ``domain``.

        Returns ``True`` once acquired, ``False`` if the wait would exceed
        ``max_wait``. Cheap when the bucket has tokens to spare -- typical
        path is a single dict lookup + subtraction.
        """
        if not domain:
            return True
        with self._lock:
            bucket = self._get_or_create(domain)
        bucket_lock = bucket["lock"]
        deadline = time.monotonic() + max_wait
        while True:
            with bucket_lock:
                now = time.monotonic()
                elapsed = now - bucket["last"]
                bucket["tokens"] = min(
                    bucket["burst"],
                    bucket["tokens"] + elapsed * bucket["rps"],
                )
                bucket["last"] = now
                if bucket["tokens"] >= 1.0:
                    bucket["tokens"] -= 1.0
                    return True
                # How long to wait for the next token?
                deficit = 1.0 - bucket["tokens"]
                wait = deficit / max(bucket["rps"], 0.001)
            if time.monotonic() + wait > deadline:
                return False
            time.sleep(min(wait, 1.0))


# --- Coverage email decoders -------------------------------------------------

# Pattern for tightly-concatenated JS strings forming an email:
#   'sec' + 'urity' + '@' + 'example.com'
#   "sec" + "urity@" + "example" + ".com"
_JS_CONCAT_PATTERN = re.compile(
    r"""(?:["']([^"']{1,40})["']\s*\+\s*){1,15}["']([^"']{1,40})["']""",
    re.IGNORECASE,
)
# Belt-and-braces input cap for ``decode_js_concat_emails``. The pattern
# itself uses bounded quantifiers ({1,40} and {1,15}) and is NOT vulnerable
# to catastrophic backtracking -- empirical: 5 000 candidate segments parse
# in <2 ms on a laptop. The cap exists to bound worst-case linear cost on
# pathological minified scripts (multi-megabyte single-line JS bundles), not
# to fix a ReDoS that does not exist in this regex.
_JS_CONCAT_MAX_INPUT_CHARS = 50_000
_PHONE_PATTERN = re.compile(
    r"(?:\+?\d{1,3}[\s.-]?)?(?:\(?\d{2,4}\)?[\s.-]?)?\d{3,4}[\s.-]?\d{3,4}(?:[\s.-]?\d{2,4})?"
)


# Set of low-ASCII codepoints we want to decode out of ``\uXXXX``
# escapes BEFORE running the email regex. Modern frameworks (Next.js,
# Nuxt, etc.) embed pre-rendered HTML into ``<script>`` tags as JSON;
# every ``<``, ``>``, ``&``, ``"``, ``/`` becomes ``\u003c``,
# ``\u003e``, ``\u0026``, ``\u0022``, ``\u002f``. The regex word-boundary
# does NOT trip between ``e`` (last char of ``u003e``) and ``s`` (first
# char of ``support``), so the local-part is silently extracted as
# ``u003esupport``. Pre-decoding these escapes restores the byte
# boundary the regex expects (``>support`` -> ``>`` is not a word char,
# so the local part starts at ``s``).
_JSON_ESCAPE_DECODE_MAP: Dict[str, str] = {}
for _ord in range(0x20, 0x7F):
    if chr(_ord).isalnum() or chr(_ord) in "._%+-":
        # NEVER decode chars that ARE valid in an email local-part.
        continue
    _JSON_ESCAPE_DECODE_MAP[f"\\u{_ord:04x}"] = chr(_ord)
    _JSON_ESCAPE_DECODE_MAP[f"\\u{_ord:04X}"] = chr(_ord)
for _seq, _ch in (("\\u000a", "\n"), ("\\u000d", "\r"), ("\\u0009", "\t")):
    _JSON_ESCAPE_DECODE_MAP[_seq] = _ch
    _JSON_ESCAPE_DECODE_MAP[_seq.upper()] = _ch
del _ord, _seq, _ch
_JSON_ESCAPE_DECODE_RE = re.compile(
    "(" + "|".join(re.escape(k) for k in _JSON_ESCAPE_DECODE_MAP) + ")",
)


def _decode_json_unicode_escapes_for_email_extraction(text: str) -> str:
    """Decode ``\\uXXXX`` JSON escape sequences for email extraction.

    Only decodes a small whitelisted set of low-ASCII codepoints
    (delimiters / whitespace / non-alnum punctuation). This is
    intentionally NOT a full ``codecs.decode(..., 'unicode_escape')``
    -- a full decode could change the meaning of arbitrary text and
    would also decode escapes inside legitimately-displayed strings.
    The whitelist approach restores word-boundary semantics for the
    email regex without materially altering the rest of the document.

    Returns ``text`` unchanged if no escapes are present (fast path).
    """
    if not text or "\\u" not in text:
        return text
    return _JSON_ESCAPE_DECODE_RE.sub(
        lambda m: _JSON_ESCAPE_DECODE_MAP[m.group(0)], text,
    )


# Local-part prefixes that indicate an extraction artefact slipped
# through normalization (e.g. someone embedded the email in a
# percent-encoded URL or a non-standard encoding we did not
# anticipate). These are checked AFTER ``email.lower()`` so the
# comparison is case-insensitive.
_EMAIL_LOCAL_PART_ARTEFACT_PREFIXES: Tuple[str, ...] = (
    "u003e", "u003c", "u0026", "u002f", "u0022", "u0027", "u0020",
    "x3e", "x3c", "x26", "x2f",
    "0x3e", "0x3c", "0x26", "0x2f",
)


def _looks_like_extraction_artefact(local_part: str) -> bool:
    """True if ``local_part`` starts with a known encoding artefact.

    See ``_EMAIL_LOCAL_PART_ARTEFACT_PREFIXES`` for the list. Used as
    a defence-in-depth filter AFTER pre-decoding JSON escapes.
    """
    if not local_part:
        return False
    lp = local_part.lower()
    for pfx in _EMAIL_LOCAL_PART_ARTEFACT_PREFIXES:
        if lp.startswith(pfx.lower()):
            return True
    return False


