def prompt_with_timeout(prompt, timeout, default):
    """
    Displays a prompt and waits for user input. If no input is received
    within the timeout, it returns the default value.

    Handles EOF on stdin (non-interactive terminal / piped input):
    when ``readline()`` returns an empty string the function falls through
    to the default path rather than returning an empty string to the caller.
    """
    print(prompt, end='', flush=True)

    # Both msvcrt (Windows) and select (POSIX) are best-effort imports at the
    # top of the module. If both failed (extremely rare -- frozen embedded
    # Python build, locked-down sandbox, etc.), we cannot poll stdin without
    # blocking forever, so honour the timeout immediately by returning the
    # default. Prior code unconditionally dereferenced `select` and
    # TypeError'd in that scenario.
    if os.name == 'nt':
        if msvcrt is None:
            print(f"\n[!] Interactive input unavailable (msvcrt missing); using default '{default}'.")
            return default
        start_time = time.time()
        while time.time() - start_time < timeout:
            if msvcrt.kbhit():
                first_char = msvcrt.getche().decode(errors='ignore')
                line = first_char + sys.stdin.readline().strip()
                print()
                if line:
                    return line
                # Empty line -- EOF / pipe closed; fall through to default.
                break
            time.sleep(0.1)
    else:
        if select is None:
            print(f"\n[!] Interactive input unavailable (select missing); using default '{default}'.")
            return default
        try:
            rlist, _, _ = select.select([sys.stdin], [], [], timeout)
        except (ValueError, OSError):
            rlist = []
        if rlist:
            try:
                line = sys.stdin.readline().rstrip('\n')
            except UnicodeDecodeError:
                line = ""
            if line:
                return line
            # EOF (stdin closed / pipe ended / non-interactive terminal):
            # treat the same as a timeout and fall through to default.
            # Without this guard, piping ``echo "" | python mailrake.py`` or
            # running in a CI environment where stdin is at EOF would
            # return an empty string instead of the configured default.

    print(f"\n[!] No input received within {timeout} seconds. Proceeding with default action ('{default}')...")
    return default

def setup_output_directory():
    """Creates a unique directory for the current run and returns its path.

    Race-safe: previously the read-then-create pattern allowed two
    concurrent processes (a manual run and a monitoring loop, or two
    cronjobs that fired at the same minute) to pick the same run number,
    racing into each other's output. We now use ``os.mkdir`` (atomic and
    fails with ``FileExistsError`` if the directory already exists) inside
    a bounded retry loop so each process is guaranteed to claim a unique
    run number.
    """
    root_output_dir = "output"
    today_str = datetime.now().strftime('%Y-%m-%d')
    base_dir = os.path.join(os.getcwd(), root_output_dir, today_str)

    os.makedirs(base_dir, exist_ok=True)

    last_good_run_number = 0
    highest_existing_run = 0
    i = 1
    while True:
        run_dir_path = os.path.join(base_dir, str(i))
        if os.path.exists(run_dir_path):
            highest_existing_run = i
            try:
                json_dir = os.path.join(run_dir_path, "JSON")
                csv_dir = os.path.join(run_dir_path, "CSV")
                has_results_in_json = os.path.isdir(json_dir) and len(os.listdir(json_dir)) > 0
                has_results_in_csv = os.path.isdir(csv_dir) and len(os.listdir(csv_dir)) > 0

                if has_results_in_json or has_results_in_csv:
                    last_good_run_number = i
            except OSError:
                pass
            i += 1
        else:
            break

    candidate = last_good_run_number + 1

    # Up to 100 attempts to claim an unused run number atomically. In
    # practice we win on the first try; the loop only matters when two
    # processes start within the same wall-clock millisecond.
    for _ in range(100):
        # Clean up any incomplete runs that sit between our candidate
        # number and the highest existing one. Best-effort: a peer process
        # may already own one of these directories, in which case we just
        # skip ahead and let it keep its run.
        #
        # SAFETY: we only delete directories that are older than 30 minutes
        # (based on directory mtime). This prevents a TOCTOU race where a
        # peer process creates the directory but has not yet written its
        # CSV/JSON output files -- we would see the directory as "empty"
        # and delete it out from under the peer. The 30-minute grace window
        # is well below the typical crawl duration (>1 hour) but long
        # enough that any directory left empty for that long is almost
        # certainly a stale/crashed run. Peer-created directories are
        # typically only empty for a few seconds (between os.mkdir and
        # the first save_results call).
        _cleanup_cutoff = time.time() - 30 * 60
        for num_to_delete in range(candidate, highest_existing_run + 1):
            dir_to_delete = os.path.join(base_dir, str(num_to_delete))
            if os.path.exists(dir_to_delete):
                try:
                    # Age guard: skip directories younger than 30 min
                    # (may be actively written by a peer process).
                    dir_mtime = os.path.getmtime(dir_to_delete)
                    if dir_mtime > _cleanup_cutoff:
                        continue
                    json_dir = os.path.join(dir_to_delete, "JSON")
                    csv_dir = os.path.join(dir_to_delete, "CSV")
                    has_results = (
                        (os.path.isdir(json_dir) and len(os.listdir(json_dir)) > 0)
                        or (os.path.isdir(csv_dir) and len(os.listdir(csv_dir)) > 0)
                    )
                    if has_results:
                        # Peer process beat us to it -- bump candidate.
                        continue
                    print(f"[*] Removing incomplete run directory: {dir_to_delete}")
                    shutil.rmtree(dir_to_delete)
                except OSError as e:
                    print(f"[!] Warning: Could not delete directory {dir_to_delete}. Error: {e}")

        run_dir = os.path.join(base_dir, str(candidate))
        try:
            os.mkdir(run_dir)
            print(f"[*] Results for this run will be saved in: {run_dir}")
            return run_dir
        except FileExistsError:
            # Another process won the race for this slot. Bump and retry.
            candidate += 1
            highest_existing_run = max(highest_existing_run, candidate)

    # Last-ditch fallback: timestamped directory so we *never* return
    # someone else's run dir.
    fallback = os.path.join(base_dir, datetime.now().strftime('%Y%m%d-%H%M%S-%f'))
    os.makedirs(fallback, exist_ok=True)
    print(f"[!] Run-number race never resolved -- using fallback dir: {fallback}")
    return fallback

def _deep_merge_settings(base: Dict, overlay: Dict) -> None:
    """Recursive deep-merge: ``overlay`` keys overwrite ``base`` keys.
    Nested dicts at the same key recurse. All other leaf values from
    ``overlay`` replace the corresponding ``base`` value.

    This is a one-way merge: ``overlay`` wins on every key it defines.
    Keys present in ``base`` but absent from ``overlay`` are preserved.
    """
    for k, v in overlay.items():
        if isinstance(v, dict) and isinstance(base.get(k), dict):
            _deep_merge_settings(base[k], v)
        else:
            base[k] = v


def save_settings(settings_dict, filepath):
    """Saves the settings dictionary to a JSON file, converting sets to lists.

    Atomic write: writes to ``filepath + '.tmp'`` then renames over the real
    path, so a crash mid-write never corrupts the config file.
    """
    serializable_settings = {}
    for key, value in settings_dict.items():
        if isinstance(value, dict):
            serializable_settings[key] = {}
            for sub_key, sub_value in value.items():
                if isinstance(sub_value, set):
                    serializable_settings[key][sub_key] = sorted(list(sub_value))
                else:
                    serializable_settings[key][sub_key] = sub_value
        else:
            serializable_settings[key] = value

    tmppath = filepath + ".tmp"
    with open(tmppath, 'w', encoding='utf-8') as f:
        json.dump(serializable_settings, f, indent=2)
        f.flush()
        os.fsync(f.fileno())
    try:
        os.replace(tmppath, filepath)
    except OSError:
        import shutil as _shutil
        _shutil.move(tmppath, filepath)

def load_settings(filepath, default_settings):
    """Loads settings from a JSON file, creating it from defaults if it doesn't exist.

    Returns a **deep copy** of the merged result so that mutating the returned
    dict never corrupts the caller's ``default_settings`` object (bug-fix #10:
    original code assigned ``top_default`` by reference which aliased the two).
    """
    import copy as _copy
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            loaded_settings = json.load(f)
            if not isinstance(loaded_settings, dict):
                raise json.JSONDecodeError("File is not a valid JSON object", "", 0)

            # Deep-copy the defaults so we never alias them.
            merged = _copy.deepcopy(default_settings)

            # Type-corruption guard: if a loaded value has a different
            # type than we expect for a top-level key, skip the merge
            # for that key and keep the full default. This handles the
            # case where someone manually corrupts the JSON (e.g.
            # ``"verifier_settings": "broken_string"``). Without this
            # guard the recursive merge would blindly replace the
            # nested dict with the corrupt value, and downstream code
            # expecting a dict would crash with ``TypeError``.
            for top_key, top_default in default_settings.items():
                loaded_val = loaded_settings.get(top_key)
                if isinstance(top_default, dict) and not isinstance(loaded_val, dict):
                    loaded_settings[top_key] = _copy.deepcopy(top_default)

            # Recursive deep-merge: overlay loaded values on top of defaults.
            # Keys present in the loaded file replace or supplement the
            # default; keys missing from the loaded file keep the default value.
            _deep_merge_settings(merged, loaded_settings)

            # Convert lists back to sets for settings that use them as
            # unordered collections (proactive paths, email prefix lists, etc.).
            # This is safe because no current setting depends on list ordering
            # (verified against all code paths that consume these settings).
            for top_key, top_value in merged.items():
                if isinstance(top_value, dict):
                    for sub_key, sub_value in top_value.items():
                        if isinstance(sub_value, list):
                            merged[top_key][sub_key] = set(sub_value)
            return merged
    except (json.JSONDecodeError, IOError, FileNotFoundError):
        if not os.path.exists(filepath):
            print(f"[*] Creating default settings file at '{filepath}'")
        else:
            print(f"[!] Warning: Could not read or parse '{filepath}'. Using default settings and attempting to recreate.")
        save_settings(default_settings, filepath)
        return _copy.deepcopy(default_settings)

def display_list(name, item_list):
    print(f"\n--- Current {name} ---")
    if not item_list:
        print(" (empty)")
    else:
        for item in sorted(list(item_list)):
            print(f"- {item}")
    print("-" * (len(name) + 14))

def modify_list(name, item_list, settings_dict, settings_filepath, is_path=False):
    """Modifies a list and saves the entire settings dictionary."""
    while True:
        display_list(name, item_list)
        action = input(f"Choose action for {name}: [a]dd, [r]emove, [b]ack to settings menu: ").lower()
        if action == 'a':
            new_item = input("Enter item to add: ").strip().lower()
            if not new_item:
                print("Cannot add an empty item.")
                continue

            if is_path:
                if not new_item.startswith('/'):
                    new_item = '/' + new_item
            elif 'provider' in name.lower():
                if '.' not in new_item or new_item.startswith('.') or new_item.endswith('.'):
                    print("[!] Invalid entry. Provider must be a valid domain (e.g., 'outlook.com').")
                    continue
            
            item_list.add(new_item)
            save_settings(settings_dict, settings_filepath)
            print(f"'{new_item}' added and settings saved.")

        elif action == 'r':
            item_to_remove = input("Enter exact item to remove: ").strip().lower()
            if item_to_remove in item_list:
                item_list.remove(item_to_remove)
                save_settings(settings_dict, settings_filepath)
                print(f"'{item_to_remove}' removed and settings saved.")
            else:
                print(f"'{item_to_remove}' not found in the list.")
        elif action == 'b':
            break
        else:
            print("Invalid choice. Please enter 'a', 'r', or 'b'.")

