def edit_auth_smtp_settings(settings, settings_filepath):
    vs = settings['verifier_settings']
    while True:
        print("\n--- Authenticated SMTP Settings ---")
        print("NOTE: This method will use your provided SMTP server to relay checks.\n")
        print(f"  1. SMTP Host:        {vs.get('smtp_host', 'N/A')}")
        print(f"  2. SMTP Port:        {vs.get('smtp_port', 'N/A')}")
        print(f"  3. SMTP User:        {vs.get('smtp_user', 'N/A')}")
        print(f"  4. SMTP Pass:        {'*' * len(vs.get('smtp_pass', '')) if vs.get('smtp_pass') else 'N/A'}")
        print(f"  5. Use TLS:          {'Yes' if vs.get('smtp_tls') else 'No'}")
        print("\n[e]dit, [b]ack")
        
        choice = input("Enter choice: ").lower()

        if choice == 'e':
            def get_input(prompt, current_value):
                val = input(prompt).strip()
                if val.lower() == 'none':
                    return ""
                return val or current_value

            settings['verifier_settings']['smtp_host'] = get_input(f"Enter SMTP Host [current: {vs.get('smtp_host', '')}]: ", vs.get('smtp_host', ''))
            try:
                port_str = get_input(f"Enter SMTP Port [current: {vs.get('smtp_port', '')}]: ", str(vs.get('smtp_port', '')))
                settings['verifier_settings']['smtp_port'] = int(port_str) if port_str else int(vs.get('smtp_port', 587))
            except ValueError:
                print("[!] Invalid port; keeping current value.")
            settings['verifier_settings']['smtp_user'] = get_input(f"Enter SMTP User [current: {vs.get('smtp_user', '')}]: ", vs.get('smtp_user', ''))
            try:
                import getpass as _gp
                settings['verifier_settings']['smtp_pass'] = _gp.getpass(f"Enter SMTP Pass [current: {'*' * len(vs.get('smtp_pass', ''))}]: ")
            except Exception:
                settings['verifier_settings']['smtp_pass'] = get_input(f"Enter SMTP Pass (WARNING — typing will echo) [current: {'*' * len(vs.get('smtp_pass', ''))}]: ", vs.get('smtp_pass', ''))
            
            current_tls_str = 'y' if vs.get('smtp_tls') else 'n'
            tls_choice = input(f"Use TLS? (y/n) [current: {current_tls_str}]: ").lower() or current_tls_str
            settings['verifier_settings']['smtp_tls'] = tls_choice.startswith('y')
            save_settings(settings, settings_filepath)
            print("Authenticated SMTP settings updated.")
        elif choice == 'b':
            break
        else:
            print("Invalid choice.")
            
