def format_duration(seconds):
    seconds = int(seconds)
    hours, remainder = divmod(seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    parts = []
    if hours > 0:
        parts.append(f"{hours} hour{'s' if hours != 1 else ''}")
    if minutes > 0:
        parts.append(f"{minutes} minute{'s' if minutes != 1 else ''}")
    if seconds > 0 or not parts:
        parts.append(f"{seconds} second{'s' if seconds != 1 else ''}")
    return ", ".join(parts)

def file_browser():
    """Presents an interactive file browser to select a .txt or .csv file."""
    current_path = os.getcwd()
    while True:
        print(f"\n--- Select Input File ---")
        print(f"Current Directory: {current_path}")
        
        try:
            items = os.listdir(current_path)
            dirs = sorted([d for d in items if os.path.isdir(os.path.join(current_path, d))])
            files = sorted([f for f in items if f.lower().endswith(('.txt', '.csv'))])

            display_items = dirs + files
            
            if not display_items and current_path == os.getcwd():
                 print("\nError: No sub-directories or supported files (.txt, .csv) found.")
                 return None

            print(" [0] Go Up One Level (..)")
            for i, item_name in enumerate(display_items, 1):
                item_path = os.path.join(current_path, item_name)
                prefix = "[D]" if os.path.isdir(item_path) else "   "
                print(f" [{i}] {prefix} {item_name}")
            
            choice_str = input(f"\nEnter number to select, or 'q' to quit: ")
            if choice_str.lower() == 'q':
                return None
            if not choice_str:
                continue
            
            choice = int(choice_str)

            if choice == 0:
                current_path = os.path.dirname(current_path)
            elif 1 <= choice <= len(display_items):
                selected_item = display_items[choice - 1]
                selected_path = os.path.join(current_path, selected_item)
                if os.path.isdir(selected_path):
                    current_path = selected_path
                else: 
                    return selected_path
            else:
                print("Invalid number, please try again.")
        
        except ValueError:
            print("Please enter a valid number.")
        except FileNotFoundError:
            print(f"Error: Directory not found. Returning to home.")
            current_path = os.getcwd()
        except Exception as e:
            print(f"An error occurred: {e}")
            return None

def _get_col_idx(col_letter):
    if not col_letter:
        return -1
    col_letter = col_letter.upper().strip()
    idx = 0
    for c in col_letter:
        if 'A' <= c <= 'Z':
            idx = idx * 26 + (ord(c) - ord('A') + 1)
        else:
            return -1
    return idx - 1

def read_emails_from_file(filepath, prompt_user=True, has_header=True, **defaults):
    email_tasks = []
    if not os.path.exists(filepath):
        print(f"[!] Error: Input file not found at '{filepath}'")
        return []

    if filepath.endswith('.txt'):
        with open(filepath, 'r', encoding='utf-8') as f:
            for line in f:
                if line.strip():
                    email_tasks.append((line.strip(), 'unknown', None))
    elif filepath.endswith('.csv'):
        def get_col_idx(col_letter):
            return _get_col_idx(col_letter)

        email_col_idx, classification_col_idx, domain_col_idx = -1, -1, -1

        if prompt_user:
            while True:
                domain_col_letter = (input("Enter column for source domain [default: A]: ") or 'A').upper()
                if not domain_col_letter:
                    domain_col_idx = -1
                    break
                domain_col_idx = get_col_idx(domain_col_letter)
                if domain_col_idx != -1: break
                else: print("Invalid column letter. Please try again.")

            while True:
                email_col_letter = (input("Enter the column letter for emails [default: B]: ") or 'B').upper()
                email_col_idx = get_col_idx(email_col_letter)
                if email_col_idx != -1: break
                else: print("Invalid column letter. Please try again.")
            
            while True:
                classification_col_letter = (input("Enter column for classification [default: C]: ") or 'C').upper()
                if not classification_col_letter:
                    classification_col_idx = -1
                    break
                classification_col_idx = get_col_idx(classification_col_letter)
                if classification_col_idx != -1: break
                else: print("Invalid column letter. Please try again.")
        else:
            email_col_idx = get_col_idx(defaults.get('email_col_default'))
            classification_col_idx = get_col_idx(defaults.get('classification_col_default'))
            domain_col_idx = get_col_idx(defaults.get('domain_col_default'))

        with open(filepath, 'r', encoding='utf-8-sig') as f:
            reader = csv.reader(f)
            if has_header:
                next(reader, None)
            for _row_num, row in enumerate(reader, start=1):
                try:
                    email = row[email_col_idx].strip() if email_col_idx != -1 and email_col_idx < len(row) else None
                    
                    classification = 'unknown'
                    if classification_col_idx != -1 and classification_col_idx < len(row):
                        classification = row[classification_col_idx].strip().lower()
                    
                    source_domain = row[domain_col_idx].strip() if domain_col_idx != -1 and domain_col_idx < len(row) else None
                    
                    if email:
                        email_tasks.append((email, classification, source_domain))
                except IndexError:
                    logger.warning(
                        "[read_emails] skipping malformed row %d in %s (expected columns: email=%d, classification=%d, domain=%d; got %d fields)",
                        _row_num, filepath, email_col_idx, classification_col_idx, domain_col_idx, len(row),
                    )
                    continue
    return email_tasks


def run_verifier_standalone(settings):
    print("\n--- Run Email Verifier ---")
    input_file = file_browser()
    if not input_file:
        print("No file selected. Returning to main menu.")
        return
        
    email_tasks = read_emails_from_file(input_file)
    if not email_tasks:
        print("No emails found in the selected file.")
        return
    
    vs = settings['verifier_settings']
    default_mode = vs.get('default_verification_mode', 'direct')
    mode_prompt_map = {'direct': '1', 'auth': '2'}
    default_concurrency = vs.get('default_concurrency', 100)
    
    while True:
        mode_choice = input(f"Choose verification method: [1] Direct Check, [2] Authenticated SMTP [default: {default_mode}]: ") or mode_prompt_map[default_mode]
        if mode_choice == '1':
            mode = 'direct'
            break
        elif mode_choice == '2':
            mode = 'auth'
            break
        else:
            print("Invalid choice. Please enter 1 or 2.")

    out_path_name = input("Enter name for the output results CSV file (e.g., verified_emails.csv): ")
    if not out_path_name:
        print("Output file name cannot be empty. Aborting.")
        return
    
    while True:
        try:
            concurrency_str = input(f"Enter concurrency (how many to check at once) [default: {default_concurrency}]: ") or str(default_concurrency)
            concurrency = int(concurrency_str)
            break
        except ValueError:
            print("Invalid input. Please enter a number.")
    
    while True:
        try:
            delay_str = input("Enter delay in seconds after each check [default: 0]: ") or '0'
            delay = int(delay_str)
            break
        except ValueError:
            print("Invalid input. Please enter a number.")
    
    verifier_output_dir = setup_output_directory()
    csv_output_dir = os.path.join(verifier_output_dir, "CSV")
    os.makedirs(csv_output_dir, exist_ok=True)
    final_out_path = os.path.join(csv_output_dir, out_path_name)

    verifier = AsyncEmailVerifier(settings)
    asyncio.run(verifier.run(email_tasks, final_out_path, concurrency, delay, mode))

def normalize_domain(raw: Optional[str]) -> Optional[str]:
    """Normalize a free-form domain/URL into a bare host suitable for crawling.

    Accepts any of:  ``example.com``, ``http://example.com``, ``https://www.example.com``,
    ``www.example.com/contact``, ``example.com:8080/path?x=1#frag``,
    ``HTTPS://Example.COM/.``, etc.

    Returns the lowercased host (no scheme, no ``www.``, no path/query/port/trailing dot)
    or ``None`` if the input is empty / not a parseable host.
    """
    if not raw:
        return None
    s = str(raw).strip()
    if not s:
        return None
    # Drop comments (anything after '#') so '# comment' lines in TXT files are ignored.
    s = s.split("#", 1)[0].strip()
    if not s:
        return None
    # Reject HTML / CSS / JS lines outright. When a Google Sheet is private,
    # the export endpoint returns the sign-in HTML page instead of CSV;
    # csv.reader then yields rows that are giant CSS / JS blobs whose first
    # cell starts with '<' or '{' or 'function'. ``urlparse`` would chew on
    # those for milliseconds before raising. Reject early.
    # Reject obvious HTML / CSS / JS rows. Don't list "//" here because
    # ``//example.com`` is a legitimate protocol-relative input.
    if s[0] in "<{}[]" or s.startswith(("function", "var ", "/*", "@media")):
        return None
    # Make sure urlparse sees a scheme so it parses the host correctly.
    # Don't double-prepend on already-protocol-relative inputs ("//foo.com").
    if "://" not in s and not s.startswith("//"):
        s = "//" + s
    # Python 3.12's ``urlsplit`` raises ``ValueError`` (instead of returning
    # a parsed result with a bad host) when it sees a bracketed token like
    # ``[b]`` -- the hostname-validator now strict-checks bracketed values
    # against ``ipaddress.ip_address``. Pre-3.12 versions just returned an
    # empty hostname for the same input. Catch the exception so a single
    # malformed cell in a sheet does not abort the entire import.
    try:
        parsed = urlparse(s, scheme="http")
    except ValueError:
        return None
    try:
        host_attr = parsed.hostname
    except ValueError:
        # ``parsed.hostname`` is itself a property that re-validates the
        # bracketed value on access (Python 3.12). Belt-and-braces.
        return None
    host = (host_attr or "").strip(".").lower()
    if not host:
        return None
    # Reject IPv6 bracket notation. ``parsed.hostname`` successfully extracts
    # ``[::1]`` / ``[2001:db8::1]``, but the crawler's internal domain maps
    # use dot-separated hostnames as keys, and the crawler does not support
    # IPv6-native HTTP connections. Rather than silently dropping (which
    # confuses users when a domain from their list never gets crawled), we
    # emit a one-line informational message and return None.
    if host.startswith("[") or host.endswith("]"):
        logger.info("[normalize_domain] IPv6 literal rejected (not supported by this crawler): %s", raw)
        return None
    if host.startswith("www."):
        host = host[4:]
    # Reject anything that isn't a plausible domain (no dot, IP literals, etc.).
    if "." not in host:
        return None
    if all(part.isdigit() for part in host.split(".")):
        return None  # IPv4 literal -- not a crawlable domain in this context
    return host


def normalize_domain_list(raw_domains) -> List[str]:
    """Normalize an iterable of raw domain strings, deduping and preserving order.

    Defence-in-depth: ``normalize_domain`` already swallows the most common
    parser exceptions, but a single malformed row in a 50k-line input file
    must NEVER abort the entire crawl. Wrap each call so any unexpected
    exception is logged at debug level and the row is dropped.
    """
    seen = set()
    out: List[str] = []
    for raw in raw_domains:
        try:
            norm = normalize_domain(raw)
        except Exception as e:
            logger.debug(
                "[normalize_domain_list] dropped row %r: %s", raw, e,
            )
            continue
        if not norm or norm in seen:
            continue
        seen.add(norm)
        out.append(norm)
    return out


_GOOGLE_SHEET_RE = re.compile(
    r"https?://docs\.google\.com/spreadsheets(?:/u/\d+)?/d/([a-zA-Z0-9_-]+)",
    re.IGNORECASE,
)


def is_google_sheet_url(s: Optional[str]) -> bool:
    """Return True iff `s` looks like a Google Sheet URL."""
    if not s:
        return False
    return bool(_GOOGLE_SHEET_RE.search(str(s).strip()))


def load_domains_from_path(path: str) -> List[str]:
    """Load and normalize domains from a `.txt` (one per line) or `.csv` (first column).

    Returns a deduped, normalized list. Returns [] if file missing or empty.
    """
    if not os.path.exists(path):
        logger.error("Input file not found: %s", path)
        print(f"[!] Input file not found: {path}")
        return []
    raw: List[str] = []
    try:
        if path.lower().endswith(".csv"):
            with open(path, "r", encoding="utf-8-sig", newline="") as f:
                reader = csv.reader(f)
                # CSV header detection: if the first cell is not a plausible host, skip it.
                rows = list(reader)
                if rows and rows[0] and normalize_domain(rows[0][0]) is None:
                    rows = rows[1:]
                for row in rows:
                    if row and row[0]:
                        raw.append(row[0])
        else:
            with open(path, "r", encoding="utf-8") as f:
                raw = [line for line in f if line.strip()]
    except Exception as e:
        _log_exception("input_loader", e)
        return []
    domains = normalize_domain_list(raw)
    if not domains:
        logger.warning("No valid domains parsed from %s", path)
    else:
        logger.info("Loaded %d unique domain(s) from %s", len(domains), path)
    return domains


def get_domains_from_google_sheet(sheet_url):
    """Fetches and parses domains from the first column of a public Google Sheet.

    Domains are normalized via :func:`normalize_domain` so entries like
    ``https://Example.com/contact`` and ``www.example.com`` collapse to ``example.com``.
    """
    logger.info(f"Fetching domains from Google Sheet: {sheet_url}")
    print(f"[*] Fetching domains from Google Sheet...")
    try:
        match = _GOOGLE_SHEET_RE.search(sheet_url)
        if not match:
            logger.error("Invalid Google Sheet URL format. Could not find sheet ID.")
            print("[!] Invalid Google Sheet URL. Expected the standard /spreadsheets/d/<id>/ form.")
            return []
        sheet_id = match.group(1)

        # Preserve any explicit gid= so multi-tab sheets work.
        gid_match = re.search(r"[?#&]gid=(\d+)", sheet_url)
        csv_url = f"https://docs.google.com/spreadsheets/d/{sheet_id}/export?format=csv"
        if gid_match:
            csv_url += f"&gid={gid_match.group(1)}"

        # Use the stealth session so the Sheet fetch carries the same
        # rotating browser fingerprint as the rest of the crawler. Falls
        # back transparently to plain ``requests`` when curl_cffi is
        # unavailable, so this is no worse than the prior code path.
        # Close the session in a ``finally`` so the underlying connection
        # pool is released promptly -- in ``--url`` monitoring mode this
        # function is called repeatedly and we don't want sessions to
        # accumulate while waiting on GC.
        response = None
        stealth = None
        try:
            try:
                stealth = _StealthSession()
                response = stealth.get(
                    csv_url,
                    timeout=30,
                    allow_redirects=True,
                    headers=random_browser_headers(),
                )
            except Exception:
                # Defensive fallback: if the stealth session itself errors
                # out (e.g. transient resolver failure), use bare requests
                # so a Sheet fetch never silently fails for fingerprint
                # reasons.
                response = requests.get(csv_url, timeout=30)
            if response is None:
                logger.error("[google_sheet] both stealth and plain requests failed")
                print("[!] Failed to fetch Google Sheet CSV data.")
                return []
            response.raise_for_status()
        finally:
            if stealth is not None:
                try:
                    stealth.close()
                except Exception:
                    pass
            if response is not None:
                try:
                    response.close()
                except Exception:
                    pass

        if response is None:
            return []
        content = response.content.decode("utf-8", errors="replace")

        # Detect a private-sheet redirect to the Google sign-in page.
        # When the sheet is NOT shared "Anyone with the link can view",
        # the export endpoint serves an HTML login page (200 OK,
        # text/html). Parsing that as CSV would otherwise yield rows
        # of CSS / JS that ``normalize_domain`` would have to reject
        # one-by-one -- expensive AND it surfaced a urlparse crash
        # on Python 3.12. Detect explicitly so the user sees a
        # clear, actionable error.
        ct = ""
        try:
            headers_obj = getattr(response, "headers", {}) or {}
            ct = (headers_obj.get("Content-Type") or headers_obj.get("content-type") or "").lower()
        except Exception:
            ct = ""
        looks_like_html = (
            "text/html" in ct
            or content[:200].lstrip().lower().startswith(("<!doctype", "<html", "<style", "<script"))
        )
        if looks_like_html:
            logger.error(
                "[google_sheet] export endpoint returned HTML (likely "
                "private sheet); content-type=%r", ct,
            )
            print(
                "[!] The Google Sheet appears to be PRIVATE -- the export\n"
                "    endpoint returned an HTML sign-in page instead of CSV.\n"
                "    Either share the sheet 'Anyone with the link can view',\n"
                "    or export it locally and pass the resulting file as the\n"
                "    first positional argument:\n\n"
                f"      curl -sL '{csv_url}' -o /tmp/sheet.csv  # will need cookies\n"
                "      # OR: File -> Download -> CSV from the Sheets UI"
            )
            return []

        csv_file = io.StringIO(content)
        reader = csv.reader(csv_file)

        raw_first_column = [row[0] for row in reader if row and row[0].strip()]
        domains = normalize_domain_list(raw_first_column)

        logger.info("Successfully fetched %d unique domain(s) from the Google Sheet.", len(domains))
        print(f"[*] Sheet -> {len(domains)} unique normalized domain(s).")
        return domains

    except _HTTP_EXC_TYPES as e:
        # ``_HTTP_EXC_TYPES`` covers both ``requests.RequestException`` AND
        # the curl_cffi equivalent. Without this, when curl_cffi is the
        # active Tier-1 backend, ``raise_for_status()`` raises a
        # ``curl_cffi.requests.errors.RequestsError`` which does NOT
        # inherit from ``requests.exceptions.RequestException`` -- so the
        # dedicated HTTP-error handler was dead code and errors fell
        # through to the generic "parsing" branch with a misleading
        # message.
        logger.error(f"Failed to fetch Google Sheet content: {e}")
        print(f"[!] Error: Failed to fetch Google Sheet content: {e}")
        return []
    except Exception as e:
        _log_exception("google_sheet", e)
        print(f"[!] Error: An error occurred while parsing the Google Sheet: {e}")
        return []

def run_cleanup(output_root_dir):
    """
    Deletes run folders created by --url runs that are older than 48 hours.
    Does not touch runs created by file-based inputs.
    """
    logger.info("Checking if cleanup of old URL-based runs is needed...")
    print("[*] Performing periodic cleanup check...")
    forty_eight_hours_ago = datetime.now() - timedelta(hours=48)
    
    if not os.path.isdir(output_root_dir):
        return

    for date_folder_name in os.listdir(output_root_dir):
        date_folder_path = os.path.join(output_root_dir, date_folder_name)
        
        if date_folder_name == "Nixon-S master folder" or not os.path.isdir(date_folder_path):
            continue
            
        try:
            folder_date = datetime.strptime(date_folder_name, '%Y-%m-%d')
            if folder_date < forty_eight_hours_ago:
                for run_folder_name in os.listdir(date_folder_path):
                    run_folder_path = os.path.join(date_folder_path, run_folder_name)
                    marker_file = os.path.join(run_folder_path, '.url_run_marker')
                    
                    if os.path.isdir(run_folder_path) and os.path.exists(marker_file):
                        print(f"[*] CLEANUP: Removing old URL-based run directory: {run_folder_path}")
                        logger.info(f"CLEANUP: Removing old URL-based run directory: {run_folder_path}")
                        if os.path.islink(run_folder_path):
                            os.unlink(run_folder_path)
                        else:
                            shutil.rmtree(run_folder_path)
                
                if not os.listdir(date_folder_path):
                    print(f"[*] CLEANUP: Removing empty date directory: {date_folder_path}")
                    logger.info(f"CLEANUP: Removing empty date directory: {date_folder_path}")
                    os.rmdir(date_folder_path)

        except (ValueError, OSError) as e:
            logger.warning(f"Could not process or perform cleanup in folder '{date_folder_name}': {e}")

def run_scraper_instance(domains, args, settings, proxies, is_url_run=False, master_folder_path=None):
    """Encapsulates the logic for a single crawl and verify run."""
    # PR #6: stamp every run with a deterministic ID so all downstream
    # artifacts (history DB, metadata.json, webhook payload) tie together.
    run_id = uuid.uuid4().hex[:32]
    run_started_ts = time.time()
    if args.exclude:
        try:
            with open(args.exclude, 'r') as f:
                exclusions = {line.strip().lower() for line in f if line.strip()}
            original_count = len(domains)
            domains = [d for d in domains if not any(d.lower().endswith(p) for p in exclusions)]
            skipped_count = original_count - len(domains)
            if skipped_count > 0:
                print(f"Skipped {skipped_count} domains based on the exclusion list.")
        except FileNotFoundError:
            logger.error(f"Exclusion file not found: {args.exclude}")
            return []

    if not domains:
        logger.warning("No valid domains to process for this run.")
        return []

    # Optional pre-screen: HEAD-probe each domain in parallel and skip
    # unreachable / parked / firewalled ones before we waste crawl time on
    # them. Free, fast, and at realistic scale 20-35% of any domain list is
    # dead so this is a material win. We run pre-screen BEFORE opening the
    # history DB so an all-dead list does not register a shutdown callback
    # nor leak a SQLite connection (was: in --url monitoring mode every
    # all-dead cycle leaked a connection + a stale callback).
    if getattr(args, "prescreen", False):
        ps_threads = max(20, args.threads or 20)
        print(f"[+] Pre-screening {len(domains)} domains (HEAD probe, threads={ps_threads}) ...")
        t0 = time.time()
        alive, dead = prescreen_domains(domains, threads=ps_threads, timeout=5.0)
        print(
            f"    -> {len(alive)} alive / {len(dead)} dead "
            f"(skipping dead, saved est. {len(dead) * 5}s of crawl time, "
            f"pre-screen took {time.time() - t0:.1f}s)"
        )
        if dead:
            logger.info("[prescreen] dead domains: %s", ", ".join(dead[:20]) + ("..." if len(dead) > 20 else ""))
        domains = alive
        if not domains:
            logger.warning("Pre-screen: every domain was dead; nothing to crawl.")
            return []

    # PR #6: open the cross-run history DB. Default path lives next to other
    # outputs; can be overridden with --history-db, or disabled with
    # --no-history-db. Errors here never abort the run -- the DB is for
    # observability, not the deliverable.
    history_db: Optional[EmailHistoryDB] = None
    if not bool(getattr(args, "no_history_db", False)):
        try:
            db_path = getattr(args, "history_db", None) or os.path.join("output", "email_history.db")
            history_db = EmailHistoryDB(db_path)
            history_db.start_run(
                run_id=run_id,
                cli_args=" ".join(sys.argv[1:]),
                python_ver=sys.version.split()[0],
                git_sha=_detect_git_sha(),
            )
            # NOTE: we intentionally do NOT register ``history_db.close`` as a
            # SIGTERM shutdown callback here. The ``finally`` block at the end
            # of this function already closes the DB (line ~7945). Registering
            # an additional close callback creates a race: when SIGTERM arrives,
            # the callback closes the DB, but the main thread continues executing
            # and may still call ``history_db.record_email()`` (line ~7839) on
            # the already-closed connection, raising ``ProgrammingError``.
            # The ``finally`` block is guaranteed to run after the signal handler
            # returns (the signal handler only sets a flag and runs callbacks;
            # flow returns to the main thread which eventually reaches ``finally``).
        except Exception as e:
            _log_exception("history_db.init", e)
            history_db = None

    output_dir = setup_output_directory()

    if is_url_run:
        try:
            marker_path = os.path.join(output_dir, '.url_run_marker')
            with open(marker_path, 'w') as f:
                pass 
        except OSError as e:
            logger.error(f"Could not create marker file in {output_dir}: {e}")

    logs_dir = os.path.join(output_dir, "Logs")
    try:
        os.makedirs(logs_dir, exist_ok=True)
    except OSError as e:
        logger.warning("[setup] Could not create logs directory %s: %s -- file logging disabled", logs_dir, e)
        logs_dir = None
    
    global file_handler
    # Build the new handler before touching the old one so a failure in the
    # FileHandler constructor (disk full, permissions, etc.) doesn't leave
    # the logger with no file handler at all -- previously we removed the
    # old handler first and an exception between remove + reassign would
    # silently kill all file logging for the rest of the run.
    if logs_dir is None:
        logger.info("[setup] Skipping file logging (logs directory unavailable)")
    else:
        new_handler = logging.FileHandler(os.path.join(logs_dir, 'domain_crawler.log'), encoding='utf-8')
        new_handler.setLevel(logging.INFO)
        new_handler.setFormatter(formatter)
        old_handler = file_handler
        logger.addHandler(new_handler)
        file_handler = new_handler
        if old_handler is not None:
            try:
                logger.removeHandler(old_handler)
                old_handler.close()
            except Exception:
                pass
    
    # Optional auto-tune: probe outbound bandwidth and pick threads /
    # verifier-concurrency to match. Free; uses Cloudflare's public speedtest
    # endpoint (no API key, no analytics).
    autotuned_verifier_concurrency = None
    if getattr(args, "auto_tune", False):
        speed = measure_internet_speed()
        tuned = autotune_concurrency(speed, cli_threads=None if args.threads in (None, 0) else args.threads)
        if speed.get("ok"):
            print(
                f"[+] Speed test: {speed['mbps']:.1f} Mbps down ({speed['rtt_ms']:.0f} ms RTT) "
                f"-> threads={tuned['threads']} verifier_concurrency={tuned['verifier_concurrency']}"
            )
        else:
            print("[!] Speed test failed; using conservative defaults (threads=10, verifier=30).")
        # Honour explicit --threads if user passed it; only override the default.
        if not getattr(args, "threads_explicit", False):
            args.threads = tuned["threads"]
        autotuned_verifier_concurrency = tuned["verifier_concurrency"]

    if getattr(args, "selenium", False):
        # Deprecation warning: the tiered fetcher (curl_cffi + camoufox)
        # supersedes Selenium for every realistic use case. Keep the
        # flag working but nudge users toward --browser-fallback.
        print(
            "[!] --selenium is deprecated and will be removed in a future "
            "release. Use --browser-fallback (camoufox) for stealth "
            "JavaScript rendering instead."
        )
        logger.warning("--selenium flag is deprecated; prefer --browser-fallback")
    crawler = AdvancedEmailScraper(
        domains=domains, max_threads=args.threads, timeout=args.timeout,
        delay=args.delay, proxies=proxies, use_selenium=args.selenium,
        output_dir=output_dir, logs_dir=logs_dir, settings=settings,
        master_folder_path=master_folder_path
    )
    # Wire CLI flags into the crawler instance.
    crawler.auto_yes = bool(getattr(args, "one_shot", False))
    crawler.respect_robots = not bool(getattr(args, "no_robots", False))
    if getattr(args, "no_sitemap", False):
        crawler.sitemap_max_urls = 0

    try:
        print("Starting crawl process...")
        crawler.crawl()
        
        print("\nCrawl process finished. Generating final reports...")
        final_base_filename = os.path.join(output_dir, args.output)
        crawler.save_results(final_base_filename, is_final_save=True)
        print(f"Final reports saved in '{output_dir}' in JSON, CSV, and Logs subfolders.")
        
        if master_folder_path:
            print(f"[*] Updating master logs in '{master_folder_path}'...")
            master_base_filename = os.path.join(master_folder_path, "master_crawl_results")
            crawler.save_results(master_base_filename, is_final_save=True, master_folder=master_folder_path)

        csv_dir = os.path.join(output_dir, "CSV")
        crawler_output_csv = os.path.join(csv_dir, f"{args.output}_emails.csv")
        
        if os.path.exists(crawler_output_csv):
            vs = settings['verifier_settings']
            timeout = vs.get('prompt_timeout', 5)
            default_concurrency = vs.get('default_concurrency', 100)
            email_tasks = read_emails_from_file(
                crawler_output_csv, prompt_user=False,
                email_col_default=vs.get('default_email_column', 'B'),
                classification_col_default=vs.get('default_classification_column', 'C'),
                domain_col_default=vs.get('default_domain_column', 'A')
            )

            if email_tasks:
                one_shot = bool(getattr(args, "one_shot", False))
                if one_shot:
                    verify_choice = 'y'
                    print(f"\n[+] [one-shot] auto-verifying {len(email_tasks)} emails (mode={vs.get('default_verification_mode', 'direct')}).")
                else:
                    verify_choice = prompt_with_timeout(
                        f"\n[+] Crawler found {len(email_tasks)} emails. Do you want to verify them now? (y/n): ",
                        timeout=timeout, default='y'
                    ).lower()

                if verify_choice.startswith('y'):
                    default_mode = vs.get('default_verification_mode', 'direct')
                    if one_shot:
                        mode = default_mode
                        concurrency = autotuned_verifier_concurrency or default_concurrency
                        delay = 0
                    else:
                        print("\n--- Configure Verification ---")
                        mode_prompt_map = {'direct': '1', 'auth': '2'}
                        mode_choice = prompt_with_timeout(
                            f"Choose verification method: [1] Direct Check, [2] Authenticated SMTP [default: {default_mode}]: ",
                            timeout=timeout, default=mode_prompt_map[default_mode]
                        )
                        mode = 'auth' if mode_choice == '2' else 'direct'

                        try:
                            concurrency_str = prompt_with_timeout(f"Enter concurrency [default: {default_concurrency}]: ", timeout=timeout, default=str(default_concurrency))
                            concurrency = int(concurrency_str)
                            if concurrency < 1:
                                concurrency = default_concurrency
                            elif concurrency > 500:
                                concurrency = 500
                                print("[!] Concurrency capped at 500 to prevent resource exhaustion.")
                        except ValueError:
                            concurrency = default_concurrency

                        try:
                            delay_str = prompt_with_timeout("Enter delay in seconds after each check [default: 0]: ", timeout=timeout, default='0')
                            delay = int(delay_str)
                        except ValueError:
                            delay = 0
                            
                    out_path = os.path.join(csv_dir, f"{args.output}_verified_emails.csv")
                    master_verified_path = None
                    if master_folder_path:
                        master_verified_path = os.path.join(master_folder_path, "CSV", "master_verified_emails.csv")

                    verifier = AsyncEmailVerifier(settings, proxies=proxies)
                    asyncio.run(verifier.run(
                        email_tasks, out_path, concurrency, delay, mode,
                        master_out_path=master_verified_path,
                        reverify_unknown=bool(getattr(args, "reverify_unknown", False)),
                        history_db=history_db,
                        history_run_id=run_id,
                    ))

        summary = crawler.get_summary_data()
        total_emails = sum(len(e['prioritized']) + len(e['other']) for e in summary['emails_per_domain'].values())
        total_cross_emails = sum(len(e['prioritized']) + len(e['other']) for e in summary['cross_domain_emails'].values())

        print("\n--- Crawl Summary ---")
        print(f"Domains successfully crawled: {len(summary.get('successful_crawls', []))}")
        print(f"Domains with emails found: {len(summary.get('emails_per_domain', {}))}")
        print(f"Total target-domain emails found: {total_emails}")
        print(f"Total cross-domain emails found: {total_cross_emails}")
        print("\n--- Time Summary ---")
        if crawler.priority_scan_duration > 0:
            print(f"Priority Scan completed in: {format_duration(crawler.priority_scan_duration)}")
        if crawler.deep_crawl_duration > 0:
            print(f"Deep Crawl completed in:    {format_duration(crawler.deep_crawl_duration)}")
            total_time = crawler.priority_scan_duration + crawler.deep_crawl_duration
            print(f"Total combined time:        {format_duration(total_time)}")
        print("---------------------\n")
        
        temp_dir_path = os.path.join(output_dir, '.tmp')
        if os.path.isdir(temp_dir_path):
            try:
                shutil.rmtree(temp_dir_path)
            except OSError as e:
                logger.warning(f"Could not remove temporary directory {temp_dir_path}: {e}")

        # ---------------- PR #6: post-crawl ops ---------------------------
        n_phones = sum(len(v) for v in (crawler.phones or {}).values())

        # Persist crawler-found emails into the history DB.
        if history_db is not None:
            try:
                for d, payload in summary.get("emails_per_domain", {}).items():
                    for email in payload.get("prioritized", []):
                        history_db.record_email(d, email, prioritized=True, source_type="target")
                    for email in payload.get("other", []):
                        history_db.record_email(d, email, prioritized=False, source_type="target")
                for d, payload in summary.get("cross_domain_emails", {}).items():
                    for email in payload.get("prioritized", []):
                        history_db.record_email(d, email, prioritized=True, source_type="cross")
                    for email in payload.get("other", []):
                        history_db.record_email(d, email, prioritized=False, source_type="cross")
                history_db.finish_run(
                    run_id=run_id,
                    n_domains=len(domains),
                    n_emails=total_emails + total_cross_emails,
                    n_phones=n_phones,
                )
                stats = history_db.stats()
                print(f"[history] db: {history_db.path} -- "
                      f"{stats['emails']} emails / {stats['domains']} domains / "
                      f"{stats['verifications']} verifications across {stats['runs']} runs")
            except Exception as e:
                _log_exception("history_db.persist", e)

        # Run metadata.json: forensic + downstream-tooling summary.
        try:
            md_path = write_run_metadata(
                output_dir,
                run_id=run_id,
                started_ts=run_started_ts,
                ended_ts=time.time(),
                n_domains=len(domains),
                n_emails=total_emails + total_cross_emails,
                n_phones=n_phones,
                cli_args=sys.argv[1:],
                extra={
                    "priority_scan_duration": round(crawler.priority_scan_duration or 0, 2),
                    "deep_crawl_duration":    round(crawler.deep_crawl_duration   or 0, 2),
                    "stealth_tls_disabled":   bool(STEALTH_TLS_DISABLED),
                    "browser_fallback_used":  bool(BROWSER_FALLBACK_ENABLED),
                },
            )
            print(f"[metadata] {md_path}")
        except Exception as e:
            _log_exception("metadata", e)

        # Optional .xlsx workbook (deliverable=green / undeliverable=red /
        # accept-all=amber). Silent skip if openpyxl missing.
        if getattr(args, "xlsx", False):
            csv_dir_local = os.path.join(output_dir, "CSV")
            xlsx_inputs: List[str] = []
            verified_csv_path: Optional[str] = None
            for suffix in ("_emails.csv", "_report.csv", "_phones.csv", "_verified_emails.csv"):
                p = os.path.join(csv_dir_local, f"{args.output}{suffix}")
                if os.path.exists(p):
                    xlsx_inputs.append(p)
                    if suffix == "_verified_emails.csv":
                        verified_csv_path = p
            if xlsx_inputs:
                xlsx_path = os.path.join(output_dir, f"{args.output}.xlsx")
                ok, info = write_xlsx_report(xlsx_inputs, xlsx_path, verified_csv=verified_csv_path)
                if ok:
                    print(f"[xlsx] wrote {info}")
                else:
                    print(f"[xlsx] skipped: {info}")

        # Webhook on completion. Best-effort; failure is logged, not raised.
        if getattr(args, "webhook", None):
            payload = build_webhook_payload(
                run_id=run_id,
                output_dir=output_dir,
                n_domains=len(domains),
                n_emails=total_emails + total_cross_emails,
                n_phones=n_phones,
                duration_seconds=time.time() - run_started_ts,
            )
            ok, info = post_completion_webhook(args.webhook, payload=payload)
            if ok:
                print(f"[webhook] delivered ({info})")
            else:
                logger.warning("[webhook] delivery failed: %s", info)

    except KeyboardInterrupt:
        print("\n[*] Crawl interrupted by user. Saving partial results and exiting cleanly.")
        logger.warning("Crawl interrupted by user.")
        try:
            partial_base = os.path.join(output_dir, args.output)
            crawler.save_results(partial_base, is_final_save=True)
            print(f"[*] Partial results written to '{output_dir}'.")
        except Exception as e:
            _log_exception("shutdown", e)
        finally:
            crawler.close()
        # Re-raise so the outer driver can handle exit cleanly without leaking
        # threads or skipping logging handlers (was: os._exit which bypassed
        # the logging.shutdown atexit hook and the file_handler flush).
        raise
    finally:
        crawler.close()
        if history_db is not None:
            try:
                history_db.close()
            except Exception:
                pass
        # NOTE: PID file removal is intentionally NOT done here. In --url
        # continuous monitoring mode this finally runs once per polling
        # cycle while the process is still alive; deleting the PID file
        # after the first cycle would defeat the purpose of --pid-file
        # (systemd / Docker would lose their handle to the process). The
        # PID file is removed by main()'s atexit handler instead.
        logger.info("Script finished.")

    return domains


# --- START: SELF-TEST / AUTO VALIDATION MODE ---

class _SelfTestReport:
    """Collects pass/fail results for the self-test runner."""

    def __init__(self):
        self.entries: List[Tuple[str, str, str]] = []

    def record(self, module: str, status: str, detail: str = "") -> None:
        self.entries.append((module, status, detail))

    @property
    def passed(self) -> int:
        return sum(1 for _, s, _ in self.entries if s == "PASS")

    @property
    def failed(self) -> int:
        return sum(1 for _, s, _ in self.entries if s == "FAIL")

    def render(self) -> str:
        lines = ["", "=" * 68, " EMAIL-SCRAPPER  SELF-TEST  REPORT", "=" * 68]
        for module, status, detail in self.entries:
            marker = "PASS" if status == "PASS" else "FAIL"
            lines.append(f"  [{marker}] {module:<28} {detail}")
        lines.append("-" * 68)
        lines.append(
            f"  Total: {self.passed} passed, {self.failed} failed "
            f"(of {len(self.entries)})"
        )
        lines.append("=" * 68)
        return "\n".join(lines)


def _selftest_run(report: _SelfTestReport, module: str, fn, *, fail_fast_hint: str = "") -> bool:
    """Execute a single self-test step, capturing PASS/FAIL with module name.

    `fail_fast_hint` is appended to FAIL details to point operators at the
    likely fix location.
    """
    try:
        detail = fn() or "ok"
        report.record(module, "PASS", str(detail))
        return True
    except Exception as e:
        hint = f"  [fix: {fail_fast_hint}]" if fail_fast_hint else ""
        detail = f"{e.__class__.__name__}: {e}{hint}"
        report.record(module, "FAIL", detail)
        logger.error("[self-test] %s FAILED: %s", module, detail)
        return False


def run_self_test(settings, default_settings, config_filepath) -> int:
    """Automated validation of every advertised feature.

    Exit status:
      0  all tests passed
      1  one or more tests failed (specific module(s) printed in report)
    """
    print("[*] Running EMAIL-SCRAPPER --self-test ...")
    logger.info("Self-test started.")
    report = _SelfTestReport()

    sandbox_root = os.path.join(os.getcwd(), ".selftest_sandbox")
    if os.path.isdir(sandbox_root):
        shutil.rmtree(sandbox_root, ignore_errors=True)
    os.makedirs(sandbox_root, exist_ok=True)

    # 1. Critical imports
    def _t_imports():
        required = [
            "requests", "bs4", "cloudscraper", "aiohttp", "aiodns",
            "aiosmtplib", "tqdm", "tld",
        ]
        missing = []
        for m in required:
            try:
                __import__(m)
            except ImportError:
                missing.append(m)
        if missing:
            raise RuntimeError("missing modules: " + ", ".join(missing))
        return f"all {len(required)} required modules present"
    _selftest_run(report, "imports", _t_imports,
                  fail_fast_hint="pip install -r requirements.txt")

    # 2. Settings load/save round-trip
    def _t_settings():
        path = os.path.join(sandbox_root, "settings.json")
        save_settings(default_settings, path)
        if not os.path.isfile(path):
            raise RuntimeError("settings file was not written")
        loaded = load_settings(path, default_settings)
        if "verifier_settings" not in loaded or "crawler_settings" not in loaded:
            raise RuntimeError("loaded settings missing required top-level keys")
        # Verify set-typed lists round-trip back into sets
        if not isinstance(loaded["crawler_settings"]["common_providers"], set):
            raise RuntimeError("set values not deserialised back into a set")
        return f"round-tripped {os.path.getsize(path)} bytes"
    _selftest_run(report, "settings_load_save", _t_settings,
                  fail_fast_hint="check load_settings/save_settings")

    # 3. Output directory creation (resumable run dirs)
    def _t_output_directory():
        cwd = os.getcwd()
        try:
            os.chdir(sandbox_root)
            run_dir_1 = setup_output_directory()
            # Simulate a "good" run by writing CSV/JSON dirs
            os.makedirs(os.path.join(run_dir_1, "JSON"), exist_ok=True)
            os.makedirs(os.path.join(run_dir_1, "CSV"), exist_ok=True)
            with open(os.path.join(run_dir_1, "JSON", "x.json"), "w") as f:
                f.write("{}")
            run_dir_2 = setup_output_directory()
            if run_dir_1 == run_dir_2:
                raise RuntimeError("second run did not get a fresh directory")
            if not (os.path.isdir(run_dir_1) and os.path.isdir(run_dir_2)):
                raise RuntimeError("expected output directories not present")
            return f"created {run_dir_1!r} and {run_dir_2!r}"
        finally:
            os.chdir(cwd)
    _selftest_run(report, "output_directory", _t_output_directory,
                  fail_fast_hint="setup_output_directory")

    # 4 + 5. CSV + TXT input parsing
    def _t_csv_input():
        p = os.path.join(sandbox_root, "input.csv")
        with open(p, "w", newline="", encoding="utf-8") as f:
            w = csv.writer(f)
            w.writerow(["domain", "email", "classification"])
            w.writerow(["acmecorp.org", "alice@acmecorp.org", "prioritized"])
            w.writerow(["acmecorp.org", "bob@acmecorp.org", "other"])
        tasks = read_emails_from_file(
            p, prompt_user=False,
            email_col_default="B",
            classification_col_default="C",
            domain_col_default="A",
        )
        if len(tasks) != 2:
            raise RuntimeError(f"expected 2 tasks, got {len(tasks)}")
        if tasks[0][0] != "alice@acmecorp.org":
            raise RuntimeError("email parsing column index is wrong")
        return f"parsed {len(tasks)} CSV rows"
    _selftest_run(report, "csv_input_parsing", _t_csv_input,
                  fail_fast_hint="read_emails_from_file (CSV branch)")

    def _t_txt_input():
        p = os.path.join(sandbox_root, "input.txt")
        with open(p, "w", encoding="utf-8") as f:
            f.write("alice@acmecorp.org\nbob@acmecorp.org\n   \n")
        tasks = read_emails_from_file(p, prompt_user=False)
        if len(tasks) != 2:
            raise RuntimeError(f"expected 2 tasks, got {len(tasks)}")
        return f"parsed {len(tasks)} TXT rows"
    _selftest_run(report, "txt_input_parsing", _t_txt_input,
                  fail_fast_hint="read_emails_from_file (TXT branch)")

    # 6. Email extraction engine
    def _t_email_extraction():
        scraper = AdvancedEmailScraper(
            domains=[], output_dir=sandbox_root, logs_dir=sandbox_root,
            settings=settings,
        )
        try:
            sample_html = (
                "<html><body>"
                "Contact: <a href=\"mailto:hello@acmecorp.org\">us</a> "
                "Or write to support[at]acmecorp[dot]org "
                "<a class='__cf_email__' data-cfemail='c4ada2a3a584a1bca5a9b4a8a1eaa7aba9'>x</a> "
                "<script>var x = 'YWxpY2VAYWNtZS50ZXN0';</script>"
                "</body></html>"
            )
            emails = scraper._extract_emails(sample_html)
            if "hello@acmecorp.org" not in emails:
                raise RuntimeError("mailto extraction failed")
            if "support@acmecorp.org" not in emails:
                raise RuntimeError("[at]/[dot] deobfuscation failed")
            return f"extracted {len(emails)} unique emails"
        finally:
            scraper.close()
    _selftest_run(report, "email_extraction", _t_email_extraction,
                  fail_fast_hint="AdvancedEmailScraper._extract_emails")

    # 7. SMTP verifier flow safety (no real network egress)
    def _t_smtp_verifier_safety():
        verifier = AsyncEmailVerifier(settings)
        # Empty mx_hosts must short-circuit cleanly with no exception.
        ok, reason = asyncio.run(
            verifier._verify_smtp_direct("nobody@nonexistent.invalid", [])
        )
        if ok is not None or "No MX" not in reason:
            raise RuntimeError(f"unexpected direct-verifier behaviour: {ok}, {reason}")
        # Authenticated mode with empty smtp_host must fail-fast not crash.
        empty_settings = json.loads(json.dumps({
            "verifier_settings": {**settings["verifier_settings"], "smtp_host": ""}
        }))
        v2 = AsyncEmailVerifier(empty_settings)
        ok2, reason2 = asyncio.run(v2._verify_smtp_auth("a@b.test"))
        if ok2 is not None or "smtp_host" not in reason2:
            raise RuntimeError(f"auth verifier should fail-fast on empty host: {reason2}")
        return "direct + auth fail-fast paths verified"
    _selftest_run(report, "smtp_verifier_safety", _t_smtp_verifier_safety,
                  fail_fast_hint="AsyncEmailVerifier._verify_smtp_direct/_verify_smtp_auth")

    # 8. MX lookup flow.
    # Use a quick TCP probe to gmail.com:443 to decide whether the box is
    # actually online. If it is, we REQUIRE at least one MX record back --
    # an empty list with network up is a regression (e.g. aiodns API drift).
    def _t_mx_lookup():
        online = False
        try:
            sock = socket.create_connection(("gmail.com", 443), timeout=3)
            sock.close()
            online = True
        except Exception:
            online = False

        verifier = AsyncEmailVerifier(settings)
        try:
            records = asyncio.run(verifier.get_mx_records("gmail.com"))
        except Exception as e:
            if online:
                raise RuntimeError(f"MX lookup raised while network was up: {e}")
            return f"network unavailable, MX lookup gracefully handled: {e}"
        if not isinstance(records, list):
            raise RuntimeError("get_mx_records did not return a list")
        if online and not records:
            raise RuntimeError(
                "network up but get_mx_records returned no records -- likely aiodns API drift"
            )
        return f"resolved {len(records)} MX records (online={online})"
    _selftest_run(report, "mx_lookup", _t_mx_lookup,
                  fail_fast_hint="AsyncEmailVerifier.get_mx_records")

    # 9. Proxy fallback behavior
    def _t_proxy_fallback():
        # Use a deliberately broken proxy URL; the verifier must return
        # (None, <reason>) without raising.
        verifier = AsyncEmailVerifier(settings, proxies=["socks5://127.0.0.1:1"])
        ok, reason = asyncio.run(
            verifier._verify_smtp_direct("a@b.test", ["mx.invalid"])
        )
        if ok is True:
            raise RuntimeError("proxy verifier should not report deliverable on a bad proxy")
        if not reason:
            raise RuntimeError("proxy verifier returned no reason string")
        return f"bad proxy reported: {reason[:60]}..."
    _selftest_run(report, "proxy_fallback", _t_proxy_fallback,
                  fail_fast_hint="AsyncEmailVerifier._verify_smtp_direct (proxy branch)")

    # 10. Deep crawl queue behavior
    def _t_deep_crawl_queue():
        scraper = AdvancedEmailScraper(
            domains=[], output_dir=sandbox_root, logs_dir=sandbox_root,
            settings=settings,
        )
        try:
            scraper.crawl_queue.append(("https://a.invalid/", 0))
            scraper.crawl_queue.append(("https://b.invalid/", 0))
            n_before = len(scraper.crawl_queue)
            # popleft semantics + appendleft re-queue must round-trip
            item = scraper.crawl_queue.popleft()
            scraper.crawl_queue.appendleft(item)
            if len(scraper.crawl_queue) != n_before:
                raise RuntimeError("queue size diverged after popleft/appendleft cycle")
            return f"deque round-tripped at size {n_before}"
        finally:
            scraper.close()
    _selftest_run(report, "deep_crawl_queue", _t_deep_crawl_queue,
                  fail_fast_hint="AdvancedEmailScraper.crawl_queue")

    # 11 + 12 + 13. JSON / CSV export + report generation
    def _t_exports():
        scraper = AdvancedEmailScraper(
            domains=[], output_dir=sandbox_root, logs_dir=sandbox_root,
            settings=settings,
        )
        try:
            scraper.results['successful_crawls'].add('acmecorp.org')
            scraper.results['emails']['acmecorp.org']['prioritized'].add('hello@acmecorp.org')
            scraper.results['emails']['acmecorp.org']['other'].add('marketing@acmecorp.org')
            scraper.results['cross_domain_emails']['acmecorp.org']['ext@gmail.com'].add(
                'https://acmecorp.org/contact'
            )
            base = os.path.join(sandbox_root, 'export_test', 'results')
            os.makedirs(os.path.dirname(base), exist_ok=True)
            scraper.save_results(base, is_final_save=True)

            json_path = os.path.join(os.path.dirname(base), 'JSON', 'results_emails.json')
            email_csv = os.path.join(os.path.dirname(base), 'CSV', 'results_emails.csv')
            report_csv = os.path.join(os.path.dirname(base), 'CSV', 'results_report.csv')
            for p in (json_path, email_csv, report_csv):
                if not os.path.isfile(p):
                    raise RuntimeError(f"export missing: {p}")
            with open(email_csv, encoding='utf-8') as f:
                rows = list(csv.reader(f))
            if len(rows) < 2:
                raise RuntimeError("email CSV had no data rows")
            return f"JSON + CSV ({len(rows) - 1} rows) + report.csv"
        finally:
            scraper.close()
    _selftest_run(report, "json_export", lambda: _t_exports(),
                  fail_fast_hint="AdvancedEmailScraper.save_results")
    # csv_export and report_generation share the same export pipeline; record
    # them as PASS once the underlying export succeeded above.
    _last = report.entries[-1]
    if _last[1] == "PASS":
        report.record("csv_export", "PASS", _last[2])
        report.record("report_generation", "PASS", _last[2])
    else:
        report.record("csv_export", "FAIL", "blocked by json_export")
        report.record("report_generation", "FAIL", "blocked by json_export")

    # 14. Timeout prompt fallback (cannot block stdin in CI; we just verify it
    # is callable and returns the default when forced through the timeout path
    # by stubbing sys.stdin/select.)
    def _t_timeout_prompt():
        if select is None and msvcrt is None:
            return "neither select nor msvcrt available; prompt will return default-only"
        # Use an extremely short timeout. select() returns empty rlist quickly,
        # which forces the default branch.
        result = prompt_with_timeout("(self-test) ", timeout=0, default="N")
        if result != "N":
            raise RuntimeError(f"expected default 'N' on timeout, got {result!r}")
        return "default returned on timeout"
    _selftest_run(report, "timeout_prompt", _t_timeout_prompt,
                  fail_fast_hint="prompt_with_timeout")

    # 15. Captcha detection
    def _t_captcha():
        scraper = AdvancedEmailScraper(
            domains=[], output_dir=sandbox_root, logs_dir=sandbox_root,
            settings=settings,
        )
        try:
            # The bare word ``captcha`` was removed from _CAPTCHA_INDICATORS
            # because it false-positives on privacy policies, help articles,
            # blog posts, and FAQ navigation that merely *mention* captchas.
            # Widget-specific markers (cf-turnstile, g-recaptcha, etc.) are
            # the correct challenge indicators.
            if not scraper._detect_captcha(
                '<div class="g-recaptcha" data-sitekey="abc"></div>'
            ):
                raise RuntimeError("captcha keyword not detected")
            if scraper._detect_captcha("welcome to acme inc"):
                raise RuntimeError("benign content reported as captcha")
            return "true-positive + true-negative both correct"
        finally:
            scraper.close()
    _selftest_run(report, "captcha_detection", _t_captcha,
                  fail_fast_hint="AdvancedEmailScraper._detect_captcha")

