    # 18. Resumable output structure (ensures incomplete runs are pruned)
    def _t_resumable_output():
        cwd = os.getcwd()
        try:
            os.chdir(sandbox_root)
            r1 = setup_output_directory()
            # Mark r1 as a "good" run with a JSON output
            os.makedirs(os.path.join(r1, "JSON"), exist_ok=True)
            with open(os.path.join(r1, "JSON", "ok.json"), "w") as f:
                f.write("{}")
            # Create an empty (incomplete) sibling run dir then re-invoke setup;
            # the helper must reuse / overwrite the empty slot.
            sibling = os.path.join(os.path.dirname(r1), "999")
            os.makedirs(sibling, exist_ok=True)
            r2 = setup_output_directory()
            if r2 == r1:
                raise RuntimeError("resumable logic returned the same run dir")
            return "incomplete run pruning works"
        finally:
            os.chdir(cwd)
    _selftest_run(report, "resumable_output", _t_resumable_output,
                  fail_fast_hint="setup_output_directory")

