    # 22. Domain normalisation
    def _t_domain_normalisation():
        cases = [
            ("https://Example.com/", "example.com"),
            ("https://www.Example.COM/contact?x=1#frag", "example.com"),
            ("HTTP://EXAMPLE.com:8080", "example.com"),
            ("www.foo.bar.example.com", "foo.bar.example.com"),
            ("  example.com.  ", "example.com"),
            ("example.com/path/with/slashes", "example.com"),
            ("# this is a comment", None),
            ("", None),
            ("notadomain", None),
            ("127.0.0.1", None),
            ("acmecorp.org", "acmecorp.org"),
        ]
        for raw, expected in cases:
            got = normalize_domain(raw)
            if got != expected:
                raise RuntimeError(f"normalize_domain({raw!r}) = {got!r}, expected {expected!r}")
        # Dedup behaviour
        deduped = normalize_domain_list([
            "https://example.com",
            "EXAMPLE.com",
            "www.example.com/contact",
            "other.org",
            "",
            "# comment",
        ])
        if deduped != ["example.com", "other.org"]:
            raise RuntimeError(f"normalize_domain_list dedup failed: {deduped}")
        return f"all {len(cases)} cases + dedup correct"
