    # 26. Stealth header rotation
    def _t_stealth_headers():
        seen_uas, seen_langs = set(), set()
        for _ in range(40):
            h = random_browser_headers()
            if "User-Agent" not in h or "Accept-Language" not in h:
                raise RuntimeError("missing required headers")
            seen_uas.add(h["User-Agent"])
            seen_langs.add(h["Accept-Language"])
        if len(seen_uas) < 4:
            raise RuntimeError(f"UA pool not rotating (only {len(seen_uas)} unique)")
        if len(seen_langs) < 2:
            raise RuntimeError(f"Accept-Language not rotating (only {len(seen_langs)} unique)")
        return f"{len(seen_uas)} unique UAs, {len(seen_langs)} unique langs across 40 calls"
    _selftest_run(report, "stealth_headers", _t_stealth_headers,
                  fail_fast_hint="random_browser_headers / _USER_AGENT_POOL")

    # 27. Speedtest + adaptive concurrency tuning (offline; pure logic)
    def _t_autotune():
        cases = [
            ({"ok": True, "mbps": 2.0,  "rtt_ms": 150}, lambda r: r["threads"] <= 12),
            ({"ok": True, "mbps": 30.0, "rtt_ms": 80},  lambda r: 20 <= r["threads"] <= 40),
            ({"ok": True, "mbps": 200,  "rtt_ms": 50},  lambda r: r["threads"] >= 60),
            ({"ok": False},                              lambda r: r["threads"] <= 12),
            ({"ok": True, "mbps": 200,  "rtt_ms": 1500}, lambda r: r["threads"] < 60),  # high RTT clamps down
        ]
        for measured, check in cases:
            r = autotune_concurrency(measured)
            if not check(r):
                raise RuntimeError(f"unexpected tune for {measured}: {r}")
        explicit = autotune_concurrency({"ok": True, "mbps": 100, "rtt_ms": 50}, cli_threads=7)
        if explicit["threads"] != 7:
            raise RuntimeError("explicit cli_threads not respected")
        return f"{len(cases)} bandwidth bands + cli-override case OK"
    _selftest_run(report, "autotune_concurrency", _t_autotune,
                  fail_fast_hint="autotune_concurrency")

    # 28. Sitemap.xml parsing + filter
    def _t_sitemap_parser():
        sample = b"""<?xml version="1.0" encoding="UTF-8"?>
        <urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
          <url><loc>https://example.com/</loc></url>
          <url><loc>https://example.com/contact-us</loc></url>
          <url><loc>https://example.com/products/widget-9000</loc></url>
          <url><loc>https://example.com/about/team</loc></url>
          <url><loc>https://example.com/blog/post-1</loc></url>
          <url><loc>https://example.com/security/disclosure</loc></url>
          <url><loc>https://other.com/contact</loc></url>
        </urlset>"""
        page_urls, child = parse_sitemap_xml(sample)
        if len(page_urls) != 7 or child:
            raise RuntimeError(f"unexpected parse: pages={len(page_urls)}, child={child}")
        kept = filter_sitemap_urls(page_urls, host_filter="example.com")
        # /contact-us, /about/team, /security/disclosure (NOT off-domain, NOT /products, NOT /blog)
        if len(kept) != 3:
            raise RuntimeError(f"filter kept wrong count: {kept}")
        # Regression: hosts whose name starts with 'w' or 'm' must not be
        # mangled by an over-eager prefix strip (was: lstrip("www.") which
        # strips the character set {'w', '.'} not the literal prefix).
        wkept = filter_sitemap_urls(
            ["https://www.walmart.com/contact-us", "https://www.walmart.com/blog/post"],
            host_filter="walmart.com",
        )
        if len(wkept) != 1 or "contact-us" not in wkept[0]:
            raise RuntimeError(f"www-prefix host filter regression: {wkept}")
        # sitemap_index variant
        idx_sample = b"""<?xml version="1.0"?>
        <sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
          <sitemap><loc>https://example.com/sitemap1.xml</loc></sitemap>
          <sitemap><loc>https://example.com/sitemap2.xml</loc></sitemap>
        </sitemapindex>"""
        _, children = parse_sitemap_xml(idx_sample)
        if len(children) != 2:
            raise RuntimeError(f"sitemap_index parsed {len(children)} children")
        return f"7 urls -> 3 kept, 2 child sitemaps detected"
    _selftest_run(report, "sitemap_parser", _t_sitemap_parser,
                  fail_fast_hint="parse_sitemap_xml / filter_sitemap_urls")

    # 29. robots.txt parser
    def _t_robots_parser():
        sample = """
        User-agent: BadBot
        Disallow: /

        User-agent: *
        Disallow: /admin/
        Disallow: /private
        Allow: /private/public/
        Crawl-delay: 2.5
        """
        rules = _RobotsRules.parse(sample)
        if not rules.disallow:
            raise RuntimeError("disallow not parsed")
        if abs(rules.crawl_delay - 2.5) > 1e-6:
            raise RuntimeError(f"crawl-delay not parsed (got {rules.crawl_delay})")
        if rules.is_allowed("/admin/users"):
            raise RuntimeError("/admin/users should be disallowed")
        if not rules.is_allowed("/public"):
            raise RuntimeError("/public should be allowed (no rule)")
        if not rules.is_allowed("/private/public/page"):
            raise RuntimeError("Allow override failed")
        if rules.is_allowed("/private/secret"):
            raise RuntimeError("/private should be disallowed")
        return f"crawl_delay=2.5s, allow-override + disallow + permitted all correct"
    _selftest_run(report, "robots_parser", _t_robots_parser,
                  fail_fast_hint="_RobotsRules.parse / .is_allowed")

    # 30. Per-domain token bucket
    def _t_token_bucket():
        # Use a tight rate so we exhaust the burst quickly and observe pacing.
        rl = DomainRateLimiter(default_rps=10.0, default_burst=2)
        # First two should be instant (burst).
        t0 = time.time()
        ok1 = rl.acquire("a.test", max_wait=0.1)
        ok2 = rl.acquire("a.test", max_wait=0.1)
        burst_elapsed = time.time() - t0
        if not (ok1 and ok2) or burst_elapsed > 0.05:
            raise RuntimeError(f"burst broken: ok1={ok1} ok2={ok2} elapsed={burst_elapsed}")
        # Third call should wait ~0.1s (1/rps).
        t1 = time.time()
        ok3 = rl.acquire("a.test", max_wait=1.0)
        wait_elapsed = time.time() - t1
        if not ok3 or wait_elapsed < 0.05:
            raise RuntimeError(f"third call did not wait (elapsed={wait_elapsed})")
        # Different domain has its own bucket and is unaffected.
        ok_other = rl.acquire("b.test", max_wait=0.05)
        if not ok_other:
            raise RuntimeError("isolated bucket interfered")
        # crawl_delay configures per-domain rate.
        rl.configure_domain("c.test", crawl_delay=0.05)
        rl.acquire("c.test"); rl.acquire("c.test")  # warm up
        t2 = time.time()
        rl.acquire("c.test")
        delay_elapsed = time.time() - t2
        if delay_elapsed < 0.02:
            raise RuntimeError(f"crawl_delay not honoured: {delay_elapsed}")
        return f"burst+pace+isolation+crawl_delay all OK"
    _selftest_run(report, "domain_rate_limiter", _t_token_bucket,
                  fail_fast_hint="DomainRateLimiter.acquire")

    # 31. JSON-LD email extraction
    def _t_jsonld_extract():
        regex = re.compile(r'\b[\w.%+-]+@[\w.-]+\.[\w]{2,}\b')
        html_doc = """
        <html><body>
        <script type="application/ld+json">
        {"@context":"https://schema.org","@type":"Organization",
         "name":"Acme","email":"founders@acme.test",
         "contactPoint":[{"@type":"ContactPoint","email":"sales@acme.test"},
                          {"@type":"ContactPoint","email":["press@acme.test","media@acme.test"]}]}
        </script>
        <script type="application/ld+json">
        {"@type":"Person","name":"CEO","email":"ceo@acme.test"}
        </script>
        </body></html>
        """
        soup = BeautifulSoup(html_doc, "html.parser")
        emails = extract_emails_from_jsonld(soup, regex)
        expected = {"founders@acme.test", "sales@acme.test", "press@acme.test",
                    "media@acme.test", "ceo@acme.test"}
        if not expected.issubset(emails):
            raise RuntimeError(f"jsonld missed: {expected - emails}")
        return f"extracted {len(emails)} emails from JSON-LD blocks"
    _selftest_run(report, "jsonld_extraction", _t_jsonld_extract,
                  fail_fast_hint="extract_emails_from_jsonld")

    # 32. data-* attribute + ROT13 + JS-concat decoders
    def _t_advanced_decoders():
        regex = re.compile(r'\b[\w.%+-]+@[\w.-]+\.[\w]{2,}\b')
        # data-* attributes with HTML-entity-encoded emails
        html_doc = '<a data-email="info&#64;example.test" data-fallback="hello@x.test">go</a>'
        soup = BeautifulSoup(html_doc, "html.parser")
        data_emails = extract_emails_from_data_attrs(soup, regex)
        if "info@example.test" not in data_emails or "hello@x.test" not in data_emails:
            raise RuntimeError(f"data-attr decoder missed: {data_emails}")
        # JS string-concat
        js = '"sec" + "urity" + "@acme" + ".test"'
        concat_emails = decode_js_concat_emails(js, regex)
        if "security@acme.test" not in concat_emails:
            raise RuntimeError(f"js-concat decoder missed: {concat_emails}")
        # ROT13: 'security@example.com' rotates to 'frphevgl@rknzcyr.pbz';
        # the original (decoded) form should be recovered.
        rot13_input = "frphevgl@rknzcyr.pbz"
        rot13_out = decode_rot13_emails(rot13_input, regex)
        if "security@example.com" not in rot13_out:
            raise RuntimeError(f"rot13 decoder missed: {rot13_out}")
        # SVG <text>
        svg_html = '<svg><text>Reach us at hello@design.test</text></svg>'
        svg_emails = extract_emails_from_svg(BeautifulSoup(svg_html, "html.parser"), regex)
        if "hello@design.test" not in svg_emails:
            raise RuntimeError(f"svg decoder missed: {svg_emails}")
        return "data-attr + js-concat + rot13 + svg all decoded"
    _selftest_run(report, "advanced_email_decoders", _t_advanced_decoders,
                  fail_fast_hint="extract_emails_from_data_attrs / decode_js_concat_emails / decode_rot13_emails / extract_emails_from_svg")

    # 33. Phone number extraction
    def _t_phone_extract():
        text = """
        Reach us at +1 415-555-2671 or our London office +44 20 7946 0958.
        Internal extension only: 1234.
        """
        phones = extract_phone_numbers(text)
        if not phones:
            raise RuntimeError("no phones extracted")
        # Should NOT pick up the 4-digit extension.
        if any(re.fullmatch(r"\d{4}", re.sub(r"\D", "", p)) for p in phones):
            raise RuntimeError(f"4-digit extension leaked through: {phones}")
        return f"extracted {len(phones)} phone(s); rejected 4-digit extension"
    _selftest_run(report, "phone_extraction", _t_phone_extract,
                  fail_fast_hint="extract_phone_numbers")

    # 34. Greylist detection
    def _t_greylist_detect():
        positives = [
            "RCPT TO temporary failure with code 451",
            "Greylisted, please try again later",
            "421 4.7.0 Try again later",
            "452 4.7.1 rate limit exceeded",
        ]
        negatives = [
            "RCPT TO accepted with code 250",
            "RCPT TO rejected with code 550",
            "Connection timed out",
            "No MX records",
            # Regression: proxy-port 443/420 etc. inside reason strings must
            # NOT be treated as a 4xx SMTP code.
            "Connection to mx.example.com via proxy socks5://10.0.0.1:443 timed out",
            "Connection to mx.example.com via proxy http://1.2.3.4:420 timed out",
            "Proxy connection failed via socks5://127.0.0.1:443: ProxyConnectionError",
        ]
        for p in positives:
            if not is_greylist_response(p):
                raise RuntimeError(f"missed greylist: {p}")
        for n in negatives:
            if is_greylist_response(n):
                raise RuntimeError(f"false greylist: {n}")
        return f"{len(positives)} greylist + {len(negatives)} non-greylist all classified correctly"
    _selftest_run(report, "greylist_detection", _t_greylist_detect,
                  fail_fast_hint="is_greylist_response")

    # 35. Content-hash dedup (per-domain)
    def _t_content_hash_dedup():
        # Use the actual crawler's _record_response_seen path on a tiny
        # sandbox instance.
        scraper = AdvancedEmailScraper(
            domains=[], max_threads=1, timeout=5, delay=0,
            proxies=None, use_selenium=False,
            output_dir=os.path.join(sandbox_root, "hash_dedup"),
            logs_dir=os.path.join(sandbox_root, "hash_dedup", "Logs"),
            settings=settings,
            master_folder_path=None,
        )
        try:
            os.makedirs(scraper.logs_dir, exist_ok=True)
            body = b"<html>contact me</html>"
            first = scraper._record_response_seen("ex.test", body)
            second = scraper._record_response_seen("ex.test", body)
            third_other = scraper._record_response_seen("ex2.test", body)  # different domain - independent
            if first or not second or third_other:
                raise RuntimeError(f"hash dedup logic wrong: first={first} second={second} third_other={third_other}")
        finally:
            scraper.close()
        return "first=False, repeat=True, other-domain=False all correct"
    _selftest_run(report, "content_hash_dedup", _t_content_hash_dedup,
                  fail_fast_hint="AdvancedEmailScraper._record_response_seen")

    # 36. CLI flags wired (one-shot / auto-tune / no-robots / no-sitemap)
    def _t_cli_flags():
        # Build a parser equivalent to the real one and verify our flags parse.
        # We can't easily import the real parser without running main(), so
        # check the argparse spec by parsing a representative invocation.
        import argparse as _argparse
        p = _argparse.ArgumentParser()
        p.add_argument("input_file", nargs="?", default=None)
        p.add_argument("--one-shot", "--auto-run", dest="one_shot", action="store_true")
        p.add_argument("--auto-tune", dest="auto_tune", action="store_true")
        p.add_argument("--no-robots", dest="no_robots", action="store_true")
        p.add_argument("--no-sitemap", dest="no_sitemap", action="store_true")
        ns = p.parse_args(["foo.txt", "--one-shot", "--auto-tune", "--no-robots", "--no-sitemap"])
        if not (ns.one_shot and ns.auto_tune and ns.no_robots and ns.no_sitemap):
            raise RuntimeError(f"flags not parsed: {ns}")
        ns2 = p.parse_args(["foo.txt", "--auto-run"])
        if not ns2.one_shot:
            raise RuntimeError("--auto-run alias broken")
        return "all 4 flags + --auto-run alias parse correctly"
    _selftest_run(report, "cli_flags_oneshot", _t_cli_flags,
                  fail_fast_hint="argparse: --one-shot / --auto-tune / --no-robots / --no-sitemap")

    # 37. PR #5: stealth_session picks curl_cffi when available.
    def _t_stealth_session():
        # When curl_cffi is installed (default), kind == 'curl_cffi'.
        # When prefer_curl_cffi=False, falls back to cloudscraper.
        s_pref = _StealthSession(prefer_curl_cffi=True, max_threads=4)
        s_off = _StealthSession(prefer_curl_cffi=False, max_threads=4)
        try:
            if HAS_CURL_CFFI and s_pref.kind != "curl_cffi":
                raise RuntimeError(f"expected curl_cffi backend, got {s_pref.kind}")
            if s_off.kind != "cloudscraper":
                raise RuntimeError(f"prefer_curl_cffi=False didn't fall back: {s_off.kind}")
            # Both backends must expose the surface we use.
            for sess in (s_pref, s_off):
                if not hasattr(sess, "headers") or not hasattr(sess, "get") or not hasattr(sess, "head"):
                    raise RuntimeError(f"missing surface on {sess.kind}")
                # headers must be mutable dict-like
                sess.headers.update({"X-Selftest": "1"})
        finally:
            s_pref.close(); s_off.close()
        return f"curl_cffi={HAS_CURL_CFFI}, both backends expose .get/.head/.headers"
    _selftest_run(report, "stealth_session", _t_stealth_session,
                  fail_fast_hint="_StealthSession (curl_cffi / cloudscraper backends)")

    # 38. PR #5: prescreen splits domains into alive / dead.
    def _t_prescreen_domains():
        # Mix: one definitely-resolvable (example.com), one definitely-dead
        # (a non-existent TLD-rooted hostname). We DON'T require example.com
        # to be alive in case the test environment is offline -- we only
        # require the function returns a tuple of two lists totalling the
        # input length, with no exceptions raised.
        alive, dead = prescreen_domains(
            ["example.com", "this-domain-definitely-does-not-exist-9q8w7e.invalid"],
            threads=2, timeout=3.0,
        )
        if not isinstance(alive, list) or not isinstance(dead, list):
            raise RuntimeError(f"wrong return types: {type(alive)}, {type(dead)}")
        if len(alive) + len(dead) != 2:
            raise RuntimeError(f"lost or duplicated domains: alive={alive} dead={dead}")
        # The .invalid hostname must always be classified dead.
        if any("invalid" in d for d in alive):
            raise RuntimeError(f".invalid TLD landed in alive: {alive}")
        # Empty input must return ([], [])
        a2, d2 = prescreen_domains([], threads=2, timeout=1.0)
        if a2 != [] or d2 != []:
            raise RuntimeError(f"empty input not handled: {a2}, {d2}")
        return f"alive={len(alive)} dead={len(dead)} (.invalid correctly dead, empty handled)"
    _selftest_run(report, "prescreen_domains", _t_prescreen_domains,
                  fail_fast_hint="prescreen_domains() top-level helper")

    # 39. PR #5: multi-MX + port 587 fallback in verifier.
    def _t_multi_mx_587_fallback():
        # Patch _smtp_handshake_once to record the (host, port) tuples it's
        # called with, returning "unreachable" for everything. We expect the
        # outer loop to walk all hosts x both ports, then return the last
        # reason.
        verifier = AsyncEmailVerifier(default_settings, proxies=None)
        calls: List[Tuple[str, int]] = []

        async def fake_handshake(self_v, email, host, port):
            calls.append((host, port))
            return None, f"Connection to {host}:{port} timed out"

        original = AsyncEmailVerifier._smtp_handshake_once
        AsyncEmailVerifier._smtp_handshake_once = fake_handshake  # type: ignore[assignment]
        try:
            result, reason = asyncio.run(
                verifier._verify_smtp_direct_once(
                    "user@example.com",
                    ["mx1.example.com", "mx2.example.com", "mx3.example.com"],
                )
            )
        finally:
            AsyncEmailVerifier._smtp_handshake_once = original  # type: ignore[assignment]
        # Multi-MX x [25, 587] => 6 attempts.
        expected = [
            ("mx1.example.com", 25), ("mx1.example.com", 587),
            ("mx2.example.com", 25), ("mx2.example.com", 587),
            ("mx3.example.com", 25), ("mx3.example.com", 587),
        ]
        if calls != expected:
            raise RuntimeError(f"wrong handshake call order: {calls}")
        if result is not None:
            raise RuntimeError(f"expected None for all-unreachable, got {result!r}")
        if "timed out" not in (reason or ""):
            raise RuntimeError(f"reason should mention timeout, got: {reason!r}")

        # Now: an early definitive accept on host #2 port 25 must
        # short-circuit (no port-587 attempt for that host, no host-3 attempts).
        calls.clear()
        async def fake_handshake_accept(self_v, email, host, port):
            calls.append((host, port))
            if host == "mx2.example.com" and port == 25:
                return True, f"RCPT TO accepted by {host}:{port} with code 250"
            return None, "unreachable"

        AsyncEmailVerifier._smtp_handshake_once = fake_handshake_accept  # type: ignore[assignment]
        try:
            result2, reason2 = asyncio.run(
                verifier._verify_smtp_direct_once(
                    "u@example.com",
                    ["mx1.example.com", "mx2.example.com", "mx3.example.com"],
                )
            )
        finally:
            AsyncEmailVerifier._smtp_handshake_once = original  # type: ignore[assignment]
        if result2 is not True:
            raise RuntimeError(f"expected True on accept, got {result2!r}")
        # mx1:25, mx1:587, mx2:25 -> stop. (3 calls, not 6.)
        if calls != [("mx1.example.com", 25), ("mx1.example.com", 587), ("mx2.example.com", 25)]:
            raise RuntimeError(f"didn't short-circuit on accept: {calls}")

        # And: a non-greylist transient failure (None result) on host #1
        # must NOT short-circuit -- it must walk on to host #2. This guards
        # the regression Devin Review caught (MAIL FROM 4xx was returning
        # False, which would have terminated the loop on the first temp
        # failure). Note: greylist-shaped 4xx errors short-circuit by
        # design (per RFC 6647); we use the production 4xx phrasing here
        # which is intentionally crafted NOT to match is_greylist_response.
        calls.clear()
        # Sanity check: the production 4xx synthetic strings must NOT be
        # interpreted as greylist by is_greylist_response (otherwise the
        # multi-MX loop would incorrectly short-circuit on every 4xx).
        # We also include common real-world non-greylist 4xx server messages
        # ("temporarily unavailable", "service temporarily not available",
        # "temporary failure") which used to false-positive when the
        # is_greylist_response heuristics were too broad.
        for synth in (
            # Synthetic wrapper text alone:
            "MAIL FROM transient at mx1.example.com:25 status=421",
            "RCPT TO transient at mx1.example.com:25 status=450",
            "MAIL FROM transient at relay status=451",
            "Connection failed to mx1.example.com:25: ConnectionRefusedError",
            "Connection to mx1.example.com:25 timed out",
            # Wrapper + real-world non-greylist server text:
            "RCPT TO transient at mx1:25 status=450; server='450 Temporarily unavailable'",
            "RCPT TO transient at mx1:25 status=421; server='421 Service temporarily not available'",
            "RCPT TO transient at mx1:25 status=450; server='450 Temporarily blocked'",
            "RCPT TO transient at mx1:25 status=421; server='421 Temporary failure during delivery'",
        ):
            if is_greylist_response(synth):
                raise RuntimeError(
                    f"is_greylist_response false-positives on production 4xx phrasing: {synth!r}"
                )
        # Sanity check (positive direction): real greylist messages MUST
        # be detected. These are the exact shapes is_greylist_response is
        # supposed to short-circuit on.
        for synth in (
            "RCPT TO transient at mx1:25 status=450; server='450 4.7.1 Greylisting in effect, please try again later'",
            "RCPT TO transient at mx1:25 status=451; server='451 4.7.1 Try again later'",
            "RCPT TO transient at mx1:25 status=421; server='421 Rate limit exceeded'",
            "RCPT TO transient at mx1:25 status=450; server='450 Greylisted; please retry'",
            "RCPT TO transient at mx1:25 status=450; server='450 Temporarily deferred for greylisting'",
        ):
            if not is_greylist_response(synth):
                raise RuntimeError(
                    f"is_greylist_response false-negative on real greylist server text: {synth!r}"
                )
        async def fake_handshake_refused_then_accept(self_v, email, host, port):
            calls.append((host, port))
            if host == "mx1.example.com":
                # Use the exact production 4xx phrasing -- a regression in
                # is_greylist_response would short-circuit here.
                return None, f"MAIL FROM transient at {host}:{port} status=421"
            if host == "mx2.example.com" and port == 25:
                return True, f"RCPT TO accepted by {host}:{port} with code 250"
            return None, "unreachable"

        AsyncEmailVerifier._smtp_handshake_once = fake_handshake_refused_then_accept  # type: ignore[assignment]
        try:
            result3, reason3 = asyncio.run(
                verifier._verify_smtp_direct_once(
                    "u@example.com",
                    ["mx1.example.com", "mx2.example.com"],
                )
            )
        finally:
            AsyncEmailVerifier._smtp_handshake_once = original  # type: ignore[assignment]
        if result3 is not True:
            raise RuntimeError(f"non-greylist transient failure short-circuited the loop: {result3!r} / {reason3!r}")
        if calls != [
            ("mx1.example.com", 25), ("mx1.example.com", 587), ("mx2.example.com", 25),
        ]:
            raise RuntimeError(f"non-greylist transient didn't continue to next host: {calls}")

        # And: a *real* greylist from the server (server-supplied message,
        # NOT a synthetic wrapper) MUST be detected and short-circuit. This
        # is the architectural point of the embed-server-message fix --
        # synthetic wrapper stays greylist-proof, real server-greylist
        # bubbles through the loop verbatim and is caught.
        calls.clear()
        async def fake_handshake_real_greylist(self_v, email, host, port):
            calls.append((host, port))
            # Emulate the production phrasing produced by _smtp_handshake_once
            # when the server sent a 4.7.1 greylist response. The wrapper
            # is greylist-proof, but the embedded server text contains the
            # marker is_greylist_response is supposed to detect.
            return None, (
                f"RCPT TO transient at {host}:{port} status=450; "
                f"server='450 4.7.1 Greylisting in effect, please try again later'"
            )

        AsyncEmailVerifier._smtp_handshake_once = fake_handshake_real_greylist  # type: ignore[assignment]
        try:
            result4, reason4 = asyncio.run(
                verifier._verify_smtp_direct_once(
                    "u@example.com",
                    ["mx1.example.com", "mx2.example.com", "mx3.example.com"],
                )
            )
        finally:
            AsyncEmailVerifier._smtp_handshake_once = original  # type: ignore[assignment]
        if result4 is not None:
            raise RuntimeError(f"real greylist response should be None, got {result4!r}")
        if "Greylisting" not in (reason4 or ""):
            raise RuntimeError(f"real greylist reason should bubble up, got: {reason4!r}")
        # Greylist short-circuit means we stop after host #1 :25 (1 call,
        # not 6). is_greylist_response had to detect "greylist" in the
        # embedded server message for this to happen.
        if len(calls) != 1:
            raise RuntimeError(
                f"real-server greylist failed to short-circuit -- {len(calls)} calls instead of 1: {calls}"
            )
        return ("all-unreachable=6 calls, accept-on-mx2:25=3 calls, "
                "refused-on-mx1-then-accept-on-mx2=3 calls, "
                "real-greylist-from-server=1 call (greylist short-circuit)")
    _selftest_run(report, "multi_mx_port587_fallback", _t_multi_mx_587_fallback,
                  fail_fast_hint="AsyncEmailVerifier._verify_smtp_direct_once (multi-MX + 587 loop)")

    # 40. PR #5: _HTTP_EXC_TYPES includes curl_cffi exceptions when present.
    def _t_http_exc_types():
        if not isinstance(_HTTP_EXC_TYPES, tuple):
            raise RuntimeError(f"_HTTP_EXC_TYPES not a tuple: {type(_HTTP_EXC_TYPES)}")
        if requests.RequestException not in _HTTP_EXC_TYPES:
            raise RuntimeError("requests.RequestException missing from _HTTP_EXC_TYPES")
        if TimeoutError not in _HTTP_EXC_TYPES:
            raise RuntimeError("TimeoutError missing from _HTTP_EXC_TYPES")
        if HAS_CURL_CFFI:
            from curl_cffi.requests.exceptions import RequestException as _CCExc
            if _CCExc not in _HTTP_EXC_TYPES:
                raise RuntimeError("curl_cffi RequestException missing from _HTTP_EXC_TYPES")
        return f"requests + TimeoutError + (curl_cffi if {HAS_CURL_CFFI})"
    _selftest_run(report, "http_exc_types", _t_http_exc_types,
                  fail_fast_hint="_HTTP_EXC_TYPES tuple build at module load")

