    # 42. PR #5: Tier-2 _Tier2Response is _process_page-shape-compatible.
    # Regression for Devin Review finding -- the original draft used __slots__
    # with no close() method and headers={}, which made _process_page silently
    # discard every Tier-2 response.
    def _t_tier2_response_shape():
        # Force the path that constructs a _Tier2Response. We can't easily
        # call _tier2_camoufox_fetch directly (it requires --browser-fallback +
        # camoufox installed), so we rebuild a minimal fixture mirroring the
        # production shape and assert _process_page's content-type guard +
        # close() call would both pass.
        class FixtureResponse:
            def __init__(self, text: str, url: str):
                self.text = text or ""
                self.content = (text or "").encode("utf-8", errors="replace")
                self.status_code = 200
                self.ok = True
                self.url = url
                self.headers = {"content-type": "text/html; charset=utf-8"}
            def close(self):
                return None
        r = FixtureResponse("<html><body>x@y.com</body></html>", "https://example.com/")
        # Mirror the _process_page guards exactly:
        ct = r.headers.get('content-type', '').lower()
        if 'text/html' not in ct:
            raise RuntimeError(f"content-type guard would skip the response: {ct!r}")
        # close() must be callable without raising.
        r.close()
        # bytes/str both available
        if not isinstance(r.content, (bytes, bytearray)):
            raise RuntimeError(f".content not bytes: {type(r.content)}")
        if not isinstance(r.text, str):
            raise RuntimeError(f".text not str: {type(r.text)}")
        return "headers carry text/html, .close() callable, .content bytes, .text str"
    _selftest_run(report, "tier2_response_shape", _t_tier2_response_shape,
                  fail_fast_hint="AdvancedEmailScraper._tier2_camoufox_fetch._Tier2Response shape")

