    # 49. SIGTERM handler: install_shutdown_handler runs callback on signal flag.
    def _t_shutdown_handler():
        # We don't actually deliver SIGTERM here (would kill the test runner).
        # Instead we directly invoke request_shutdown(15, None) and verify the
        # callback fires + the global flag flips.
        global _SHUTDOWN_REQUESTED, _SHUTDOWN_CALLBACKS
        prev_flag = _SHUTDOWN_REQUESTED
        prev_cbs  = list(_SHUTDOWN_CALLBACKS)
        try:
            _SHUTDOWN_REQUESTED = False
            _SHUTDOWN_CALLBACKS = []
            fired = []
            _SHUTDOWN_CALLBACKS.append(lambda: fired.append(True))
            request_shutdown(15, None)
            if not _SHUTDOWN_REQUESTED:
                raise RuntimeError("flag did not flip")
            if not fired:
                raise RuntimeError("callback did not fire")
            # Idempotency: a second SIGTERM should NOT re-fire callbacks.
            # (We skip this check because the second invocation calls os._exit
            # in production. Instead we verify install_shutdown_handler
            # doesn't raise.)
            install_shutdown_handler()
        finally:
            _SHUTDOWN_REQUESTED = prev_flag
            _SHUTDOWN_CALLBACKS = prev_cbs
        return "SIGTERM flag flips, callbacks fire, install_shutdown_handler() succeeds"
    _selftest_run(report, "shutdown_handler", _t_shutdown_handler,
                  fail_fast_hint="install_shutdown_handler() / request_shutdown()")

