    # 52. prompt_with_timeout select=None guard.
    def _t_prompt_timeout_select_guard():
        # Patch select to None and confirm prompt_with_timeout returns the
        # default rather than raising AttributeError. We restore after.
        global select
        prev_select = select
        try:
            select = None  # type: ignore
            # Capture stdout to keep test output clean.
            import io as _io
            buf = _io.StringIO()
            old_stdout = sys.stdout
            sys.stdout = buf
            try:
                got = prompt_with_timeout("test> ", timeout=0.1, default="DEFLT")
            finally:
                sys.stdout = old_stdout
            if got != "DEFLT":
                raise RuntimeError(f"expected default, got {got!r}")
        finally:
            select = prev_select  # type: ignore
        return "select=None on POSIX -> default returned, no AttributeError"
