    # 54. Regression for Devin Review finding: in --url monitoring mode,
    # repeated run_scraper_instance() calls would each register a
    # history_db.close callback in _SHUTDOWN_CALLBACKS without ever
    # removing it. The `finally` block must clean up after each cycle so
    # the list does not grow unboundedly. We don't actually run the
    # crawler here; we test the contract directly: callbacks registered
    # within a try/finally pattern get removed.
    def _t_shutdown_callback_no_leak():
        global _SHUTDOWN_CALLBACKS
        prev = list(_SHUTDOWN_CALLBACKS)
        try:
            _SHUTDOWN_CALLBACKS = []
            # Simulate 5 monitoring cycles. Each cycle: register, then
            # remove on exit (mirroring run_scraper_instance try/finally).
            for _ in range(5):
                cb = lambda: None
                _SHUTDOWN_CALLBACKS.append(cb)
                try:
                    pass  # crawl + verify body
                finally:
                    try:
                        _SHUTDOWN_CALLBACKS.remove(cb)
                    except ValueError:
                        pass
            if len(_SHUTDOWN_CALLBACKS) != 0:
                raise RuntimeError(f"callbacks leaked across cycles: {len(_SHUTDOWN_CALLBACKS)}")
        finally:
            _SHUTDOWN_CALLBACKS = prev
        return "5 simulated --url cycles -> 0 stale callbacks (no leak)"
    _selftest_run(report, "shutdown_callback_no_leak", _t_shutdown_callback_no_leak,
                  fail_fast_hint="run_scraper_instance try/finally _SHUTDOWN_CALLBACKS cleanup")

    # 55. Regression for Devin Review finding: master verified-emails CSV is
    # opened in append mode for every --url monitoring cycle. Using
    # encoding='utf-8-sig' there would inject a 3-byte BOM mid-file on
    # every cycle, corrupting the CSV. The contract is: BOM only on
    # initial creation, plain utf-8 on append.
    def _t_master_csv_append_no_double_bom():
        path = os.path.join(sandbox_root, "master_append_bom_test.csv")
        # First write: file does not exist -> use utf-8-sig (writes BOM).
        master_file_exists = os.path.isfile(path)
        enc = "utf-8-sig" if not master_file_exists else "utf-8"
        with open(path, "a", newline="", encoding=enc) as f:
            w = csv.writer(f)
            w.writerow(["email", "status"])
            w.writerow(["a@x.com", "deliverable"])
        # Second write (simulates next monitoring cycle): file exists ->
        # use plain utf-8 (no BOM).
        master_file_exists = os.path.isfile(path)
        enc = "utf-8-sig" if not master_file_exists else "utf-8"
        with open(path, "a", newline="", encoding=enc) as f:
            w = csv.writer(f)
            w.writerow(["b@y.com", "undeliverable"])
        # Verify: BOM at start, NO BOM bytes anywhere else.
        with open(path, "rb") as f:
            blob = f.read()
        if not blob.startswith(b"\xef\xbb\xbf"):
            raise RuntimeError("BOM missing at start of master CSV")
        # Count BOM occurrences in the whole file. Should be exactly 1.
        # NOTE: hoist count out of the f-string so the byte literal does not
        # appear inside an f-string expression -- Python <3.12 forbids
        # backslashes in f-string expression parts (SyntaxError at parse
        # time), and a doubled-up "\\x" form to dodge the lexer would mean
        # a 12-byte literal instead of the 3-byte BOM in the message.
        bom_count = blob.count(b"\xef\xbb\xbf")
        if bom_count != 1:
            raise RuntimeError(
                "BOM appears %d times in master CSV -- append cycles are "
                "corrupting the file" % bom_count
            )
        return "BOM only on initial create; subsequent appends BOM-free"
    _selftest_run(report, "master_csv_append_no_double_bom",
                  _t_master_csv_append_no_double_bom,
                  fail_fast_hint="AsyncEmailVerifier master_out_path append-mode encoding")

    # 56. Regression for Devin Review finding: --pid-file deletion must
    # happen at PROCESS exit, not at the end of every run_scraper_instance
    # cycle (which would defeat --pid-file in --url monitoring mode).
    # Verify by inspecting source: the per-cycle unlink call must be gone
    # and main() must register an atexit handler instead.
    def _t_pid_file_lifetime():
        try:
            with open(__file__, "r", encoding="utf-8") as _f:
                src = _f.read()
        except Exception as e:
            raise RuntimeError(f"could not read source: {e}")
        # Construct the bad pattern at runtime so this test's own source
        # doesn't false-positive on itself (the pattern below would
        # otherwise be a literal substring of *this* function's body).
        bad_pattern = "os" + ".unlink(" + "args.pid_file)"
        if bad_pattern in src:
            raise RuntimeError(
                f"PID-file deleted in run_scraper_instance finally "
                f"(saw '{bad_pattern}'); should only be removed at process exit"
            )
        if "atexit.register(_cleanup_pid_file)" not in src:
            raise RuntimeError(
                "main() does not register an atexit handler for PID file cleanup"
            )
        return "PID file removed only at process exit (atexit), not per-cycle"
    _selftest_run(report, "pid_file_lifetime", _t_pid_file_lifetime,
                  fail_fast_hint="main() atexit.register(_cleanup_pid_file)")

    # 57. Pin the MAIL FROM 4xx/5xx contract: 5xx is permanent (False),
    # 4xx is transient (None) so the multi-MX + port-587 fallback loop
    # does not short-circuit on a temporary rejection from the primary
    # MX. We verify by source inspection -- both the direct and auth
    # paths must follow the same pattern.
    def _t_mail_from_status_split():
        try:
            with open(__file__, "r", encoding="utf-8") as _f:
                src = _f.read()
        except Exception as e:
            raise RuntimeError(f"could not read source: {e}")
        # Both occurrences must come AFTER `code, mail_msg = await smtp.mail(`.
        # We just sanity-check the count of the canonical fragments.
        if src.count("MAIL FROM permanently rejected") < 2:
            raise RuntimeError("missing 5xx-permanent branch (direct or auth)")
        if src.count("MAIL FROM transient") < 2:
            raise RuntimeError("missing 4xx-transient branch (direct or auth)")
        # And: `return False` must be guarded by `if code >= 500` (not
        # `>= 400`), otherwise the multi-MX loop would short-circuit on
        # transient failures.
        import re as _re
        # Match the lines in the smtp.mail() handlers specifically.
        bad = _re.search(r"smtp\.mail\([^)]*\)[\s\S]{0,200}?if code >= 400:\s*\n\s*return False", src)
        if bad:
            raise RuntimeError("found 'if code >= 400: return False' in MAIL FROM handler -- multi-MX loop will short-circuit")
        return "5xx -> False (permanent), 4xx -> None (transient) on both paths"
    _selftest_run(report, "mail_from_status_split", _t_mail_from_status_split,
                  fail_fast_hint="AsyncEmailVerifier MAIL FROM 5xx/4xx branch")

    # 58. prescreen_domains uses per-thread sessions (threading.local) so
