    # 71. Bug #16: subdomain-aware _is_same_domain.
    def _t_same_domain_subdomain_aware():
        s = AdvancedEmailScraper(["acme.com"], max_threads=1, settings=default_settings,
                                 output_dir=sandbox_root, logs_dir=sandbox_root)
        positives = [
            ("https://blog.acme.com/post", "acme.com"),
            ("https://www.acme.com/contact", "acme.com"),
            ("https://acme.com/about", "blog.acme.com"),
        ]
        negatives = [
            ("https://other.com/x", "acme.com"),
            ("https://acmecorp.com/x", "acme.com"),  # similar but distinct
        ]
        for url, base in positives:
            if not s._is_same_domain(url, base):
                raise RuntimeError(f"expected same-domain: {url} vs {base}")
        for url, base in negatives:
            if s._is_same_domain(url, base):
                raise RuntimeError(f"expected different-domain: {url} vs {base}")
        return "subdomains of same eTLD+1 treated as same domain; unrelated rejected"
    _selftest_run(report, "same_domain_subdomain_aware", _t_same_domain_subdomain_aware,
                  fail_fast_hint="AdvancedEmailScraper._is_same_domain eTLD+1 logic")

    # 72. Bug #19: content_hashes per-domain cap (FIFO eviction).
    def _t_content_hash_cap():
        s = AdvancedEmailScraper(["acme.com"], max_threads=1, settings=default_settings,
                                 output_dir=sandbox_root, logs_dir=sandbox_root)
        s._CONTENT_HASH_CAP = 3
        for i in range(10):
            body = f"page-{i}".encode()
            seen = s._record_response_seen("acme.com", body)
            if seen:
                raise RuntimeError(f"unique body {i} reported as seen")
        if len(s.content_hashes["acme.com"]) > 3:
            raise RuntimeError("content-hash cap not enforced")
        # Re-record an evicted-then-revisited body: should NOT be flagged
        # as seen (correctly forgotten), but recording it must not crash.
        seen2 = s._record_response_seen("acme.com", b"page-0")
        if seen2:
            raise RuntimeError("evicted body should not be reported as seen")
        return "per-domain content-hash bounded to cap with FIFO eviction"
    _selftest_run(report, "content_hash_per_domain_cap", _t_content_hash_cap,
                  fail_fast_hint="AdvancedEmailScraper._record_response_seen / content_hash_order")

    # 73. Bug #21: autotune verifier concurrency capped at 300.
    def _t_autotune_verifier_cap():
        # cli_threads -> verifier_concurrency: must never exceed 300.
        for t in (50, 100, 200, 1000):
            r = autotune_concurrency({"ok": True, "mbps": 100.0, "rtt_ms": 50.0}, cli_threads=t)
            if r["verifier_concurrency"] > 300:
                raise RuntimeError(
                    f"verifier_concurrency for cli_threads={t} = {r['verifier_concurrency']} > 300"
                )
        # Sanity: small thread counts still scale up to threads*4.
        r = autotune_concurrency({"ok": False}, cli_threads=20)
        if r["verifier_concurrency"] != max(50, 80):  # min(80, 300) = 80
            raise RuntimeError(f"unexpected concurrency for cli_threads=20: {r}")
        return "verifier_concurrency capped at 300; lower thread counts unaffected"
    _selftest_run(report, "autotune_verifier_concurrency_cap", _t_autotune_verifier_cap,
                  fail_fast_hint="autotune_concurrency -- verifier_concurrency cap")

