    # Devin Review follow-ups on PR #8.

    # 76. Reviewer flagged: rate-limiter token consumed twice (once in
    # _process_page fast-fail, once in _fetch_url). Must consume only once.
    def _t_rate_limiter_single_consume():
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._fetch_url)
        # Strip the comment block we introduced -- only count *code*
        # invocations of rate_limiter.acquire.
        code_lines = [
            ln for ln in src.splitlines()
            if "rate_limiter.acquire" in ln
            and not ln.lstrip().startswith("#")
        ]
        if code_lines:
            raise RuntimeError(
                "_fetch_url still calls rate_limiter.acquire -- token would be "
                "double-consumed since _process_page already pre-checked"
            )
        # And the fast-fail in _process_page is still there.
        proc_src = _inspect.getsource(AdvancedEmailScraper._process_page)
        if "rate_limiter.acquire" not in proc_src:
            raise RuntimeError("_process_page lost its rate-limiter pre-check")
        return "rate-limiter consumed once per URL (in _process_page only)"
    _selftest_run(report, "rate_limiter_single_consume", _t_rate_limiter_single_consume,
                  fail_fast_hint="AdvancedEmailScraper._fetch_url / _process_page rate-limiter")

    # 77. Reviewer flagged: _is_same_domain fallback could match unrelated
    # suffixes. Verify dot-boundary + degenerate-label rejection.
    def _t_same_domain_fallback_rejects_unrelated():
        s = AdvancedEmailScraper(["acme.com"], max_threads=1, settings=default_settings,
                                 output_dir=sandbox_root, logs_dir=sandbox_root)
        # "evil-acme.com" must NOT match "acme.com" -- tail is "-acme.com"
        # not ".acme.com" so dot-boundary check rejects it.
        if s._is_same_domain("https://evil-acme.com/x", "acme.com"):
            raise RuntimeError("evil-acme.com incorrectly matched acme.com")
        if s._is_same_domain("https://acme.com/x", "evil-acme.com"):
            raise RuntimeError("acme.com incorrectly matched evil-acme.com")
        # Single-label base ("local") must NOT claim every "x.local".
        if s._is_same_domain("https://printer.local/x", "local"):
            raise RuntimeError(
                "single-label base 'local' incorrectly matched 'printer.local'"
            )
        # But genuine private-TLD subdomains should still pass.
        if not s._is_same_domain("https://b.foo.local/x", "foo.local"):
            raise RuntimeError("foo.local subdomain incorrectly rejected")
        # Case-insensitivity (RFC 4343): mixed-case URL must still match
        # lower-cased base in the fallback path.
        if not s._is_same_domain("https://Blog.Corp.LOCAL/x", "corp.local"):
            raise RuntimeError("mixed-case URL did not match lower-cased base")
        if not s._is_same_domain("https://corp.local/x", "Blog.Corp.LOCAL"):
            raise RuntimeError("mixed-case base did not match lower-cased URL")
        return "fallback safely rejects unrelated suffixes + degenerate labels + case-insensitive"
    _selftest_run(report, "same_domain_fallback_rejects_unrelated",
                  _t_same_domain_fallback_rejects_unrelated,
                  fail_fast_hint="AdvancedEmailScraper._is_same_domain dot-boundary fallback")

    # Audit-prompt residual fixes (PR #9).

    # 78. file_handler swap is exception-safe: a failing FileHandler
    # constructor must NOT leave the global file_handler unset / detached.
    def _t_file_handler_swap_atomic():
        import inspect as _inspect
        # Read the source of the function that swaps file_handler. The
        # safety property: new handler is constructed BEFORE the old one
        # is removed, so a constructor failure leaves the old handler in
        # place and the new one is never assigned.
        # Locate the function by scanning the module source for the marker.
        with open(__file__, "r", encoding="utf-8") as f:
            src = f.read()
        # The marker phrase from the new comment we added.
        if "Build the new handler before touching the old one" not in src:
            raise RuntimeError(
                "file_handler swap is still vulnerable: new handler must be "
                "constructed before the old one is removed"
            )
        return "file_handler swap constructs new handler before removing old"
    _selftest_run(report, "file_handler_swap_atomic", _t_file_handler_swap_atomic,
                  fail_fast_hint="run_scraper_instance file_handler reassignment")

    # 79. Greylisted addresses are deferred to --reverify-unknown rather
