    # 84. setup_output_directory uses atomic os.mkdir (TOCTOU-safe).
    def _t_setup_output_dir_toctou_safe():
        import inspect as _inspect
        src = _inspect.getsource(setup_output_directory)
        # The race-safe path uses os.mkdir which raises FileExistsError;
        # confirm the catch is wired.
        if "FileExistsError" not in src or "os.mkdir(" not in src:
            raise RuntimeError(
                "setup_output_directory still uses non-atomic exists()+makedirs()"
            )
        # Live test: a populated run dir must NOT be recycled. Pre-existing
        # behaviour intentionally reclaims *empty* run dirs to avoid disk
        # bloat; the TOCTOU concern is that a populated dir gets stomped.
        prev_cwd = os.getcwd()
        try:
            sandbox = os.path.join(sandbox_root, "toctou_test")
            os.makedirs(sandbox, exist_ok=True)
            os.chdir(sandbox)
            d1 = setup_output_directory()
            # Mark d1 as "completed" so it won't be reclaimed.
            os.makedirs(os.path.join(d1, "CSV"), exist_ok=True)
            with open(os.path.join(d1, "CSV", "x.csv"), "w") as f:
                f.write("ok")
            d2 = setup_output_directory()
            if d1 == d2:
                raise RuntimeError("populated run dir was overwritten by next call")
        finally:
            os.chdir(prev_cwd)
        return "setup_output_directory atomically claims unique run number"
    _selftest_run(report, "setup_output_dir_toctou_safe", _t_setup_output_dir_toctou_safe,
                  fail_fast_hint="setup_output_directory os.mkdir + retry")

