# ===================================================================
# 1. DOMAIN NORMALISATION
# ===================================================================
class TestDomainNormalisation(unittest.TestCase):

    def test_basic_domain(self):
        self.assertEqual(normalize_domain("example.com"), "example.com")

    def test_with_scheme(self):
        self.assertEqual(normalize_domain("https://Example.com"), "example.com")

    def test_with_www(self):
        self.assertEqual(normalize_domain("https://www.Example.COM"), "example.com")

    def test_with_path(self):
        self.assertEqual(normalize_domain("example.com/contact/team"), "example.com")

    def test_with_port(self):
        self.assertEqual(normalize_domain("example.com:8080"), "example.com")

    def test_with_query_fragment(self):
        self.assertEqual(
            normalize_domain("https://www.Example.COM/contact?x=1#frag"),
            "example.com",
        )

    def test_trailing_dot(self):
        self.assertEqual(normalize_domain("  example.com.  "), "example.com")

    def test_comment_line(self):
        self.assertIsNone(normalize_domain("# this is a comment"))

    def test_empty_string(self):
        self.assertIsNone(normalize_domain(""))

    def test_none_input(self):
        self.assertIsNone(normalize_domain(None))

    def test_ip_literal_rejected(self):
        self.assertIsNone(normalize_domain("127.0.0.1"))

    def test_single_label_rejected(self):
        self.assertIsNone(normalize_domain("localhost"))

    def test_subdomain_preserved(self):
        self.assertEqual(normalize_domain("www.foo.bar.example.com"), "foo.bar.example.com")

    def test_http_scheme(self):
        self.assertEqual(normalize_domain("HTTP://EXAMPLE.com:8080"), "example.com")

    def test_domain_list_dedup(self):
        result = normalize_domain_list([
            "https://example.com",
            "EXAMPLE.com",
            "www.example.com/contact",
            "other.org",
            "",
            "# comment",
        ])
        self.assertEqual(result, ["example.com", "other.org"])

    def test_domain_list_preserves_order(self):
        result = normalize_domain_list(["b.org", "a.org", "c.org"])
        self.assertEqual(result, ["b.org", "a.org", "c.org"])


