class TestEmailExtraction(unittest.TestCase):

    def _make_scraper(self):
        tmpdir = tempfile.mkdtemp()
        s = AdvancedEmailScraper(
            domains=[], output_dir=tmpdir, logs_dir=tmpdir,
            settings=DEFAULT_SETTINGS,
        )
        return s, tmpdir

    def tearDown(self):
        if hasattr(self, '_tmpdir') and os.path.isdir(self._tmpdir):
            shutil.rmtree(self._tmpdir, ignore_errors=True)

    def test_basic_email_extraction(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>Contact us at alice@acmecorp.org for info.</body></html>"
            emails = s._extract_emails(html)
            self.assertIn("alice@acmecorp.org", emails)
        finally:
            s.close()

    def test_mailto_extraction(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = '<html><body><a href="mailto:bob@acmecorp.org">Email</a></body></html>'
            emails = s._extract_emails(html)
            self.assertIn("bob@acmecorp.org", emails)
        finally:
            s.close()

    def test_blacklisted_domain_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>test@example.com and real@realcorp.org</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn("test@example.com", emails)
        finally:
            s.close()

    def test_hex_hash_user_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>abcdef1234567890abcdef@domain.com</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn("abcdef1234567890abcdef@domain.com", emails)
        finally:
            s.close()

    def test_long_user_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            long_user = "a" * 36
            html = f"<html><body>{long_user}@domain.com</body></html>"
            emails = s._extract_emails(html)
            self.assertEqual(len(emails), 0)
        finally:
            s.close()

    def test_image_domain_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>user@images.png</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn("user@images.png", emails)
        finally:
            s.close()

    def test_css_js_domain_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>user@styles.css and user@scripts.js</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn("user@styles.css", emails)
            self.assertNotIn("user@scripts.js", emails)
        finally:
            s.close()

    def test_dotdot_user_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>user..name@domain.com</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn("user..name@domain.com", emails)
        finally:
            s.close()

    def test_leading_dot_user_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>.user@domain.com</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn(".user@domain.com", emails)
        finally:
            s.close()

    def test_eg_prefix_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>e.g.user@domain.com and real@realcorp.org</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn("e.g.user@domain.com", emails)
        finally:
            s.close()

    def test_sentry_substring_filtered(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = "<html><body>alert@sentry.io</body></html>"
            emails = s._extract_emails(html)
            self.assertNotIn("alert@sentry.io", emails)
        finally:
            s.close()

    def test_multiple_emails_on_page(self):
        s, self._tmpdir = self._make_scraper()
        try:
            html = """<html><body>
            Contact: alice@acmecorp.org
            Sales: sales@acmecorp.org
            <a href="mailto:support@acmecorp.org">Support</a>
            </body></html>"""
            emails = s._extract_emails(html)
            self.assertTrue(len(emails) >= 2)
        finally:
            s.close()


