class TestCoverageDecoders(unittest.TestCase):

    def setUp(self):
        self.email_regex = re.compile(r'\b[\w.%+-]+@[\w.-]+\.[\w]{2,}\b', re.UNICODE)

    def test_jsonld_email_extraction(self):
        html = '''<html><body>
        <script type="application/ld+json">
        {"@type": "Organization", "email": "org@example.com"}
        </script>
        </body></html>'''
        soup = BeautifulSoup(html, 'html.parser')
        result = extract_emails_from_jsonld(soup, self.email_regex)
        self.assertIn("org@example.com", result)

    def test_jsonld_contact_point(self):
        html = '''<html><body>
        <script type="application/ld+json">
        {"@type": "Organization", "contactPoint": {"email": "cp@example.com"}}
        </script>
        </body></html>'''
        soup = BeautifulSoup(html, 'html.parser')
        result = extract_emails_from_jsonld(soup, self.email_regex)
        self.assertIn("cp@example.com", result)

    def test_jsonld_email_list(self):
        html = '''<html><body>
        <script type="application/ld+json">
        {"@type": "Organization", "email": ["a@example.com", "b@example.com"]}
        </script>
        </body></html>'''
        soup = BeautifulSoup(html, 'html.parser')
        result = extract_emails_from_jsonld(soup, self.email_regex)
        self.assertIn("a@example.com", result)
        self.assertIn("b@example.com", result)

    def test_jsonld_malformed_json(self):
        html = '''<html><body>
        <script type="application/ld+json">
        {not valid json but has info@example.com}
        </script>
        </body></html>'''
        soup = BeautifulSoup(html, 'html.parser')
        result = extract_emails_from_jsonld(soup, self.email_regex)
        self.assertIn("info@example.com", result)

    def test_jsonld_none_soup(self):
        result = extract_emails_from_jsonld(None, self.email_regex)
        self.assertEqual(result, set())

    def test_data_attrs_extraction(self):
        html = '<html><body><div data-email="hidden@example.com"></div></body></html>'
        soup = BeautifulSoup(html, 'html.parser')
        result = extract_emails_from_data_attrs(soup, self.email_regex)
        self.assertIn("hidden@example.com", result)

    def test_data_attrs_html_encoded(self):
        html = '<html><body><div data-contact="user&#64;example.com"></div></body></html>'
        soup = BeautifulSoup(html, 'html.parser')
        result = extract_emails_from_data_attrs(soup, self.email_regex)
        self.assertIn("user@example.com", result)

    def test_data_attrs_none_soup(self):
        result = extract_emails_from_data_attrs(None, self.email_regex)
        self.assertEqual(result, set())

    def test_svg_text_extraction(self):
        html = '<html><body><svg><text>svg@example.com</text></svg></body></html>'
        soup = BeautifulSoup(html, 'html.parser')
        result = extract_emails_from_svg(soup, self.email_regex)
        self.assertIn("svg@example.com", result)

    def test_svg_none_soup(self):
        result = extract_emails_from_svg(None, self.email_regex)
        self.assertEqual(result, set())

    def test_rot13_decoding(self):
        # ROT13 of "test@example.com" is "grfg@rknzcyr.pbz"
        text = "Contact: grfg@rknzcyr.pbz"
        result = decode_rot13_emails(text, self.email_regex)
        self.assertIn("test@example.com", result)

    def test_js_concat_decoding(self):
        script = """var email = 'sec' + 'urity@' + 'site.com';"""
        result = decode_js_concat_emails(script, self.email_regex)
        self.assertIn("security@site.com", result)

    def test_js_concat_double_quotes(self):
        script = '''var e = "con" + "tact@" + "corp.org";'''
        result = decode_js_concat_emails(script, self.email_regex)
        self.assertIn("contact@corp.org", result)


# ===================================================================
# 4. ROBOTS.TXT PARSING
# ===================================================================
class TestRobotsRules(unittest.TestCase):

    def test_basic_disallow(self):
        text = "User-agent: *\nDisallow: /private\n"
        rules = _RobotsRules.parse(text)
        self.assertFalse(rules.is_allowed("/private"))
        self.assertTrue(rules.is_allowed("/public"))

    def test_allow_overrides_disallow(self):
        text = "User-agent: *\nDisallow: /dir\nAllow: /dir/public\n"
        rules = _RobotsRules.parse(text)
        self.assertFalse(rules.is_allowed("/dir/secret"))
        self.assertTrue(rules.is_allowed("/dir/public"))

    def test_crawl_delay(self):
        text = "User-agent: *\nCrawl-delay: 2.5\n"
        rules = _RobotsRules.parse(text)
        self.assertAlmostEqual(rules.crawl_delay, 2.5)

    def test_non_star_agent_ignored(self):
        text = "User-agent: Googlebot\nDisallow: /\n"
        rules = _RobotsRules.parse(text)
        self.assertTrue(rules.is_allowed("/"))

    def test_empty_text(self):
        rules = _RobotsRules.parse("")
        self.assertTrue(rules.is_allowed("/anything"))
        self.assertAlmostEqual(rules.crawl_delay, 0.0)

    def test_comments_in_robots(self):
        text = "User-agent: * # all bots\nDisallow: /admin # admin pages\n"
        rules = _RobotsRules.parse(text)
        self.assertFalse(rules.is_allowed("/admin"))

    def test_none_text(self):
        rules = _RobotsRules.parse(None)
        self.assertTrue(rules.is_allowed("/"))

    def test_multiple_disallows(self):
        text = "User-agent: *\nDisallow: /a\nDisallow: /b\n"
        rules = _RobotsRules.parse(text)
        self.assertFalse(rules.is_allowed("/a"))
        self.assertFalse(rules.is_allowed("/b"))
        self.assertTrue(rules.is_allowed("/c"))


