class TestSitemapParsing(unittest.TestCase):

    def test_basic_sitemap(self):
        xml = b"""<?xml version="1.0"?>
        <urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
          <url><loc>https://example.com/</loc></url>
          <url><loc>https://example.com/contact</loc></url>
        </urlset>"""
        pages, children = parse_sitemap_xml(xml)
        self.assertEqual(len(pages), 2)
        self.assertEqual(len(children), 0)

    def test_sitemap_index(self):
        xml = b"""<?xml version="1.0"?>
        <sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
          <sitemap><loc>https://example.com/sitemap-posts.xml</loc></sitemap>
          <sitemap><loc>https://example.com/sitemap-pages.xml</loc></sitemap>
        </sitemapindex>"""
        pages, children = parse_sitemap_xml(xml)
        self.assertEqual(len(pages), 0)
        self.assertEqual(len(children), 2)

    def test_empty_bytes(self):
        pages, children = parse_sitemap_xml(b"")
        self.assertEqual(pages, [])
        self.assertEqual(children, [])

    def test_filter_contact_keywords(self):
        urls = [
            "https://example.com/contact",
            "https://example.com/about/team",
            "https://example.com/products/widget",
            "https://example.com/blog/post-1",
            "https://example.com/security/disclosure",
        ]
        kept = filter_sitemap_urls(urls, host_filter="example.com")
        self.assertIn("https://example.com/contact", kept)
        self.assertIn("https://example.com/about/team", kept)
        self.assertIn("https://example.com/security/disclosure", kept)
        self.assertNotIn("https://example.com/products/widget", kept)
        self.assertNotIn("https://example.com/blog/post-1", kept)

    def test_filter_host_restriction(self):
        urls = [
            "https://example.com/contact",
            "https://other.com/contact",
        ]
        kept = filter_sitemap_urls(urls, host_filter="example.com")
        self.assertEqual(len(kept), 1)
        self.assertIn("https://example.com/contact", kept)

    def test_filter_dedup(self):
        urls = ["https://example.com/contact", "https://example.com/contact"]
        kept = filter_sitemap_urls(urls, host_filter="example.com")
        self.assertEqual(len(kept), 1)

    def test_filter_www_prefix_strip(self):
        urls = ["https://www.walmart.com/contact-us"]
        kept = filter_sitemap_urls(urls, host_filter="walmart.com")
        self.assertEqual(len(kept), 1)


# ===================================================================
# 6. RATE LIMITER
# ===================================================================
class TestDomainRateLimiter(unittest.TestCase):

    def test_basic_acquire(self):
        rl = DomainRateLimiter(default_rps=100.0, default_burst=10)
        self.assertTrue(rl.acquire("example.com", max_wait=0.1))

    def test_burst_exhaustion(self):
        rl = DomainRateLimiter(default_rps=1.0, default_burst=2)
        self.assertTrue(rl.acquire("example.com", max_wait=0.01))
        self.assertTrue(rl.acquire("example.com", max_wait=0.01))
        # Third should fail with very short wait.
        self.assertFalse(rl.acquire("example.com", max_wait=0.01))

    def test_configure_domain(self):
        rl = DomainRateLimiter(default_rps=100.0, default_burst=10)
        rl.configure_domain("slow.com", crawl_delay=10.0)
        self.assertTrue(rl.acquire("slow.com", max_wait=0.01))

    def test_empty_domain(self):
        rl = DomainRateLimiter()
        self.assertTrue(rl.acquire("", max_wait=0.01))
        self.assertTrue(rl.acquire(None, max_wait=0.01))

    def test_independent_domains(self):
        rl = DomainRateLimiter(default_rps=1.0, default_burst=1)
        self.assertTrue(rl.acquire("a.com", max_wait=0.01))
        self.assertTrue(rl.acquire("b.com", max_wait=0.01))
        self.assertFalse(rl.acquire("a.com", max_wait=0.01))


