# ===================================================================
# 9. AUTOTUNE CONCURRENCY
# ===================================================================
class TestAutotuneConcurrency(unittest.TestCase):

    def test_low_bandwidth(self):
        r = autotune_concurrency({"ok": True, "mbps": 2.0, "rtt_ms": 150})
        self.assertLessEqual(r["threads"], 12)

    def test_medium_bandwidth(self):
        r = autotune_concurrency({"ok": True, "mbps": 30.0, "rtt_ms": 80})
        self.assertGreaterEqual(r["threads"], 20)
        self.assertLessEqual(r["threads"], 40)

    def test_high_bandwidth(self):
        r = autotune_concurrency({"ok": True, "mbps": 200.0, "rtt_ms": 50})
        self.assertGreaterEqual(r["threads"], 60)

    def test_failed_measurement(self):
        r = autotune_concurrency({"ok": False})
        self.assertLessEqual(r["threads"], 12)

    def test_high_rtt_clamps(self):
        r = autotune_concurrency({"ok": True, "mbps": 200.0, "rtt_ms": 1500})
        self.assertLess(r["threads"], 60)

    def test_explicit_cli_threads(self):
        r = autotune_concurrency({"ok": True, "mbps": 100, "rtt_ms": 50}, cli_threads=7)
        self.assertEqual(r["threads"], 7)

    def test_verifier_concurrency_capped_at_300(self):
        r = autotune_concurrency({"ok": True, "mbps": 100, "rtt_ms": 50}, cli_threads=200)
        self.assertLessEqual(r["verifier_concurrency"], 300)


