class TestDecodeSmtpMsg(unittest.TestCase):

    def test_bytes_input(self):
        result = _decode_smtp_msg(b"450 Try again later")
        self.assertIn("450", result)

    def test_str_input(self):
        result = _decode_smtp_msg("550 No such user")
        self.assertIn("550", result)

