# ===================================================================
# 15. CONTENT-HASH DEDUP
# ===================================================================
class TestContentHashDedup(unittest.TestCase):

    def _make_scraper(self):
        tmpdir = tempfile.mkdtemp()
        s = AdvancedEmailScraper(
            domains=[], output_dir=tmpdir, logs_dir=tmpdir,
            settings=DEFAULT_SETTINGS,
        )
        return s, tmpdir

    def test_first_body_not_deduped(self):
        s, tmpdir = self._make_scraper()
        try:
            body = b"<html>unique content</html>"
            self.assertFalse(s._record_response_seen("a.com", body))
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_duplicate_body_deduped(self):
        s, tmpdir = self._make_scraper()
        try:
            body = b"<html>same content</html>"
            s._record_response_seen("a.com", body)
            self.assertTrue(s._record_response_seen("a.com", body))
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_different_domains_independent(self):
        s, tmpdir = self._make_scraper()
        try:
            body = b"<html>shared body</html>"
            s._record_response_seen("a.com", body)
            self.assertFalse(s._record_response_seen("b.com", body))
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_cap_enforcement(self):
        s, tmpdir = self._make_scraper()
        s._CONTENT_HASH_CAP = 3
        try:
            for i in range(5):
                s._record_response_seen("a.com", f"body{i}".encode())
            # First 2 should have been evicted.
            self.assertFalse(s._record_response_seen("a.com", b"body0"))
            self.assertFalse(s._record_response_seen("a.com", b"body1"))
            # Last ones should still be there.
            self.assertTrue(s._record_response_seen("a.com", b"body4"))
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_empty_body_not_recorded(self):
        s, tmpdir = self._make_scraper()
        try:
            self.assertFalse(s._record_response_seen("a.com", b""))
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)


