# 17. ADAPTIVE DEPTH PROMOTION
# ===================================================================
class TestAdaptiveDepthPromotion(unittest.TestCase):

    def _make_scraper(self):
        tmpdir = tempfile.mkdtemp()
        s = AdvancedEmailScraper(
            domains=["example.com"], output_dir=tmpdir, logs_dir=tmpdir,
            settings=DEFAULT_SETTINGS,
        )
        return s, tmpdir

    def test_no_promotion_when_emails_found(self):
        s, tmpdir = self._make_scraper()
        try:
            s.domain_email_progress["example.com"] = {"emails": 5, "urls": 10}
            s._maybe_extend_depth_for_domain("example.com")
            self.assertNotIn("example.com", s.deep_promoted_domains)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_no_promotion_below_threshold(self):
        s, tmpdir = self._make_scraper()
        try:
            s.domain_email_progress["example.com"] = {"emails": 0, "urls": 1}
            s._maybe_extend_depth_for_domain("example.com")
            self.assertNotIn("example.com", s.deep_promoted_domains)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_promotion_fires_once(self):
        s, tmpdir = self._make_scraper()
        try:
            s.domain_email_progress["example.com"] = {"emails": 0, "urls": 5}
            s.general_links_discovered["example.com"] = {"https://example.com/about"}
            s._maybe_extend_depth_for_domain("example.com")
            self.assertIn("example.com", s.deep_promoted_domains)
            queue_len = len(s.crawl_queue)
            # Second call should NOT add more items.
            s._maybe_extend_depth_for_domain("example.com")
            self.assertEqual(len(s.crawl_queue), queue_len)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)


