# ===================================================================
# 19. INTERNET CONNECTION CHECK (bug fix: broader exception handling)
# ===================================================================
class TestInternetConnectionCheck(unittest.TestCase):

    def _make_scraper(self):
        tmpdir = tempfile.mkdtemp()
        s = AdvancedEmailScraper(
            domains=[], output_dir=tmpdir, logs_dir=tmpdir,
            settings=DEFAULT_SETTINGS,
        )
        return s, tmpdir

    def test_connection_success(self):
        s, tmpdir = self._make_scraper()
        try:
            s.session.head = MagicMock(return_value=MagicMock(status_code=200))
            self.assertTrue(s._check_internet_connection())
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_connection_error(self):
        s, tmpdir = self._make_scraper()
        try:
            import requests as _req
            s.session.head = MagicMock(side_effect=_req.exceptions.ConnectionError("no route"))
            self.assertFalse(s._check_internet_connection())
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_timeout_error(self):
        """Bug fix: Timeout should also return False, not crash."""
        s, tmpdir = self._make_scraper()
        try:
            import requests as _req
            s.session.head = MagicMock(side_effect=_req.exceptions.Timeout("timed out"))
            self.assertFalse(s._check_internet_connection())
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_ssl_error(self):
        """Bug fix: SSL errors should also return False, not crash."""
        s, tmpdir = self._make_scraper()
        try:
            import requests as _req
            s.session.head = MagicMock(side_effect=_req.exceptions.SSLError("cert verify failed"))
            self.assertFalse(s._check_internet_connection())
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_probe_routed_through_session(self):
        """_check_internet_connection must use the configured stealth
        session (which honours the proxy chain), NOT a fresh top-level
        ``requests.head`` call. Previously the probe leaked the operator's
        real IP whenever --proxies was active.
        """
        s, tmpdir = self._make_scraper()
        try:
            s.session.head = MagicMock(return_value=MagicMock(status_code=200))
            self.assertTrue(s._check_internet_connection())
            self.assertGreaterEqual(s.session.head.call_count, 1,
                                    "_check_internet_connection must route the probe via self.session")
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)


