class TestHistoryDB(unittest.TestCase):

    def test_create_and_close(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = os.path.join(tmpdir, "test_history.db")
            db = EmailHistoryDB(db_path)
            db.start_run(run_id="test-1", cli_args="--self-test",
                          python_ver="3.11", git_sha="abc123")
            db.close()
            self.assertTrue(os.path.isfile(db_path))

    def test_record_email(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = os.path.join(tmpdir, "test_history.db")
            db = EmailHistoryDB(db_path)
            db.start_run(run_id="test-2", cli_args="",
                          python_ver="3.11", git_sha="abc")
            db.record_email(
                domain="b.com",
                email="a@b.com",
                prioritized=True,
                source_type="crawl",
            )
            db.close()
            self.assertTrue(os.path.isfile(db_path))
            conn = sqlite3.connect(db_path)
            try:
                rows = conn.execute(
                    "SELECT domain, email, prioritized, source_type FROM emails"
                ).fetchall()
                self.assertEqual(len(rows), 1)
                self.assertEqual(rows[0][0], "b.com")
                self.assertEqual(rows[0][1], "a@b.com")
                self.assertEqual(rows[0][2], 1)
                self.assertEqual(rows[0][3], "crawl")
            finally:
                conn.close()

    def test_close_idempotent(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            db_path = os.path.join(tmpdir, "test_history.db")
            db = EmailHistoryDB(db_path)
            db.close()
            db.close()  # Should not raise.


