# ===================================================================
class TestExtractionEdgeCases(unittest.TestCase):

    def _make_scraper(self):
        tmpdir = tempfile.mkdtemp()
        s = AdvancedEmailScraper(
            domains=[], output_dir=tmpdir, logs_dir=tmpdir,
            settings=DEFAULT_SETTINGS,
        )
        return s, tmpdir

    def test_empty_html(self):
        s, tmpdir = self._make_scraper()
        try:
            emails = s._extract_emails("")
            self.assertEqual(len(emails), 0)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_no_at_sign_filtered(self):
        s, tmpdir = self._make_scraper()
        try:
            html = "<html><body>not-an-email.com</body></html>"
            emails = s._extract_emails(html)
            self.assertEqual(len(emails), 0)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_cloudflare_email_decode(self):
        s, tmpdir = self._make_scraper()
        try:
            # Standard Cloudflare encoded email pattern.
            # data-cfemail XOR key=0x0e decodes to "hello@testdomain.com".
            html = '''<html><body>
            <a href="/cdn-cgi/l/email-protection" class="__cf_email__"
               data-cfemail="0e666b6262614e7a6b7d7a6a61636f6760206d6163">
               [email protected]
            </a>
            </body></html>'''
            emails = s._extract_emails(html)
            self.assertIn("hello@testdomain.com", emails,
                          "Cloudflare XOR decoder should extract the email")
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_decode_cf_xor_string_directly(self):
        """Direct unit test for ``_decode_cf_xor_string`` (the Cloudflare
        XOR primitive used by both ``_decode_cloudflare_emails`` and
        ``_decode_cloudflare_hrefs``). Tests valid input, invalid hex,
        odd-length input, non-ASCII output, and the strict-ASCII reject."""
        s, tmpdir = self._make_scraper()
        try:
            # Known test vector: encoded with XOR key=0x0e
            # plaintext = "ab@testdomain.com" (local part >= 2 chars for regex)
            # First 2 hex chars = key (0x0e), remaining = data XOR key
            encoded = "0e6f6c4e7a6b7d7a6a61636f6760206d6163"
            decoded = s._decode_cf_xor_string(encoded)
            with self.subTest("valid decode"):
                self.assertEqual(decoded, "ab@testdomain.com")

            with self.subTest("invalid hex"):
                self.assertIsNone(s._decode_cf_xor_string("0exyzzzz"))

            with self.subTest("odd-length hex"):
                self.assertIsNone(s._decode_cf_xor_string("0e1"))

            with self.subTest("too short"):
                self.assertIsNone(s._decode_cf_xor_string("0e"))

            with self.subTest("empty input"):
                self.assertIsNone(s._decode_cf_xor_string(""))
                self.assertIsNone(s._decode_cf_xor_string(None))

            evil = "0e" + "00" + ("0e" * 10)
            with self.subTest("NUL byte rejection"):
                self.assertIsNone(s._decode_cf_xor_string(evil))

            with self.subTest("email validation reject"):
                self.assertIsNone(s._decode_cf_xor_string(
                    "0e" + "".join(f"{ord(c) ^ 0x0e:02x}" for c in "notvalid")
                ))
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_deobfuscate_emails_directly(self):
        """Direct unit test for ``_deobfuscate_emails`` which replaces
        common obfuscation patterns like ``[at]`` / ``(at)`` with ``@``,
        and ``[dot]`` / ``(dot)`` with ``.`` before running the email
        regex."""
        s, tmpdir = self._make_scraper()
        try:
            # [at] / [dot] pattern
            result = s._deobfuscate_emails("hello[at]example[dot]com")
            self.assertIn("hello@example.com", result)

            # (at) / (dot) pattern
            result = s._deobfuscate_emails("user(at)domain(dot)org")
            self.assertIn("user@domain.org", result)

            # HTML entities
            result = s._deobfuscate_emails("info&#x40;site&#x2E;com")
            self.assertIn("info@site.com", result)

            # Text without email → empty set.
            self.assertEqual(s._deobfuscate_emails("no email here"), set())

            # Empty text → empty set.
            self.assertEqual(s._deobfuscate_emails(""), set())

            # Mixed patterns on a single page.
            result = s._deobfuscate_emails(
                "Contact: alice[at]corp[dot]com or bob(at)work(dot)net"
            )
            self.assertIn("alice@corp.com", result)
            self.assertIn("bob@work.net", result)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_mixed_case_normalised(self):
        s, tmpdir = self._make_scraper()
        try:
            html = "<html><body>Alice@AcmeCorp.ORG</body></html>"
            emails = s._extract_emails(html)
            self.assertGreater(len(emails), 0,
                               "should have extracted at least one email from mixed-case input")
            for e in emails:
                self.assertEqual(e, e.lower(), f"email {e!r} was not lowercased")
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)


