class TestPlaceholderDomainFilter(unittest.TestCase):
    """``_is_placeholder_domain`` rejects known placeholder / demo
    domains while allowing real corporate domains through."""

    def test_rejects_placeholder_domains(self):
        for em in (
            "user@acmeinc.com",
            "alex@companyemail.com",
            "info@contoso.com",
            "hello@acme.io",
            "test@co.com",
            "admin@example.com",
        ):
            self.assertTrue(_is_placeholder_domain(em),
                            f"{em} should be rejected as placeholder")

