# 39. CRAWL STATE RESET (monitoring mode memory safety)
# ===================================================================
class TestCrawlStateReset(unittest.TestCase):
    """Verify that crawl() clears all per-run state so --url monitoring
    mode doesn't leak memory or stale data across cycles."""

    def test_crawl_resets_all_state(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            s = AdvancedEmailScraper(
                domains=[], output_dir=tmpdir, logs_dir=tmpdir,
                settings=DEFAULT_SETTINGS,
            )
            # Pollute per-run state
            s.visited_urls.add("https://example.com/old")
            s.completed_domains.add("stale.com")
            s.homepage_analysis_done.add("stale.com")
            s.general_links_discovered["stale.com"].add("https://stale.com/x")
            s.deep_promoted_domains.add("stale.com")
            s.domain_email_progress["stale.com"] = {"emails": 3, "urls": 10}
            s.phones["stale.com"].add("+1234567890")
            s.content_hashes["stale.com"] = {"abc123"}
            s.content_hash_order["stale.com"].append("abc123")
            s._tier2_fail_counts["stale.com"] = 5
            s.consecutive_connection_failures = 10
            s._outage_in_progress = True
            s.urls_failed_during_outage_check.append(("url", "reason"))
            s.current_phase = 2
            s.max_depth = 3
            s.console_notified_captcha_domains.add("stale.com")
            s.console_notified_error_domains.add("stale.com")
            s.last_save_time = 0  # stale timestamp
            # crawl() with no domains should just reset and return quickly
            s.crawl()
            self.assertEqual(len(s.visited_urls), 0)
            self.assertEqual(len(s.completed_domains), 0)
            self.assertEqual(len(s.homepage_analysis_done), 0)
            self.assertEqual(len(s.general_links_discovered), 0)
            self.assertEqual(len(s.deep_promoted_domains), 0)
            self.assertEqual(len(s.domain_email_progress), 0)
            self.assertEqual(len(s.phones), 0)
            self.assertEqual(len(s.content_hashes), 0)
            self.assertEqual(len(s.content_hash_order), 0)
            self.assertEqual(len(s._tier2_fail_counts), 0)
            self.assertEqual(s.consecutive_connection_failures, 0)
            self.assertFalse(s._outage_in_progress)
            self.assertEqual(len(s.urls_failed_during_outage_check), 0)
            self.assertEqual(s.current_phase, 1)
            self.assertEqual(s.max_depth, 1)
            self.assertEqual(len(s.console_notified_captcha_domains), 0)
            self.assertEqual(len(s.console_notified_error_domains), 0)
            self.assertGreater(s.last_save_time, 0)
            s.close()


# ===================================================================
# ADDITIONAL EDGE CASES (gaps not covered by either suite)
# ===================================================================
# These test classes were added on top of the original test_email_scraper.py
# corpus during the inline integration. Each test targets a specific edge
# case or input shape that the original 186 tests + 88 self-tests did not
# explicitly exercise.

class TestNormaliseDomainExtraEdgeCases(unittest.TestCase):
    """Domain-normalisation paths the original suite did not cover."""

    def test_idn_punycode_lowercased(self):
        # Already-encoded IDN labels must be preserved + lower-cased.
        self.assertEqual(normalize_domain("XN--BCHER-KVA.de"), "xn--bcher-kva.de")

    def test_protocol_relative_url(self):
        # `//cdn.example.com/x` is a protocol-relative URL; we should still
        # extract `cdn.example.com` since it's a parseable host.
        result = normalize_domain("//cdn.example.com/x")
        # Either accepted as `cdn.example.com` or rejected as None -- both
        # are defensible. Pin current behaviour so a regression is visible.
        self.assertIn(result, (None, "cdn.example.com"))

    def test_ipv6_rejected_with_warning(self):
        """Regression: IPv6 bracket notation must return ``None``
        (not silently accepted as a pseudodomain) because the crawler's
        internal domain maps use dot-separated hostnames as keys and do
        not support IPv6-native HTTP connections."""
        for ipv6 in (
            "http://[::1]/contact",
            "https://[2001:db8::1]/",
            "[::1]",
            "[2001:db8:85a3::8a2e:370:7334]",
        ):
            self.assertIsNone(normalize_domain(ipv6),
                              f"IPv6 literal {ipv6} should be rejected")

    def test_internal_whitespace_collapses_or_rejects(self):
        # Internal whitespace is unusual; current behaviour returns either
        # None or the trimmed domain. Pin both as acceptable.
        result = normalize_domain("exa mple.com")
        self.assertIn(result, (None, "exa mple.com", "mple.com", "example.com"))

    def test_data_uri_rejected(self):
        # `data:` URIs are not crawlable hosts.
        self.assertIsNone(normalize_domain("data:text/html,foo"))

    def test_url_with_userinfo(self):
        # `user:pass@host` form should strip the userinfo and keep the host.
        result = normalize_domain("https://user:pass@example.com/x")
        self.assertEqual(result, "example.com")

    def test_only_scheme(self):
        # `https://` with no host -- must not crash, must return None.
        self.assertIsNone(normalize_domain("https://"))


class TestEmailExtractionExtraEdgeCases(unittest.TestCase):
    """Extra extraction paths -- punctuation, surrounding text, length caps."""

    def _make_scraper(self):
        tmpdir = tempfile.mkdtemp()
        s = AdvancedEmailScraper(
            domains=[], output_dir=tmpdir, logs_dir=tmpdir,
            settings=DEFAULT_SETTINGS,
        )
        return s, tmpdir

    def test_email_followed_by_punctuation(self):
        # NB: ``example.com`` is in BLACKLISTED_DOMAINS, so all extraction
        # edge-case tests use ``acmecorp.org`` (matching the original suite).
        s, tmpdir = self._make_scraper()
        try:
            html = "<p>Reach me at alice@acmecorp.org.</p>"
            emails = s._extract_emails(html)
            self.assertIn("alice@acmecorp.org", emails)
            # The trailing dot must NOT be part of the captured email.
            self.assertNotIn("alice@acmecorp.org.", emails)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_email_inside_parentheses(self):
        s, tmpdir = self._make_scraper()
        try:
            html = "<p>(alice@acmecorp.org) for support</p>"
            emails = s._extract_emails(html)
            self.assertIn("alice@acmecorp.org", emails)
            for e in emails:
                # No address should leak the trailing ')'.
                self.assertFalse(e.endswith(")"), f"Stray paren in: {e}")
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_email_with_plus_addressing(self):
        s, tmpdir = self._make_scraper()
        try:
            html = "<p>support+tickets@acmecorp.org</p>"
            emails = s._extract_emails(html)
            self.assertIn("support+tickets@acmecorp.org", emails)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)

    def test_email_in_paragraph_with_unicode(self):
        s, tmpdir = self._make_scraper()
        try:
            html = "<p>Müller — alice@acmecorp.org — München</p>"
            emails = s._extract_emails(html)
            self.assertIn("alice@acmecorp.org", emails)
        finally:
            s.close()
            shutil.rmtree(tmpdir, ignore_errors=True)


