class TestRobotsRulesExtraEdgeCases(unittest.TestCase):
    """Robots.txt directives the original suite did not exercise."""

    def test_sitemap_directive_does_not_crash(self):
        # `Sitemap:` lines are informational; parser must accept them.
        text = ("User-agent: *\n"
                "Disallow: /admin\n"
                "Sitemap: https://example.com/sitemap.xml\n")
        rules = _RobotsRules.parse(text)
        self.assertFalse(rules.is_allowed("/admin/users"))
        self.assertTrue(rules.is_allowed("/public"))

    def test_blank_disallow_means_allow_all(self):
        # `Disallow:` with empty value means "no restrictions" per RFC 9309.
        text = "User-agent: *\nDisallow:\n"
        rules = _RobotsRules.parse(text)
        self.assertTrue(rules.is_allowed("/anything"))

    def test_robots_with_crlf_line_endings(self):
        # Windows-style line endings must parse identically.
        text = "User-agent: *\r\nDisallow: /private\r\n"
        rules = _RobotsRules.parse(text)
        self.assertFalse(rules.is_allowed("/private/x"))


class TestRateLimiterExtraEdgeCases(unittest.TestCase):
    """DomainRateLimiter behavior under concurrency + bad config."""

    def test_low_rate_fast_fails_with_max_wait(self):
        # Very-low-rate domain: the second consume must respect ``max_wait``
        # and not block past it.
        rl = DomainRateLimiter(default_rps=0.1, default_burst=1)
        # First token is in the burst, so it should succeed.
        self.assertTrue(rl.acquire("example.com", max_wait=0.1))
        # Second should fast-fail at max_wait.
        start = time.time()
        rl.acquire("example.com", max_wait=0.2)
        elapsed = time.time() - start
        self.assertLess(elapsed, 1.5,
                        f"acquire blocked {elapsed:.2f}s past max_wait")

    def test_configure_domain_acquires_per_bucket_lock(self):
        """Regression: ``configure_domain`` must acquire the per-bucket
        lock before mutating ``rps`` / ``burst`` so that a concurrent
        ``acquire`` call (which reads those fields under ``bucket["lock"]``)
        sees a consistent snapshot. Without this, the refill formula
        ``tokens + elapsed * rps`` could mix old tokens with new rps.

        This test drives 20 concurrent threads: half calling
        ``configure_domain`` with ever-changing crawl_delay values,
        half calling ``acquire``. The test passes if no thread observes
        a corrupt state (crash, negative tokens, or acquire returning
        False when tokens should be available)."""
        rl = DomainRateLimiter(default_rps=100.0, default_burst=50)
        errors = []

        def configurer():
            try:
                for i in range(20):
                    rl.configure_domain("race.test", crawl_delay=random.uniform(0.01, 0.5))
                    time.sleep(0.001)
            except Exception as e:
                errors.append(e)

        def consumer():
            try:
                for _ in range(50):
                    rl.acquire("race.test", max_wait=1.0)
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=configurer) for _ in range(10)]
        threads += [threading.Thread(target=consumer) for _ in range(10)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=10)
        for t in threads:
            self.assertFalse(t.is_alive(), f"Thread {t.name} did not finish within 10s timeout")

        self.assertEqual(errors, [], f"Concurrent configure+acquire raised: {errors}")

    def test_concurrent_acquire_threadsafe(self):
        # 20 threads hammering one domain must not raise or corrupt state.
        rl = DomainRateLimiter(default_rps=100.0, default_burst=20)
        errors = []

        def worker():
            try:
                for _ in range(5):
                    rl.acquire("example.com", max_wait=0.5)
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=worker) for _ in range(20)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=15)
        for t in threads:
            self.assertFalse(t.is_alive(), f"Thread {t.name} did not finish within 15s timeout")
        self.assertEqual(errors, [], f"Concurrent acquire raised: {errors}")


class TestAcceptAllCacheExtraEdgeCases(unittest.TestCase):
    """ACCEPT_ALL_CACHE thread-safety and bounded-cap behaviour."""

    def setUp(self):
        with _ACCEPT_ALL_CACHE_LOCK:
            ACCEPT_ALL_CACHE.clear()

    def tearDown(self):
        with _ACCEPT_ALL_CACHE_LOCK:
            ACCEPT_ALL_CACHE.clear()

    def test_concurrent_put_threadsafe(self):
        errors = []

        def worker(start):
            try:
                for i in range(50):
                    _accept_all_cache_put(f"d{start}-{i}.com", i % 2 == 0)
            except Exception as e:
                errors.append(e)

        threads = [threading.Thread(target=worker, args=(i,)) for i in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join(timeout=5)
        self.assertEqual(errors, [], f"Concurrent put raised: {errors}")
        # Cache must hold no more than its documented cap.
        self.assertLessEqual(len(ACCEPT_ALL_CACHE), 10000)
        for i in range(8):
            val = _accept_all_cache_get(f"d{i}-0.com")
            self.assertIsNotNone(val, f"d{i}-0.com should be retrievable")
            self.assertIsInstance(val, bool)

    def test_get_after_clear(self):
        _accept_all_cache_put("foo.com", True)
        with _ACCEPT_ALL_CACHE_LOCK:
            ACCEPT_ALL_CACHE.clear()
        self.assertIsNone(_accept_all_cache_get("foo.com"))


