class TestGreylistExtraEdgeCases(unittest.TestCase):
    """Extra greylist-detection inputs."""

    def test_uppercase_keyword(self):
        self.assertTrue(is_greylist_response("GREYLISTED, please retry"))

    def test_smtp_4xx_response_code(self):
        # SMTP 4xx soft-fail with greylist text.
        self.assertTrue(is_greylist_response("450 4.7.1 Greylisted"))

    def test_550_hard_fail_not_greylist(self):
        # 5xx is a permanent rejection -- never greylist.
        self.assertFalse(is_greylist_response("550 No such user"))

    def test_470_policy_rejection_not_greylist(self):
        """Regression: SMTP ``4.7.0`` (security policy rejection, RFC 5321
        §7.1) must NOT be classified as greylisting. Exchange returns
        ``4.7.0`` for TLS-required rejections; treating it as greylist
        causes the verifier to retry indefinitely on addresses that will
        never be delivered.

        Note: ``4.7.0`` typically appears with a 4xx SMTP status code
        (e.g. ``421 4.7.0``) — in that case the 421 already triggers
        the transient-detection regex correctly. The bug was when
        ``4.7.0`` appeared inside a **permanent** rejection (5xx) or
        bare in wrapper text without a 4xx prefix, where the old
        text-substring tuple would match ``"4.7.0"`` and misclassify
        it as greylist."""
        for msg in (
            "RCPT TO rejected by mx:25 status=550; server='550 4.7.0 TLS required'",
            "550 4.7.0 TLS required for this domain",
            "554 5.7.0 4.7.0 Delivery not authorized",
        ):
            self.assertFalse(is_greylist_response(msg),
                             f"4.7.0 should NOT be greylist: {msg!r}")

    def test_471_policy_rejection_not_greylist(self):
        """Regression: SMTP ``4.7.1`` (delivery not authorized, RFC 5321
        §7.1) must NOT be classified as greylisting. Postfix returns
        ``4.7.1`` for mailbox-not-found; treating it as greylist causes
        the verifier to keep retrying addresses that will never be
        delivered.

        The bug was in the old text-substring tuple that matched bare
        ``"4.7.1"`` — a permanent rejection like ``"550 4.7.1 Delivery
        not authorized"`` would be miscategorised as transient greylist.

        ``4.7.1`` CAN appear alongside actual greylisting text
        (e.g. ``"450 4.7.1 Greylisting in effect"``). In those cases
        the greylisting keyword ``"greylist"`` (not the status code)
        is what triggers the correct greylist classification."""
        for msg in (
            "RCPT TO rejected by mx:25 status=550; server='550 4.7.1 User unknown'",
            "550 4.7.1 Delivery not authorized, message refused",
            "554 5.7.1 4.7.1 Sender denied",
            "4.7.1 User unknown in virtual mailbox table",
        ):
            self.assertFalse(is_greylist_response(msg),
                             f"4.7.1 should NOT be greylist: {msg!r}")

    def test_try_again_later_matches_but_bare_try_again_does_not(self):
        """Regression: ``"try again later"`` is a greylisting marker, but
        the bare substring ``"try again"`` was removed because it false-
        positives on non-greylist messages like ``"Authentication failed,
        try again"``."""
        # Must match (specific phrase):
        self.assertTrue(is_greylist_response("450 4.7.1 Try again later"))
        self.assertTrue(is_greylist_response("try again later"))
        # Must NOT match (bare substring without "later"):
        self.assertFalse(is_greylist_response("Authentication failed, try again"))

    def test_bare_deferred_does_not_match(self):
        """Regression: the bare word ``"deferred"`` was removed from
        greylist markers because it false-positives on backpressure
        messages like ``"Temporary message deferred due to queue depth"``.
        Only ``"temporarily deferred"`` (specific) should match."""
        self.assertFalse(is_greylist_response("Temporary message deferred due to queue depth"))
        self.assertFalse(is_greylist_response("Message deferred"))
        # Still matches with the specific phrase:
        self.assertTrue(is_greylist_response("temporarily deferred"))


class TestExtractJsonldExtraEdgeCases(unittest.TestCase):
    """JSON-LD shapes the original 4 jsonld tests did not cover."""

    def test_nested_publisher_email(self):
        if BeautifulSoup is None:
            self.skipTest("BeautifulSoup not available")
        html = '''<html><head>
<script type="application/ld+json">
{"@context":"https://schema.org","@type":"Article",
 "publisher":{"@type":"Organization","email":"editor@example.com"}}
</script></head><body></body></html>'''
        soup = BeautifulSoup(html, "html.parser")
        emails = extract_emails_from_jsonld(soup, re.compile(r"[A-Za-z0-9._+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"))
        self.assertIn("editor@example.com", emails)

    def test_array_of_organizations(self):
        if BeautifulSoup is None:
            self.skipTest("BeautifulSoup not available")
        html = '''<html><head>
<script type="application/ld+json">
[{"@type":"Organization","email":"a@example.com"},
 {"@type":"Organization","email":"b@example.com"}]
</script></head><body></body></html>'''
        soup = BeautifulSoup(html, "html.parser")
        emails = extract_emails_from_jsonld(soup, re.compile(r"[A-Za-z0-9._+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"))
        self.assertIn("a@example.com", emails)
        self.assertIn("b@example.com", emails)

    def test_nested_email_in_list_not_dropped(self):
        """Regression: when ``"email"`` is a list containing dict items,
        the ``_walk`` function previously only handled strings. Dict
        items inside the list were silently dropped because the ``elif
        k == "email" and isinstance(v, list)`` branch only iterated
        over string items. The fix adds ``else: _walk(item)`` so that
        non-string items are recursively walked, finding any nested
        ``email`` fields they contain.

        This shape is technically non-standard (schema.org types
        ``email`` as ``Text``), but scraped JSON-LD from real CMS /
        framework output can produce ``"email": [{...}]`` forms."""
        if BeautifulSoup is None:
            self.skipTest("BeautifulSoup not available")
        # Case 1: email is a list of dicts, each with their own email field.
        html1 = '''<html><head>
<script type="application/ld+json">
{"@type":"Organization","email":[
    {"@type":"ContactPoint","email":"a@example.com"},
    {"@type":"ContactPoint","email":"b@example.com"}
]}
</script></head><body></body></html>'''
        soup1 = BeautifulSoup(html1, "html.parser")
        emails1 = extract_emails_from_jsonld(soup1, re.compile(r"[A-Za-z0-9._+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"))
        self.assertIn("a@example.com", emails1)
        self.assertIn("b@example.com", emails1)
        # Case 2: nested deeper — email list inside employee.
        html2 = '''<html><head>
<script type="application/ld+json">
{"@type":"Organization","employee":{"@type":"Person","email":[
    {"@type":"ContactPoint","email":"employee@example.com"}
]}}
</script></head><body></body></html>'''
        soup2 = BeautifulSoup(html2, "html.parser")
        emails2 = extract_emails_from_jsonld(soup2, re.compile(r"[A-Za-z0-9._+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"))
        self.assertIn("employee@example.com", emails2)


class TestConfidenceScoringExtraEdgeCases(unittest.TestCase):
    """Score-combination paths the original 8 tests did not cover."""

    def test_unreachable_baseline(self):
        # 'unreachable' means we never got a verdict -- score should be moderate.
        score = compute_email_confidence(smtp_status="unreachable")
        self.assertGreater(score, 20)
        self.assertLess(score, 60)

    def test_privacy_penalty_applied(self):
        base = compute_email_confidence(smtp_status="deliverable")
        with_priv = compute_email_confidence(smtp_status="deliverable",
                                             is_privacy=True)
        self.assertLess(with_priv, base)

    def test_disposable_overrides_gravatar(self):
        # Even with Gravatar evidence, disposable must remain very low.
        score = compute_email_confidence(
            smtp_status="deliverable",
            has_gravatar=True,
            is_disposable=True,
        )
        self.assertLessEqual(score, 10)

    def test_no_mx_zero(self):
        score = compute_email_confidence(smtp_status="no_mx",
                                         has_gravatar=True)
        self.assertEqual(score, 0)

    def test_clamped_to_100(self):
        # Synthetic combination that would otherwise overflow must clamp.
        score = compute_email_confidence(
            smtp_status="deliverable",
            has_gravatar=True,
        )
        self.assertLessEqual(score, 100)


