class TestDomainRateLimiterReuseEdgeCases(unittest.TestCase):
    """Make sure repeated configure() calls on a domain don't leak state."""

    def test_reconfigure_same_domain(self):
        rl = DomainRateLimiter(default_rps=10.0, default_burst=5)
        rl.configure_domain("foo.com", rps=20.0)
        rl.configure_domain("foo.com", rps=5.0)  # narrower
        self.assertTrue(rl.acquire("foo.com", max_wait=0.5))

    def test_close_race_with_enqueue(self):
        """Regression: ``close()`` must set ``self._conn = None`` inside
        the lock so a concurrent ``enqueue()`` never sees a nullified
        connection while holding its lock. Without this, the following
        interleaving would crash with ``AttributeError``::

            Thread A (enqueue)            Thread B (close)
            1. if not self._conn → False
                                          2. self._conn.close()
                                          3. self._conn = None ← outside lock!
            4. self._conn.execute(...) → CRASH

        Two threads race on the SAME queue instance: one enqueues,
        the other closes. A fixed iteration count (not a while-true
        loop) guarantees the test terminates even when every iteration
        triggers the race. The fix ensures enqueue either succeeds or
        safely detects the closed connection and returns — it never
        crashes with AttributeError / ProgrammingError."""
        import tempfile as _tf
        with _tf.TemporaryDirectory() as td:
            db = os.path.join(td, "race_queue.sqlite3")
            q = _PersistedRequestQueue(db)
            self.assertTrue(q.enabled())

            enqueue_errors = []

            def enqueuer():
                for i in range(200):
                    try:
                        q.enqueue(f"https://race{i}.example/x", depth=1)
                    except Exception as e:
                        enqueue_errors.append(e)

            def closer():
                for _ in range(5):
                    try:
                        q.close()
                    except Exception as e:
                        logger.debug("closer exception: %s", e)
                    time.sleep(0.01)

            t1 = threading.Thread(target=enqueuer)
            t2 = threading.Thread(target=closer)
            t1.start()
            t2.start()
            t1.join(timeout=10)
            t2.join(timeout=10)
            self.assertFalse(t1.is_alive())
            self.assertFalse(t2.is_alive())

            # enqueuer may succeed or return early due to closed conn,
            # but must never crash with AttributeError/ProgrammingError.
            self.assertEqual(enqueue_errors, [],
                             f"enqueue during close raised: {enqueue_errors}")


