# DEEP-AUDIT REGRESSIONS
# ===================================================================
# Regression tests pinning the verifier-side fixes from the deep audit:
#  - aiohttp connector limit must not silently throttle high concurrency
#  - greylisting must defer to --reverify-unknown rather than blocking a
#    worker on asyncio.sleep
#  - decode_js_concat_emails must run in linear time on adversarial input
#    AND must cap input size as defence-in-depth on multi-MB minified JS.

class TestVerifierConnectorLimit(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """Pin the aiohttp.TCPConnector synchronisation introduced in the audit.

    Without this, aiohttp's default ``TCPConnector(limit=100)`` silently
    throttles every task above 100 in an internal queue, producing
    artificial timeouts whenever the user passes ``--concurrency 200`` (or
    auto-tune raises it past 100).
    """

    def test_run_creates_explicit_tcp_connector(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier.run)
        self.assertIn(
            "aiohttp.TCPConnector",
            src,
            "AsyncEmailVerifier.run must instantiate an explicit TCPConnector "
            "to prevent the default limit=100 from throttling high-concurrency runs",
        )

    def test_run_connector_limit_scales_with_concurrency(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier.run)
        # Must reference ``concurrency`` (or a derived var) when sizing the
        # connector. Bare "limit=100" without any reference to concurrency
        # would re-introduce the bottleneck.
        self.assertTrue(
            "limit=max(100, int(concurrency))" in src
            or "limit=max(100, retry_concurrency)" in src,
            "TCPConnector(limit=...) must scale with concurrency, not be hard-coded",
        )

    def test_run_handles_concurrency_above_default(self):
        # End-to-end smoke: run() with concurrency=250 (above aiohttp's 100
        # default) must not raise on connector creation. We pass an empty
        # task list so the run returns immediately after pool setup.
        verifier = AsyncEmailVerifier(DEFAULT_SETTINGS)
        try:
            asyncio.run(verifier.run(
                email_tasks=[], out_path="/tmp/_audit_unused.csv",
                concurrency=250, delay=0, mode="direct",
            ))
        except Exception as e:
            self.fail(f"run(concurrency=250) raised: {e}")

    def test_run_does_not_disable_tls_verification(self):
        # Regression for Devin Review on PR #3: TCPConnector(ssl=False)
        # disables HTTPS certificate verification for the Gravatar HEAD
        # request and lets a network-path attacker forge has_gravatar,
        # which feeds compute_email_confidence(). The pool-limit fix has
        # nothing to do with TLS; both must be independent.
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier.run)
        self.assertNotIn(
            "ssl=False", src,
            "TCPConnector must NOT pass ssl=False -- the session does the "
            "Gravatar HEAD over HTTPS and the result feeds the confidence "
            "score. Disabling cert verification makes that signal MITM-forgeable.",
        )


class TestGreylistDefersToReverify(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """Pin the new greylist behaviour: defer retry rather than sleep inline."""

    def test_no_inline_sleep_in_verify_smtp_direct(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier._verify_smtp_direct)
        self.assertNotIn(
            "asyncio.sleep", src,
            "_verify_smtp_direct must NOT block a worker with asyncio.sleep "
            "on greylist; defer to --reverify-unknown instead",
        )

    def test_greylist_marker_in_reason(self):
        # The marker is what users see in the CSV ``reason`` column and
        # what self-test #79 keys off; pin it so a refactor doesn't drop it.
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier._verify_smtp_direct)
        self.assertIn("deferred to --reverify-unknown pass", src)

    def test_greylist_response_fast_path(self):
        # _verify_smtp_direct must complete in ~zero wall time on a
        # greylist response, not 60 seconds. We patch
        # _verify_smtp_direct_once to immediately return a greylist tuple
        # and assert the public method returns within 1 s.
        verifier = AsyncEmailVerifier(DEFAULT_SETTINGS)

        async def fake_once(_self, _email, _mx_hosts):
            return None, "450 4.7.1 Greylisted, please try again later"

        with patch.object(AsyncEmailVerifier, "_verify_smtp_direct_once", fake_once):
            t0 = time.time()
            result, reason = asyncio.run(
                verifier._verify_smtp_direct("user@example.com", ["mx.example.com"])
            )
            elapsed = time.time() - t0
        self.assertIsNone(result, "greylist must surface as unknown (None)")
        self.assertIn("greylisted", reason.lower())
        self.assertIn("--reverify-unknown", reason)
        self.assertLess(
            elapsed, 1.0,
            f"greylist path took {elapsed:.2f}s -- must be near-instant",
        )


class TestJsConcatInputCap(unittest.TestCase):
    """``decode_js_concat_emails`` must complete fast on adversarial input
    and cap input size as defence-in-depth."""

    def _make_email_regex(self):
        return re.compile(r"\b[\w.%+-]+@[\w.-]+\.[\w]{2,}\b", re.UNICODE)

    def test_pathological_input_completes_quickly(self):
        # 5,000 quoted+plus segments -- adversarial volume but not
        # catastrophic-backtracking-shaped (the pattern is bounded). Must
        # finish in well under a second.
        regex = self._make_email_regex()
        adversarial = ('"' + 'a' * 40 + '"+') * 5000
        t0 = time.time()
        decode_js_concat_emails(adversarial, regex)
        elapsed = time.time() - t0
        self.assertLess(
            elapsed, 1.0,
            f"decode_js_concat_emails took {elapsed:.2f}s on 5k segments",
        )

    def test_input_truncation_does_not_break_legit_payload(self):
        # A real obfuscated email near the start of an otherwise huge JS
        # blob must still be extracted after truncation.
        regex = self._make_email_regex()
        legit = '"sec" + "urity@" + "site.com";\n'
        padding = 'x' * (_JS_CONCAT_MAX_INPUT_CHARS * 2)  # 100 KB padding
        out = decode_js_concat_emails(legit + padding, regex)
        self.assertIn("security@site.com", out)

    def test_input_cap_respected(self):
        # Direct check that the constant exists and is a positive int.
        self.assertIsInstance(_JS_CONCAT_MAX_INPUT_CHARS, int)
        self.assertGreaterEqual(_JS_CONCAT_MAX_INPUT_CHARS, 10_000)


