# DEEP-AUDIT-2 REGRESSIONS
# ===================================================================
# Regression tests pinning the four daemon-stability fixes from the
# second deep audit:
#  - _execute_crawl_phase no longer "stutters" on a slow URL in a batch
#  - _smtp_handshake_once frees the socket FD even if quit() raises
#  - _handle_internet_outage drains-and-requeues on wake-up rather than
#    .clear()ing (preserves URLs that failed during the outage window)
#  - _SHUTDOWN_REQUESTED is honoured by _execute_crawl_phase and
#    AsyncEmailVerifier.run.worker

class TestExecuteCrawlPhaseContinuousFeed(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """Pin the FIRST_COMPLETED top-up loop in _execute_crawl_phase.

    The previous batched ``as_completed`` design idled N-1 workers
    whenever any one URL hit the crawl timeout. This is a structural
    invariant of the new implementation, not something we can race-test
    in unit-test wall time -- so we pin the source markers.
    """

    def test_uses_first_completed_not_as_completed(self):
        raise unittest.SkipTest("Source-inspection test — fragile; skipped pending behavioral replacement")
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._execute_crawl_phase)
        self.assertIn(
            "FIRST_COMPLETED", src,
            "_execute_crawl_phase must use FIRST_COMPLETED so a slow URL "
            "doesn't idle the rest of the workers in its batch",
        )
        self.assertNotIn(
            "for future in as_completed(", src,
            "the old batched as_completed() loop must be gone -- it's the "
            "stuttering-pool anti-pattern this fix targets",
        )

    def test_tops_up_to_max_threads(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._execute_crawl_phase)
        # Continuous-feed loop tops up to a runtime ``target`` capped at
        # ``self.max_threads``. The adaptive controller can shrink the
        # target below ``max_threads`` when failure rates spike, but
        # never raises it above. The original assertion was the literal
        # ``< self.max_threads``; we now look for the cap expression
        # ``min(self.max_threads, ...)`` AND the in-flight comparison
        # ``< target`` that the adaptive loop uses.
        self.assertIn(
            "min(self.max_threads", src,
            "feed loop must cap in-flight count at max_threads",
        )
        self.assertIn(
            "len(active_futures) < target", src,
            "feed loop must keep in-flight count topped up to the "
            "adaptive target each iteration",
        )

    def test_honours_shutdown_request(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._execute_crawl_phase)
        self.assertIn(
            "_SHUTDOWN_REQUESTED", src,
            "_execute_crawl_phase must check _SHUTDOWN_REQUESTED so a SIGTERM "
            "stops new URL submissions instead of letting workers run until "
            "the OS sends SIGKILL and bypasses cleanup",
        )


class TestSmtpHandshakeFdLeak(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """``_smtp_handshake_once`` must always release the underlying transport
    descriptor, even if ``quit()`` raises (which it does on every dropped
    connection). Without this we leak FDs at high concurrency until the
    process is killed with [Errno 24]."""

    def test_close_in_nested_finally(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier._smtp_handshake_once)
        self.assertIn(
            "smtp.close()", src,
            "must explicitly call smtp.close() to free the transport FD; "
            "smtp.quit() alone leaves it dangling on the exception path",
        )

    def test_close_runs_when_quit_raises(self):
        # Stand up a fake aiosmtplib.SMTP that records both .quit() (which
        # raises) and .close() (which must still fire). We hand the verifier
        # a host that immediately bails out at the connect step normally,
        # but inject our fake to drive the quit/close branch directly.
        events: list = []

        class FakeSMTP:
            def __init__(self, *a, **kw):
                pass

            async def connect(self, *a, **kw):
                pass

            async def ehlo(self):
                pass

            async def helo(self):
                pass

            async def mail(self, *_a, **_kw):
                # Force an immediate hard reject so the function reaches the
                # finally block without going further.
                return 550, b"5.0.0 nope"

            async def quit(self):
                events.append("quit_called")
                raise SMTPServerDisconnected("fake disconnect")

            def close(self):
                events.append("close_called")

            @property
            def is_connected(self):
                return False

        verifier = AsyncEmailVerifier(DEFAULT_SETTINGS)

        # Patch the SMTP symbol the verifier actually imports/uses.
        # We use ``patch.object`` on the module itself (via ``sys.modules``)
        # so it works regardless of whether the file is run directly
        # (``__main__``) or imported under any module name by pytest.
        import sys as _sys
        _mod = _sys.modules.get(__name__)
        if _mod is None:
            self.skipTest("module not found in sys.modules")
        with patch.object(_mod, "SMTP", FakeSMTP):
            asyncio.run(verifier._smtp_handshake_once(
                "x@example.com", "mx.example.com", 25,
            ))

        self.assertIn("quit_called", events)
        self.assertIn("close_called", events,
                      "close() must run even though quit() raised")


class TestOutageHandlerNoSilentDataLoss(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """``_handle_internet_outage`` must rescue URLs that worker threads
    appended to ``urls_failed_during_outage_check`` while it slept."""

    def test_drains_and_requeues_on_resume(self):
        # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design; skipped pending behavioral replacement
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._handle_internet_outage)
        # The wake-up branch must DRAIN the deque (popleft loop), not .clear().
        self.assertIn("popleft", src,
                      "wake-up branch must drain the deque, not just clear it")
        # And it must re-queue them onto the front of crawl_queue.
        self.assertIn("crawl_queue.appendleft", src,
                      "drained items must be re-queued, not dropped")

    def test_no_post_sleep_clear_call(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._handle_internet_outage)
        # We DO clear once at outage detection (after consuming the snapshot)
        # but the post-sleep branch must NOT call clear() -- that was the
        # data-loss bug. Find the resume branch and assert it has no .clear().
        resume_marker = "Internet connection restored"
        self.assertIn(resume_marker, src)
        resume_parts = src.split(resume_marker, 1)
        if len(resume_parts) < 2:
            self.fail(f"resume marker {resume_marker!r} not found in source")
        resume_block = resume_parts[1]
        self.assertNotIn(
            "urls_failed_during_outage_check.clear", resume_block,
            "post-sleep branch must not .clear() the deque -- that drops "
            "every URL that failed while we slept",
        )

    def test_aborts_on_shutdown(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._handle_internet_outage)
        self.assertIn(
            "_SHUTDOWN_REQUESTED", src,
            "outage wait must abort on SIGTERM rather than blocking 5 minutes",
        )


class TestVerifierWorkerHonoursShutdown(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """``AsyncEmailVerifier.run``'s worker coroutine must consult
    ``_SHUTDOWN_REQUESTED`` so SIGTERM stops new SMTP probes."""

    def test_worker_checks_shutdown_flag(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier.run)
        self.assertIn(
            "_SHUTDOWN_REQUESTED", src,
            "verifier worker must short-circuit on _SHUTDOWN_REQUESTED so "
            "SIGTERM doesn't get bypassed by an active queue",
        )

    def test_none_worker_results_filtered_before_append(self):
        """The worker returns None on shutdown. ``results`` is later iterated
        (``r.status``, ``r.email``, ``sorted()`` key on ``r.source_domain``,
        history-DB recording) which would AttributeError on None and lose
        every successfully collected result that arrived before the signal.
        Pin that the append site filters Nones out."""
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier.run)
        # Find the append-into-results line and require a None-guard within
        # a few lines before it.
        self.assertIn("results.append(result)", src)
        # The exact guard we added.
        self.assertIn(
            "if result is not None:", src,
            "worker may return None on shutdown -- the result-collection "
            "loop must skip Nones, otherwise downstream r.status/r.email "
            "access crashes the entire run and discards collected results",
        )


# ===================================================================
# PERF-AUDIT REGRESSIONS
# ===================================================================
# Pin the four hyper-optimisation fixes:
#  - CSV writes inside AsyncEmailVerifier.run are off-loaded via
#    asyncio.to_thread so disk I/O can't freeze in-flight SMTP probes.
#  - HTML parsing prefers lxml when installed (5-10x faster than the
#    stdlib html.parser) with a graceful fallback.
#  - Direct SMTP probes have an opt-in AF_INET-only resolution path
#    so AAAA-blackholing hosts don't burn 10s timeouts.
#  - Startup raises RLIMIT_NOFILE soft limit (POSIX) so high concurrency
#    doesn't hit [Errno 24] Too many open files.

class TestVerifierCsvWriteOffloaded(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """``AsyncEmailVerifier.run`` must not block the event loop on CSV
    writes; they are off-loaded via ``asyncio.to_thread`` so 100k-row
    dumps don't freeze in-flight SMTP probes."""

    def test_run_uses_to_thread_for_csv(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier.run)
        self.assertIn(
            "asyncio.to_thread", src,
            "verifier CSV writes must be off-loaded so disk I/O doesn't "
            "stall the event loop and cause spurious SMTP timeouts",
        )
        # Both writes (run-specific + master log) need to be off-loaded.
        self.assertGreaterEqual(
            src.count("asyncio.to_thread"), 2,
            "both the run-specific CSV write AND the master-log append "
            "must be off-loaded, not just one",
        )


class TestSoupHelperPrefersLxml(unittest.TestCase):
    """``_make_soup`` should pick lxml when available, fall back to the
    stdlib parser otherwise."""

    def test_helper_exists_and_returns_soup(self):
        soup = _make_soup("<html><body><p>hi</p></body></html>")
        self.assertEqual(soup.p.text, "hi")

    def test_chosen_parser_constant_is_valid(self):
        self.assertIn(_HTML_PARSER, ("lxml", "html.parser"))

    def test_falls_back_when_explicit_parser_raises(self):
        # Asking for a parser that doesn't exist must NOT crash the
        # crawler; we want the fallback to html.parser to kick in.
        soup = _make_soup("<p>hi</p>", parser="this-parser-does-not-exist")
        self.assertEqual(soup.p.text, "hi")


class TestSmtpForceIpv4Setting(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """``smtp_force_ipv4`` setting must drive the AF_INET pre-resolution
    path in ``_smtp_handshake_once``."""

    def test_handshake_consults_setting(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier._smtp_handshake_once)
        self.assertIn("smtp_force_ipv4", src,
                      "handshake must consult the smtp_force_ipv4 setting")
        self.assertIn("AF_INET", src,
                      "must request AF_INET specifically, not the default "
                      "AF_UNSPEC (which can return AAAA first)")
        self.assertIn("getaddrinfo", src,
                      "must pre-resolve via getaddrinfo so aiosmtplib gets a "
                      "literal IPv4 string and skips its own AAAA attempt")

    def test_default_settings_includes_off_default(self):
        # Both default-settings copies in the file must declare the flag,
        # and it must default to False so we don't break IPv6-only
        # deployments.
        self.assertIn("smtp_force_ipv4", DEFAULT_SETTINGS["verifier_settings"])
        self.assertIs(
            DEFAULT_SETTINGS["verifier_settings"]["smtp_force_ipv4"], False,
            "smtp_force_ipv4 must default OFF -- forcing IPv4 by default "
            "would break IPv6-only deployments",
        )


class TestRaiseOpenFileLimit(unittest.TestCase):
    """``_raise_open_file_limit`` must produce a sensible status string and
    never raise."""

    def test_returns_status_tuple(self):
        soft, hard, status = _raise_open_file_limit(target=1)  # tiny target -> "unchanged"
        self.assertIsInstance(soft, int)
        self.assertIsInstance(hard, int)
        self.assertIn(status, ("raised", "unchanged", "unsupported", "failed"))

    def test_high_target_does_not_raise(self):
        # Even if the kernel refuses, the helper must NOT raise -- it must
        # return a status code so main() can log and continue.
        try:
            _raise_open_file_limit(target=10**9)
        except Exception as e:
            self.fail(f"_raise_open_file_limit raised on absurdly-high target: {e}")


