class TestQueuedUrlsDedup(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """Pin the ``queued_urls`` set introduced to bound queue growth from
    concurrent link-extraction passes.

    Before this set existed, 50 worker threads each parsing a page with
    100 internal links could append the same internal URL up to 50
    times before any worker popped it. Each duplicate was a no-op on
    dispatch (visited_urls guard) but still cost a popleft + lookup.
    The set turns the per-page link-extraction dedup into an O(1)
    check, shrinking queue size by ~Nworkers× under heavy concurrency.
    """

    def test_queued_urls_initialized_in_init(self):
        # Source-inspect to pin the attribute exists on every instance.
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper.__init__)
        self.assertIn("self.queued_urls", src,
                      "__init__ must initialize queued_urls so link-extraction can dedup")

    def test_queued_urls_cleared_in_crawl(self):
        # Source-inspect crawl() reset block.
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper.crawl)
        self.assertIn("self.queued_urls.clear()", src,
                      "crawl() must clear queued_urls so monitoring cycle 2 can re-queue URLs from cycle 1")

    def test_dedup_blocks_second_append(self):
        # Behavioural pin: a URL appended once must not be appended again.
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s.crawl_queue = deque()
        s.queued_urls = set()
        s.visited_urls = set()
        s.lock = RLock()

        def maybe_append(url, depth):
            with s.lock:
                if url not in s.visited_urls and url not in s.queued_urls:
                    s.crawl_queue.append((url, depth))
                    s.queued_urls.add(url)

        # Simulate 50 workers all racing to append the same URL.
        url = "https://target.test/contact"
        for _ in range(50):
            maybe_append(url, 1)
        self.assertEqual(len(s.crawl_queue), 1,
                         f"queued_urls should bound dups to 1, got {len(s.crawl_queue)}")
        self.assertIn(url, s.queued_urls)

    def test_popleft_discards_from_queued_urls(self):
        # Pin the discard() in _execute_crawl_phase so a URL re-popped
        # for rate-limit re-queue isn't blocked by stale set membership.
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._execute_crawl_phase)
        self.assertIn("self.queued_urls.discard", src,
                      "_execute_crawl_phase must discard the popped URL from queued_urls so rate-limit re-queue still works")


class TestRateLimitRequeueDedup(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """Rate-limited URLs must not accumulate unbounded copies in the queue."""

    def test_same_url_capped_at_two_inflight(self):
        # Build a scraper without going through __init__'s heavy I/O.
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s.crawl_queue = deque()
        s.lock = RLock()
        s._rate_limit_requeues = {}

        url = "https://blocked.test/page"
        depth = 1
        # Simulate 5 worker threads racing to re-queue the same URL.
        for _ in range(5):
            with s.lock:
                key = (url, depth)
                count = s._rate_limit_requeues.get(key, 0)
                if count < 2:
                    s._rate_limit_requeues[key] = count + 1
                    s.crawl_queue.append(key)
        self.assertEqual(len(s.crawl_queue), 2,
                         f"queue should cap at 2 copies, got {len(s.crawl_queue)}")
        self.assertEqual(s._rate_limit_requeues[(url, depth)], 2)


class TestCamoufoxBrowserCached(unittest.TestCase):
    # DEPENDENCY: Source-inspection via inspect.getsource — fragile by design.
    """The Tier-2 fallback must not spawn a new Firefox per URL.

    We don't actually launch camoufox; we source-inspect the method to
    pin the architectural change (lazy init + reuse) so a future regression
    that re-introduces ``with Camoufox(...) as browser`` per call gets caught.
    """

    def test_uses_shared_browser_with_lock(self):
        import inspect as _inspect
        # The shared-browser implementation now lives in the impl method
        # (the public ``_tier2_camoufox_fetch`` is a single-thread
        # executor dispatcher). Inspect the impl for the architectural
        # invariants instead.
        src = _inspect.getsource(AdvancedEmailScraper._tier2_camoufox_fetch_impl)
        self.assertIn("self._camoufox_browser", src)
        self.assertIn("self._camoufox_lock", src)
        self.assertIn("if self._camoufox_browser is None", src)
        self.assertNotIn("with Camoufox(", src,
                         "Tier-2 must not re-spawn camoufox per call -- use the shared browser cached on self")
        # And the public dispatcher must dispatch through the executor
        # so the greenlet-bound browser never crosses thread boundaries.
        dsrc = _inspect.getsource(AdvancedEmailScraper._tier2_camoufox_fetch)
        self.assertIn("_get_camoufox_executor", dsrc)
        self.assertIn("submit", dsrc)

    def test_close_tears_down_camoufox(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper.close)
        self.assertIn("_camoufox_ctx_mgr", src,
                      "close() must release the shared Tier-2 browser")
        self.assertIn("__exit__", src)

    def test_crashed_browser_recovered_on_next_call(self):
        """If the shared browser crashes mid-fetch, the reference must be
        cleared so the very next call re-launches a fresh browser. Without
        this reset Tier-2 stays permanently broken for the rest of the
        scraper's lifetime after a single browser crash.

        Behavioural pin: simulate a crashed browser whose ``new_page`` raises,
        and verify ``self._camoufox_browser`` is None after the call.
        """
        import sys as _sys
        import types as _types
        from unittest.mock import patch as _patch

        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s.lock = RLock()
        s._camoufox_lock = RLock()
        s._tier2_fail_counts = {}

        mod = _sys.modules[__name__]
        fake_pkg = _types.ModuleType("camoufox")
        fake_sub = _types.ModuleType("camoufox.sync_api")
        fake_sub.Camoufox = lambda *a, **kw: None  # never invoked: lazy-init guard skipped

        class _CrashedBrowser:
            def new_page(self):
                raise RuntimeError("playwright connection closed")

        class _CrashedCtx:
            def __exit__(self, *a, **kw):
                return False

        s._camoufox_browser = _CrashedBrowser()
        s._camoufox_ctx_mgr = _CrashedCtx()

        # Stub _detect_captcha so the method body is reachable.
        s._detect_captcha = lambda html: False

        with _patch.dict(_sys.modules, {
            "camoufox": fake_pkg,
            "camoufox.sync_api": fake_sub,
        }), _patch.object(mod, "BROWSER_FALLBACK_ENABLED", True), \
             _patch.object(mod, "HAS_CAMOUFOX", True):
            # _extract_domain on the bound class still works because we
            # build s via __new__ which doesn't run __init__ but the
            # method itself is just a static parser.
            result = s._tier2_camoufox_fetch("https://example.test/blocked")

        self.assertIsNone(result)
        self.assertIsNone(s._camoufox_browser,
                          "_camoufox_browser must be reset to None on fetch failure so the next call re-launches a fresh browser")
        self.assertIsNone(s._camoufox_ctx_mgr,
                          "_camoufox_ctx_mgr must also be cleared so close() doesn't try to __exit__ a dead context")


