class TestDecodeJsConcatEmailsDeep(unittest.TestCase):
    """``decode_js_concat_emails`` corner cases."""

    def setUp(self):
        self.regex = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")

    def test_empty_returns_empty_set(self):
        self.assertEqual(decode_js_concat_emails("", self.regex), set())

    def test_no_plus_returns_empty(self):
        self.assertEqual(
            decode_js_concat_emails("foo bar baz no plus here", self.regex),
            set(),
        )

    def test_basic_concat(self):
        text = "var e = 'sec' + 'urity@' + 'example.test';"
        result = decode_js_concat_emails(text, self.regex)
        self.assertIn("security@example.test", result)

    def test_double_quoted_concat(self):
        text = 'var e = "sec" + "urity@" + "example.test";'
        result = decode_js_concat_emails(text, self.regex)
        self.assertIn("security@example.test", result)

    def test_caps_input_size(self):
        # 100KB of pathological data should not hang or crash.
        big = ("'a' + 'b' + " * 5000) + "'c'"
        try:
            decode_js_concat_emails(big, self.regex)
        except Exception as e:
            self.fail(f"decode_js_concat_emails raised on big input: {e!r}")

    def test_no_at_symbol_no_email_extracted(self):
        text = "'a' + 'b' + 'c'"
        self.assertEqual(decode_js_concat_emails(text, self.regex), set())


