class TestExtractEmailsFromDataAttrs(unittest.TestCase):
    def setUp(self):
        self.regex = re.compile(r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}")

    def test_none_soup(self):
        self.assertEqual(extract_emails_from_data_attrs(None, self.regex), set())

    def test_empty_soup(self):
        soup = BeautifulSoup("<html></html>", "html.parser")
        self.assertEqual(extract_emails_from_data_attrs(soup, self.regex), set())

    def test_basic_data_attr(self):
        soup = BeautifulSoup(
            '<a data-email="hello@example.test">Email</a>',
            "html.parser",
        )
        self.assertIn("hello@example.test", extract_emails_from_data_attrs(soup, self.regex))

    def test_html_entity_encoded(self):
        soup = BeautifulSoup(
            '<a data-email="hello&#64;example.test">Email</a>',
            "html.parser",
        )
        self.assertIn("hello@example.test", extract_emails_from_data_attrs(soup, self.regex))

    def test_non_data_attr_ignored(self):
        soup = BeautifulSoup(
            '<a href="hello@example.test">Email</a>',
            "html.parser",
        )
        # href is not data-*, should be ignored by this helper.
        self.assertEqual(extract_emails_from_data_attrs(soup, self.regex), set())

    def test_lowercase_normalisation(self):
        soup = BeautifulSoup('<div data-x="HELLO@EXAMPLE.TEST"></div>', "html.parser")
        result = extract_emails_from_data_attrs(soup, self.regex)
        # Output is lowercased.
        self.assertIn("hello@example.test", result)


