class TestComputeEmailConfidenceDeep(unittest.TestCase):
    def test_deliverable_baseline_high(self):
        score = compute_email_confidence(
            smtp_status="deliverable",
            has_gravatar=False, is_role=False, is_disposable=False,
            is_privacy=False, syntax_ok=True,
        )
        self.assertGreaterEqual(score, 60)
        self.assertLessEqual(score, 100)

    def test_undeliverable_low(self):
        score = compute_email_confidence(
            smtp_status="undeliverable", syntax_ok=True,
        )
        self.assertLess(score, 50)

    def test_no_mx_zero_or_low(self):
        score = compute_email_confidence(smtp_status="no_mx", syntax_ok=True)
        self.assertLessEqual(score, 30)

    def test_disposable_drops_score(self):
        clean = compute_email_confidence(smtp_status="deliverable", syntax_ok=True)
        dirty = compute_email_confidence(
            smtp_status="deliverable", is_disposable=True, syntax_ok=True,
        )
        self.assertLess(dirty, clean)

    def test_role_drops_score(self):
        clean = compute_email_confidence(smtp_status="deliverable", syntax_ok=True)
        role = compute_email_confidence(
            smtp_status="deliverable", is_role=True, syntax_ok=True,
        )
        self.assertLess(role, clean)

    def test_gravatar_boosts_score(self):
        without = compute_email_confidence(smtp_status="deliverable", syntax_ok=True)
        with_grav = compute_email_confidence(
            smtp_status="deliverable", has_gravatar=True, syntax_ok=True,
        )
        self.assertGreaterEqual(with_grav, without)

    def test_score_clamped_0_to_100(self):
        for st in ["deliverable", "undeliverable", "accept_all", "unreachable", "no_mx", None]:
            for grav in [True, False]:
                for role in [True, False]:
                    for disp in [True, False]:
                        for priv in [True, False]:
                            s = compute_email_confidence(
                                smtp_status=st, has_gravatar=grav, is_role=role,
                                is_disposable=disp, is_privacy=priv, syntax_ok=True,
                            )
                            self.assertGreaterEqual(s, 0, f"score {s} negative for {st}/{grav}/{role}/{disp}/{priv}")
                            self.assertLessEqual(s, 100, f"score {s} > 100 for {st}/{grav}/{role}/{disp}/{priv}")

    def test_syntax_failure_floors_score(self):
        score = compute_email_confidence(
            smtp_status="deliverable", syntax_ok=False,
        )
        # Syntax failure should not produce a "confident" result.
        self.assertLess(score, 60)


