class TestSitemapFilterDeep(unittest.TestCase):
    def test_empty_input(self):
        self.assertEqual(filter_sitemap_urls([]), [])

    def test_dedupes(self):
        urls = [
            "https://x.test/contact",
            "https://x.test/contact",
            "https://x.test/about",
        ]
        out = filter_sitemap_urls(urls)
        self.assertEqual(len(out), 2)

    def test_filters_non_contact_paths(self):
        # Sitemap filter only keeps contact-discovery URLs (paths
        # containing ``contact``, ``about``, ``team``, ``careers``,
        # ``imprint``, ``legal``, etc.). Random product pages are
        # dropped to avoid crawling 50,000 listings.
        urls = [
            "https://x.test/products/widget",
            "https://x.test/contact",
            "https://x.test/blog/2024-news",
        ]
        out = filter_sitemap_urls(urls)
        self.assertEqual(out, ["https://x.test/contact"])

    def test_host_filter_exact(self):
        # Note: the implementation strips ``www.`` from netloc but then
        # compares EXACTLY against host_filter — so subdomains do NOT
        # pass. Pin the actual behaviour.
        urls = [
            "https://x.test/contact",
            "https://www.x.test/about",
            "https://other.test/contact",
        ]
        out = filter_sitemap_urls(urls, host_filter="x.test")
        # x.test/contact and www.x.test/about both pass; other.test fails.
        for u in out:
            self.assertNotIn("other.test", u)
        self.assertEqual(len(out), 2)

    def test_host_filter_subdomain_dropped(self):
        # The current implementation does NOT match subdomains.
        urls = ["https://blog.x.test/contact", "https://other.test/contact"]
        out = filter_sitemap_urls(urls, host_filter="x.test")
        # Pin: subdomain is dropped under the strict-equality netloc check.
        for u in out:
            self.assertNotIn("blog.x.test", u)


class TestParseSitemapXmlDeep(unittest.TestCase):
    def test_empty_bytes(self):
        urls, sitemaps = parse_sitemap_xml(b"")
        self.assertEqual(urls, [])
        self.assertEqual(sitemaps, [])

    def test_basic(self):
        xml = b"""<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
    <url><loc>https://example.test/a</loc></url>
    <url><loc>https://example.test/b</loc></url>
</urlset>"""
        urls, sitemaps = parse_sitemap_xml(xml)
        self.assertIn("https://example.test/a", urls)
        self.assertIn("https://example.test/b", urls)

    def test_sitemap_index(self):
        xml = b"""<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
    <sitemap><loc>https://example.test/sub.xml</loc></sitemap>
</sitemapindex>"""
        urls, sitemaps = parse_sitemap_xml(xml)
        self.assertIn("https://example.test/sub.xml", sitemaps)

    def test_malformed_returns_empty(self):
        urls, sitemaps = parse_sitemap_xml(b"<not-xml")
        self.assertEqual(urls, [])
        self.assertEqual(sitemaps, [])

    def test_no_namespace(self):
        xml = b"<urlset><url><loc>https://example.test/a</loc></url></urlset>"
        urls, sitemaps = parse_sitemap_xml(xml)
        self.assertIn("https://example.test/a", urls)


class TestRobotsRulesDeep(unittest.TestCase):
    def test_empty_text_allows_all(self):
        rules = _RobotsRules.parse("")
        self.assertTrue(rules.is_allowed("/anything"))

    def test_disallow_all(self):
        rules = _RobotsRules.parse("User-agent: *\nDisallow: /")
        self.assertFalse(rules.is_allowed("/contact"))

    def test_disallow_specific(self):
        rules = _RobotsRules.parse("User-agent: *\nDisallow: /admin\nAllow: /admin/public")
        self.assertFalse(rules.is_allowed("/admin/secret"))

    def test_only_blank_lines(self):
        rules = _RobotsRules.parse("\n\n\n")
        self.assertTrue(rules.is_allowed("/contact"))

    def test_only_comments(self):
        rules = _RobotsRules.parse("# comment\n# more comments\n")
        self.assertTrue(rules.is_allowed("/contact"))

    def test_user_agent_specific_ignored_for_star(self):
        # If a rule applies to "Googlebot" only, and we're not Googlebot,
        # it shouldn't apply.
        text = "User-agent: Googlebot\nDisallow: /private"
        rules = _RobotsRules.parse(text)
        # The default crawler matches User-agent: * (or no rule => allowed).
        self.assertTrue(rules.is_allowed("/private"))


class TestRateLimiterDeep(unittest.TestCase):
    def test_default_constructor(self):
        rl = DomainRateLimiter()
        # Must allow at least one request immediately.
        self.assertTrue(rl.acquire("example.test", max_wait=1.0))

    def test_configure_domain_overrides(self):
        rl = DomainRateLimiter()
        rl.configure_domain("slow.test", rps=0.5, crawl_delay=0.0)
        # First acquire passes.
        self.assertTrue(rl.acquire("slow.test", max_wait=0.5))

    def test_acquire_max_wait_zero_returns_quickly(self):
        rl = DomainRateLimiter(default_rps=0.001)  # very slow.
        rl.acquire("burst.test", max_wait=0.0)
        # Second call with max_wait=0 should fail-fast (return False), not block.
        t0 = time.monotonic()
        rl.acquire("burst.test", max_wait=0.0)
        elapsed = time.monotonic() - t0
        self.assertLess(elapsed, 0.3, f"acquire(max_wait=0) blocked for {elapsed:.2f}s")

    def test_per_domain_isolation(self):
        rl = DomainRateLimiter(default_rps=1.0, default_burst=1)
        # Saturate domain A.
        rl.acquire("a.test", max_wait=0.5)
        # Domain B should still be unaffected.
        self.assertTrue(rl.acquire("b.test", max_wait=0.5))

    def test_get_or_create_returns_same_record(self):
        rl = DomainRateLimiter()
        r1 = rl._get_or_create("x.test")
        r2 = rl._get_or_create("x.test")
        self.assertIs(r1, r2)


class TestPhoneExtractionDeep(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(extract_phone_numbers(""), set())

    def test_none(self):
        self.assertEqual(extract_phone_numbers(None), set())

    def test_basic_us_format(self):
        text = "Call us: +1 (555) 123-4567"
        result = extract_phone_numbers(text)
        # Some variant of the digits should be in the result.
        self.assertTrue(any("5551234567" in p.replace("-", "").replace(" ", "").replace("(", "").replace(")", "").replace("+", "")
                            for p in result),
                        f"expected a phone match in {result}")
        # Should NOT extract the "1" as a standalone number.
        for p in result:
            digits = re.sub(r"\D", "", p)
            self.assertGreaterEqual(len(digits), 7)

    def test_year_filtered(self):
        result = extract_phone_numbers("Founded in 2020 — copyright 1999-2023.")
        for p in result:
            digits = re.sub(r"\D", "", p)
            self.assertGreaterEqual(len(digits), 7,
                                    f"too-short {p} should have been filtered")
        # 2023 may appear as part of a phone-range substring; verify no
        # standalone year-like match (i.e. every match has >= 7 digits).

    def test_max_count_caps_output(self):
        text = " ".join([f"+1 555 000 {i:04d}" for i in range(200)])
        result = extract_phone_numbers(text, max_count=50)
        self.assertEqual(len(result), 50,
                         f"max_count=50 should cap output at 50, got {len(result)}")

    # ---- CSS / JSON / coordinate garbage filters ----
    def test_css_pixel_values_filtered(self):
        result = extract_phone_numbers("width: 146.539px; height: 28.742px")
        self.assertEqual(len(result), 0, "CSS pixel values must not be treated as phones")

    def test_json_coordinates_filtered(self):
        result = extract_phone_numbers('{"lat": 37.2513, "lng": 141.455, "alt": 35}')
        self.assertEqual(len(result), 0, "JSON coordinate pairs must not be treated as phones")

    def test_timestamp_float_filtered(self):
        result = extract_phone_numbers("0.0671082 179.506 28.3")
        self.assertEqual(len(result), 0, "timestamp floats must not be treated as phones")

    def test_bare_seven_digit_number_filtered(self):
        result = extract_phone_numbers("1003979")
        self.assertEqual(len(result), 0, "bare 7-digit number without structure must not be treated as phone")

    def test_css_matrix_filtered(self):
        result = extract_phone_numbers("matrix(0.8, 0, 0, 0.8, 146.539, 193.473)")
        self.assertEqual(len(result), 0, "CSS matrix values must not be treated as phones")

    def test_version_dot_dot_filtered(self):
        result = extract_phone_numbers("version 14.2.1 (build 2024.03.15)")
        self.assertEqual(len(result), 0, "version numbers with multiple dots must not be phones")

    def test_real_phone_still_extracted(self):
        result = extract_phone_numbers("Call +1 (415) 555-0198 or +44 20 7946 0958")
        self.assertGreaterEqual(len(result), 2, "real phone numbers must still be extracted")

    def test_real_international_with_country_code(self):
        result = extract_phone_numbers("Reach us at +91-22-1234-5678")
        self.assertGreaterEqual(len(result), 1, "Indian-format phone must be extracted")


