    def test_post_webhook_bad_url_returns_false(self):
        """``post_completion_webhook`` must return ``(False, ...)`` for
        an unreachable URL (not raise). This test does NOT make a real
        network call — it connects to a loopback port that nothing is
        listening on, which fails immediately with ``ConnectionRefused``."""
        ok, reason = post_completion_webhook(
            "http://127.0.0.1:1/webhook",  # port 1: almost certainly closed
            payload={"text": "test"},
            timeout=2.0,
        )
        self.assertFalse(ok, "unreachable webhook URL must return ok=False")
        self.assertIsInstance(reason, str)
        self.assertGreater(len(reason), 0, "reason must describe the failure")


