class TestContentHashDedupBehaviour(unittest.TestCase):
    """``_record_response_seen`` per-domain LRU eviction."""

    def setUp(self):
        self.s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        self.s.lock = RLock()
        self.s.content_hashes = defaultdict(set)
        self.s.content_hash_order = defaultdict(deque)
        self.s._CONTENT_HASH_CAP = 3

    def test_first_seen_returns_false(self):
        self.assertFalse(self.s._record_response_seen("x.test", b"body1"))

    def test_repeat_returns_true(self):
        self.s._record_response_seen("x.test", b"body1")
        self.assertTrue(self.s._record_response_seen("x.test", b"body1"))

    def test_per_domain_isolated(self):
        self.s._record_response_seen("a.test", b"shared")
        # Same body on a different domain is still "new" for that domain.
        self.assertFalse(self.s._record_response_seen("b.test", b"shared"))

    def test_lru_evicts_oldest(self):
        for body in [b"b1", b"b2", b"b3"]:
            self.s._record_response_seen("x.test", body)
        # 4th should evict b1.
        self.s._record_response_seen("x.test", b"b4")
        self.assertEqual(len(self.s.content_hashes["x.test"]), 3)
        # b1 has been evicted; re-inserting it returns False.
        self.assertFalse(self.s._record_response_seen("x.test", b"b1"))

    def test_empty_body_returns_false(self):
        self.assertFalse(self.s._record_response_seen("x.test", b""))

    def test_no_domain_returns_false(self):
        self.assertFalse(self.s._record_response_seen("", b"body"))


