class TestMasterCsvAtomicOpen(unittest.TestCase):
    """Regression: CSV master log uses ``os.open(O_EXCL)`` for atomic
    first-writer detection instead of a TOCTOU-prone ``isfile()``."""

    def test_atomic_open_creates_new_file(self):
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "master.csv")
            fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
            os.close(fd)
            self.assertTrue(os.path.isfile(path))
            # Second open with O_EXCL must fail.
            with self.assertRaises(FileExistsError):
                os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)

    def test_atomic_open_pattern_used_in_master_csv(self):
        """End-to-end regression test for the CSV master log TOCTOU fix.

        Replicates the exact write pattern that ``_append_master_csv``
        (inside ``AsyncEmailVerifier.run``) uses: atomic O_EXCL first-writer
        detection, utf-8-sig for the initial creation, plain utf-8 for
        appends, header only on first write, and ``_SafeCsvDictWriter``
        for every row.

        No mocks, no source inspection — real file I/O with the exact
        production classes (``_SafeCsvDictWriter``, ``csv.DictWriter``).
        """
        import csv as _csv
        header = ["email", "status", "reason"]
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "master.csv")

            # ---- First write: must create file with BOM + header ----
            try:
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
                os.close(fd)
                first_try = True
            except FileExistsError:
                first_try = False
            encoding = 'utf-8-sig' if first_try else 'utf-8'
            with open(path, 'a', newline='', encoding=encoding) as f:
                writer = _SafeCsvDictWriter(_csv.DictWriter(f, fieldnames=header))
                if first_try:
                    writer.writeheader()
                writer.writerow({"email": "alice@example.com", "status": "valid", "reason": "RCPT TO accepted"})

            # ---- Second write: must append WITHOUT BOM / header ----
            try:
                fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o644)
                os.close(fd)
                first_try = True
            except FileExistsError:
                first_try = False
            encoding = 'utf-8-sig' if first_try else 'utf-8'
            with open(path, 'a', newline='', encoding=encoding) as f:
                writer = _SafeCsvDictWriter(_csv.DictWriter(f, fieldnames=header))
                if first_try:
                    writer.writeheader()
                writer.writerow({"email": "bob@other.org", "status": "invalid", "reason": "RCPT TO rejected"})

            # ---- Verify structure ----
            # Exactly two data rows, one header row (DictReader strips header):
            with open(path, 'r', encoding='utf-8-sig', newline='') as f:
                rows = list(_csv.DictReader(f))
            self.assertEqual(len(rows), 2, "master CSV should have exactly 2 data rows")
            self.assertEqual(rows[0]["email"], "alice@example.com")
            self.assertEqual(rows[1]["email"], "bob@other.org")

            # Exactly one BOM at the very start (byte 0), never mid-file:
            with open(path, 'rb') as f:
                raw = f.read()
            bom_count = raw.count(b'\xef\xbb\xbf')
            self.assertEqual(bom_count, 1,
                             "should have exactly one BOM at offset 0; "
                             f"found {bom_count} BOM sequence(s) in {len(raw)} bytes")
            self.assertTrue(raw.startswith(b'\xef\xbb\xbf'),
                            "file must begin with utf-8 BOM")


class TestEmailHistoryDbDeep(unittest.TestCase):
    """``EmailHistoryDB`` schema and round-trip."""

    def setUp(self):
        self.tmp = tempfile.NamedTemporaryFile(suffix=".sqlite", delete=False)
        self.tmp.close()
        try:
            self.db = EmailHistoryDB(self.tmp.name)
        except Exception:
            os.unlink(self.tmp.name)
            raise

    def tearDown(self):
        try:
            self.db.close()
        except (sqlite3.Error, OSError):
            pass
        try:
            os.unlink(self.tmp.name)
        except OSError:
            pass

    def test_record_email_and_stats(self):
        self.db.record_email(
            domain="b.test",
            email="a@b.test",
            prioritized=True,
            source_type="contact",
        )
        stats = self.db.stats()
        self.assertIsInstance(stats, dict)
        self.assertEqual(stats["emails"], 1, "one email recorded")
        self.assertEqual(stats["domains"], 1, "one domain")
        self.assertIn("verifications", stats)
        self.assertIn("runs", stats)

    def test_record_email_idempotent(self):
        # Recording the same (domain, email) twice bumps run_count, not row count.
        self.db.record_email(
            domain="b.test", email="a@b.test",
            prioritized=False, source_type="contact",
        )
        self.db.record_email(
            domain="b.test", email="a@b.test",
            prioritized=False, source_type="contact",
        )
        # Same email twice → still 1 row (run_count bumped internally).
        stats = self.db.stats()
        self.assertEqual(stats["emails"], 1,
                         "duplicate (domain, email) must not add a second row")

    def test_record_verification(self):
        self.db.record_verification(
            email="a@b.test", status="deliverable",
            reason="OK", confidence=85,
            has_gravatar=True, run_id="run-1",
        )
        stats = self.db.stats()
        self.assertEqual(stats["verifications"], 1,
                         "verification must be recorded")
        # Verify individual rows via a direct query.
        cur = self.db.conn.execute(
            "SELECT email, status, reason, confidence FROM verifications WHERE email=?",
            ("a@b.test",),
        )
        row = cur.fetchone()
        self.assertIsNotNone(row, "verification row must exist")
        self.assertEqual(row[1], "deliverable")
        self.assertEqual(row[2], "OK")
        self.assertEqual(row[3], 85)

    def test_start_finish_run_round_trip(self):
        self.db.start_run(
            run_id="r2", cli_args="--mode direct",
            python_ver="3.10", git_sha="deadbeef",
        )
        self.db.finish_run(
            run_id="r2", n_domains=1, n_emails=2, n_phones=0,
        )
        stats = self.db.stats()
        self.assertIn("emails", stats)
        self.assertIn("domains", stats)
        self.assertIn("verifications", stats)
        self.assertIn("runs", stats)
        self.assertGreaterEqual(stats["runs"], 1, "at least one run should exist")

    def test_close_idempotent(self):
        self.db.close()
        # Second close must not raise.
        try:
            self.db.close()
        except Exception as e:
            self.fail(f"second close raised: {e!r}")


