class TestDetectGitSha(unittest.TestCase):
    def in_tmpdir(self, fn):
        prev = os.getcwd()
        try:
            with tempfile.TemporaryDirectory() as td:
                os.chdir(td)
                fn(td)
        finally:
            os.chdir(prev)

    def _git(self, td):
        return os.path.join(td, ".git")

    def test_detached_head(self):
        def _(td):
            gd = self._git(td)
            os.makedirs(gd)
            with open(os.path.join(gd, "HEAD"), "w") as f:
                f.write("abc123def456789\n")
            self.assertEqual(_detect_git_sha(), "abc123def456")
        self.in_tmpdir(_)

    def test_branch_ref(self):
        def _(td):
            gd = self._git(td)
            os.makedirs(os.path.join(gd, "refs", "heads"))
            with open(os.path.join(gd, "HEAD"), "w") as f:
                f.write("ref: refs/heads/main\n")
            with open(os.path.join(gd, "refs", "heads", "main"), "w") as f:
                f.write("deadbeefcafebabe\n")
            self.assertEqual(_detect_git_sha(), "deadbeefcafe")
        self.in_tmpdir(_)

    def test_no_git_directory(self):
        self.in_tmpdir(lambda td: self.assertEqual(_detect_git_sha(), ""))

    def test_ref_file_missing(self):
        def _(td):
            gd = self._git(td)
            os.makedirs(gd)
            with open(os.path.join(gd, "HEAD"), "w") as f:
                f.write("ref: refs/heads/missing\n")
            self.assertEqual(_detect_git_sha(), "")
        self.in_tmpdir(_)

    def test_truncated_head(self):
        def _(td):
            gd = self._git(td)
            os.makedirs(gd)
            with open(os.path.join(gd, "HEAD"), "w") as f:
                f.write("ab")
            self.assertEqual(_detect_git_sha(), "ab")
        self.in_tmpdir(_)

    def test_read_error_returns_empty(self):
        def _(td):
            gd = self._git(td)
            os.makedirs(gd)
            h = os.path.join(gd, "HEAD")
            with open(h, "w") as f:
                f.write("dummy")
            os.chmod(h, 0o000)
            try:
                self.assertEqual(_detect_git_sha(), "")
            finally:
                os.chmod(h, 0o644)
        self.in_tmpdir(_)


class TestDeepMergeSettings(unittest.TestCase):
    def test_flat_overlay_wins(self):
        base = {"a": 1, "b": 2}
        _deep_merge_settings(base, {"b": 99, "c": 3})
        self.assertEqual(base, {"a": 1, "b": 99, "c": 3})

    def test_nested_deep_merge(self):
        base = {"db": {"host": "localhost", "port": 5432}, "debug": False}
        _deep_merge_settings(base, {"db": {"port": 9999, "user": "admin"}})
        self.assertEqual(base["db"]["host"], "localhost")
        self.assertEqual(base["db"]["port"], 9999)
        self.assertEqual(base["db"]["user"], "admin")
        self.assertEqual(base["debug"], False)

    def test_overlay_non_dict_overwrites_dict(self):
        base = {"nested": {"keep": 1}}
        _deep_merge_settings(base, {"nested": "scalar"})
        self.assertEqual(base["nested"], "scalar")

    def test_overlay_dict_overwrites_non_dict(self):
        base = {"x": 42}
        _deep_merge_settings(base, {"x": {"y": 1}})
        self.assertEqual(base["x"], {"y": 1})

    def test_empty_overlay_noop(self):
        base = {"a": 1}
        _deep_merge_settings(base, {})
        self.assertEqual(base, {"a": 1})

    def test_empty_base_absorbs_overlay(self):
        base = {}
        _deep_merge_settings(base, {"a": 1, "b": {"c": 2}})
        self.assertEqual(base, {"a": 1, "b": {"c": 2}})

    def test_none_values_in_overlay(self):
        base = {"a": 1, "b": 2}
        _deep_merge_settings(base, {"b": None})
        self.assertEqual(base, {"a": 1, "b": None})


