class TestNetworkAvailableEventBarrier(unittest.TestCase):
    """During an internet outage, the outage handler must clear the
    ``_network_available`` event so all OTHER worker threads idle at
    the barrier in ``_fetch_url`` instead of pop-fail-pop-fail-ing
    through the queue. Without this, 49 of 50 workers blindly drain
    ~1000 URLs during the 5-minute outage window, burning DNS queries,
    ephemeral ports, and log lines for nothing."""

    def setUp(self):
        global _SHUTDOWN_REQUESTED
        self._saved_shutdown = _SHUTDOWN_REQUESTED

    def tearDown(self):
        global _SHUTDOWN_REQUESTED
        _SHUTDOWN_REQUESTED = self._saved_shutdown

    def test_init_creates_event_in_set_state(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper.__init__)
        self.assertIn(
            "_network_available = threading.Event()", src,
            "__init__ must create _network_available as a threading.Event",
        )
        self.assertIn(
            "_network_available.set()", src,
            "__init__ must put the event in 'set' state (network available) "
            "so workers don't idle on the very first call",
        )

    def test_outage_handler_clears_event_before_sleep(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._handle_internet_outage)
        non_comment_src = "\n".join(
            ln for ln in src.splitlines()
            if not ln.lstrip().startswith("#")
        )
        clear_pos = non_comment_src.find("_network_available.clear()")
        # Tolerate a jittered sleep: ``time.sleep(300 + random.uniform(...))``
        # is the same logical 5-minute pause as ``time.sleep(300)``.
        sleep_pos = non_comment_src.find("time.sleep(300")
        self.assertGreater(clear_pos, -1,
                           "_handle_internet_outage must clear the event")
        self.assertGreater(sleep_pos, -1)
        self.assertLess(clear_pos, sleep_pos,
                        "event must be cleared BEFORE the 5-min sleep so "
                        "workers idle during the entire outage window")

    def test_outage_handler_sets_event_on_resume(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._handle_internet_outage)
        self.assertGreaterEqual(
            src.count("_network_available.set()"), 2,
            "_handle_internet_outage must set() the event on at least two "
            "exit paths: normal resume AND shutdown abort",
        )

    def test_fetch_url_waits_at_barrier(self):
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._fetch_url)
        non_comment_src = "\n".join(
            ln for ln in src.splitlines()
            if not ln.lstrip().startswith("#")
        )
        barrier_pos = non_comment_src.find("_network_available")
        proxy_pos = non_comment_src.find("_assign_proxy_for_url")
        self.assertGreater(barrier_pos, -1,
                           "_fetch_url must check _network_available")
        self.assertGreater(proxy_pos, -1)
        self.assertLess(
            barrier_pos, proxy_pos,
            "barrier must be at the TOP of _fetch_url, BEFORE proxy "
            "assignment / DNS / TCP work; otherwise the whole point of "
            "the barrier (skip useless work) is defeated",
        )

    def test_call_site_finally_restores_event_on_handler_exception(self):
        """If _handle_internet_outage raises AFTER clear() but BEFORE
        any set() (e.g. MemoryError during snapshot, broken-pipe on
        stdout, _log_entry IO error), the call site's finally block
        MUST set() the event -- otherwise every worker and the main
        thread deadlock forever at the barrier with no recovery path
        other than SIGTERM. Pinned by source-inspection: the finally
        block of the _handle_internet_outage() call site must contain
        ``self._network_available.set()``."""
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._fetch_url)
        # Find the try/finally that wraps _handle_internet_outage().
        call_pos = src.find("self._handle_internet_outage()")
        self.assertGreater(call_pos, -1)
        # Look for the finally-block content following that call. It
        # must restore the event before resetting _outage_in_progress
        # (so even if a finer-grained exception happens during the
        # _outage_in_progress reset itself, the event is already
        # restored).
        finally_block = src[call_pos:call_pos + 1500]
        self.assertIn(
            "_network_available.set()", finally_block,
            "Call site of _handle_internet_outage must restore the "
            "_network_available event in its finally block; otherwise "
            "an exception raised after clear() and before set() leaves "
            "the event permanently cleared and deadlocks all workers + "
            "the main thread at the _cf.wait() in _execute_crawl_phase.",
        )
        self.assertIn(
            "_outage_in_progress = False", finally_block,
            "finally block must also reset _outage_in_progress",
        )

    def test_post_loop_shutdown_recheck_present(self):
        """When the outage handler is aborted by shutdown, it set()s the
        event so workers idling at the barrier can wake up. But that
        wake-up arrives via the wait() returning True (event was set),
        which exits the inner while loop WITHOUT going through the
        timeout-branch ``if _SHUTDOWN_REQUESTED`` check. There must be
        a SECOND _SHUTDOWN_REQUESTED check immediately after the wait
        loop, before any HTTP work, so workers don't proceed during
        shutdown and risk tripping a new outage cycle (which would
        delay shutdown by another 5 minutes)."""
        import inspect as _inspect
        src = _inspect.getsource(AdvancedEmailScraper._fetch_url)
        # Strip comments so we don't false-positive on the doc comment.
        non_comment_src = "\n".join(
            ln for ln in src.splitlines()
            if not ln.lstrip().startswith("#")
        )
        # Locate the bounded-wait loop and the post-loop shutdown check.
        wait_loop_pos = non_comment_src.find(
            "while not self._network_available.wait("
        )
        proxy_pos = non_comment_src.find("_assign_proxy_for_url")
        self.assertGreater(wait_loop_pos, -1, "wait loop missing")
        self.assertGreater(proxy_pos, wait_loop_pos)
        between = non_comment_src[wait_loop_pos:proxy_pos]
        # Two _SHUTDOWN_REQUESTED checks must appear: the in-loop one
        # (timeout branch) and the post-loop one (event-set branch).
        self.assertGreaterEqual(
            between.count("_SHUTDOWN_REQUESTED"), 2,
            "_fetch_url must check _SHUTDOWN_REQUESTED both INSIDE the "
            "wait loop (timeout branch) and AFTER it (event-set branch); "
            "without the post-loop check, a shutdown-triggered set() of "
            "the event releases workers straight into _assign_proxy_for_url "
            "and they may trip a new outage cycle and delay shutdown.",
        )

    def test_barrier_blocks_workers_behaviourally(self):
        """Behavioural pin: when the event is cleared, _fetch_url must
        block at the barrier. We patch every method _fetch_url touches
        AFTER the barrier so the call genuinely returns None on shutdown
        (rather than spuriously raising AttributeError on an
        uninitialised scraper -- the prior version of this test was
        flagged for that exact spurious-pass risk).

        Synchronisation: instead of a fragile time.sleep() to wait for
        the worker thread to reach the barrier, we substitute an
        instrumented Event subclass whose ``wait()`` signals a
        secondary event the moment the worker enters it. This removes
        ALL timing dependence -- the test is deterministic regardless
        of CI load."""
        from unittest.mock import patch

        # Instrumented event: signals ``wait_called`` the moment any
        # thread enters .wait(), so the test can synchronise precisely
        # without a time.sleep() guess.
        class _InstrumentedEvent(threading.Event):
            def __init__(self):
                super().__init__()
                self.wait_called = threading.Event()
            def wait(self, timeout=None):  # noqa: D401
                self.wait_called.set()
                return super().wait(timeout)

        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s._network_available = _InstrumentedEvent()  # cleared by default

        proceeded = [False]
        def _stub_assign(self_, url):
            # Should NOT be reached during shutdown.
            proceeded[0] = True
            return None

        result = [None]
        ran_to_completion = [False]
        thread_exc = [None]

        def _runner():
            try:
                with patch.object(
                    AdvancedEmailScraper, "_assign_proxy_for_url", _stub_assign
                ):
                    result[0] = s._fetch_url(
                        "http://example.test/", ("http://example.test/", 0)
                    )
                    ran_to_completion[0] = True
            except BaseException as e:  # noqa: BLE001 -- diagnostic only
                thread_exc[0] = e

        global _SHUTDOWN_REQUESTED
        original_shutdown = _SHUTDOWN_REQUESTED
        try:
            t = threading.Thread(target=_runner, daemon=True)
            t.start()
            # Block until the worker thread has actually entered the
            # bounded wait. No more sleep-based race -- this returns
            # the instant the barrier's wait() is called, regardless
            # of CI load.
            entered = s._network_available.wait_called.wait(timeout=5.0)
            self.assertTrue(
                entered,
                "Worker thread did not reach the _network_available.wait() "
                "call within 5s -- the barrier may not be at the top of "
                "_fetch_url, or the thread crashed before reaching it",
            )
            # First assertion: the worker is BLOCKED at the barrier.
            # Neither the assign stub nor any other code has run yet.
            self.assertFalse(
                proceeded[0],
                "_fetch_url must NOT have called _assign_proxy_for_url yet "
                "while the barrier is cleared",
            )
            self.assertFalse(
                ran_to_completion[0],
                "_fetch_url must still be blocked at the barrier",
            )
            # Now trigger shutdown + set the event -- this models the
            # outage-handler's shutdown-abort set() at line ~2813.
            _SHUTDOWN_REQUESTED = True
            s._network_available.set()
            t.join(timeout=10)
            self.assertFalse(t.is_alive(),
                             "_fetch_url did not return after barrier release")
            # Behavioural pin: the post-loop _SHUTDOWN_REQUESTED check
            # MUST short-circuit before _assign_proxy_for_url. If the
            # check is missing or wrong, proceeded[0] is True (the stub
            # ran). With the check present, proceeded[0] stays False.
            self.assertFalse(
                proceeded[0],
                "_fetch_url proceeded to _assign_proxy_for_url after "
                "shutdown set() -- the post-loop _SHUTDOWN_REQUESTED "
                "check is missing or wrong",
            )
            self.assertTrue(
                ran_to_completion[0],
                f"_fetch_url did not return cleanly during shutdown; "
                f"thread_exc={thread_exc[0]!r}. The prior version of this "
                f"test passed spuriously because an uninitialised "
                f"AdvancedEmailScraper raised AttributeError downstream.",
            )
            self.assertIsNone(result[0],
                              "_fetch_url should return None on shutdown")
        finally:
            _SHUTDOWN_REQUESTED = original_shutdown


class TestPrescreenDomainsClosesResponse(unittest.TestCase):
    """``prescreen_domains._probe`` must close every HEAD/GET response so
    the urllib3 connection-pool slot is released. Without ``r.close()``
    on the success path (status_code < 500), 20k-domain lists pin
    thousands of pool slots until GC catches up and drive the process
    into ``OSError: [Errno 24] Too many open files``."""

    def test_probe_closes_response_in_finally(self):
        import inspect as _inspect
        src = _inspect.getsource(prescreen_domains)
        # Strip comment lines so the explanatory comment block doesn't
        # produce a false positive on its own use of the broken pattern.
        non_comment_src = "\n".join(
            ln for ln in src.splitlines()
            if not ln.lstrip().startswith("#")
        )
        # The probe must use try/finally with r.close() so EVERY exit
        # path (success, redirect, 405-fallback, exception) releases
        # the connection slot.
        self.assertIn(
            "finally:", non_comment_src,
            "prescreen_domains._probe must use try/finally to guarantee "
            "response close on success path (status_code < 500), not "
            "rely on GC to release the urllib3 pool slot",
        )
        self.assertIn(
            "r.close()", non_comment_src,
            "prescreen_domains._probe must explicitly close r in finally",
        )

    def test_probe_closes_response_behavioural(self):
        """Behavioural pin: probe a domain whose HEAD returns 200, and
        assert ``close()`` is invoked on the returned response."""
        close_calls = [0]

        class _FakeResp:
            status_code = 200
            def close(self):
                close_calls[0] += 1

        class _FakeSession:
            def head(self, *a, **kw):
                return _FakeResp()
            def get(self, *a, **kw):
                return _FakeResp()
            def close(self):
                pass

        from unittest.mock import patch as _patch
        with _patch(f'{__name__}._StealthSession', lambda *a, **kw: _FakeSession()):
            alive, dead = prescreen_domains(["example.test"], threads=1, timeout=0.1)
        self.assertEqual(alive, ["example.test"])
        self.assertEqual(dead, [])
        # close() must have been called at least once on the success path.
        # (Counted separately from the session.close() at end-of-pool.)
        self.assertGreaterEqual(
            close_calls[0], 1,
            "prescreen_domains must call r.close() on the success-path "
            "HEAD response to release the urllib3 pool slot",
        )


# -----------------------------------------------------------------------------
# Public entry point invoked by ``--self-test`` after the smoke-check stage.
# -----------------------------------------------------------------------------

def run_extended_tests(verbosity: int = 2) -> int:
    """Run the comprehensive embedded unittest suite.

    This is the second stage of ``--self-test``. The first stage exercises
    feature-level smoke checks (88 checks, no mocking); this stage runs the
    detailed test corpus defined in this file -- edge cases, negative paths,
    mocked dependencies, and regression pinning.

    All ``Test*(unittest.TestCase)`` subclasses defined at module level in
    this script are discovered automatically.

    Returns 0 if all tests passed, 1 otherwise.
    """
    print("[*] Running EMAIL-SCRAPPER --self-test (stage 2: extended unittest suite) ...")
    logger.info("Extended test suite started.")

    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    # Discover every Test* subclass at module level. Sort by name for stable
    # ordering across runs.
    test_classes = []
    for name, obj in sorted(globals().items()):
        if (isinstance(obj, type) and
                issubclass(obj, unittest.TestCase) and
                obj is not unittest.TestCase and
                name.startswith("Test")):
            test_classes.append((name, obj))

    if not test_classes:
        print("[!] No TestCase classes found in this module -- aborting.")
        return 1

    for _name, cls in test_classes:
        suite.addTests(loader.loadTestsFromTestCase(cls))

    if suite.countTestCases() == 0:
        print("[!] No test cases collected.")
        return 1

    print(f"[*] Collected {suite.countTestCases()} tests across "
          f"{len(test_classes)} TestCase classes\n")

    runner = unittest.TextTestRunner(verbosity=verbosity)
    result = runner.run(suite)

    passed = result.testsRun - len(result.failures) - len(result.errors)
    failed = len(result.failures) + len(result.errors)
    print(f"\n{'=' * 68}")
    print(f"  Total: {passed} passed, {failed} failed (of {result.testsRun})")
    print(f"{'=' * 68}")

    logger.info("Extended test suite finished: %d passed, %d failed",
                passed, failed)
    return 0 if result.wasSuccessful() else 1

# --- END: EXTENDED TEST SUITE ------------------------------------------------


# =============================================================================
# AUDIT-FIX REGRESSION TESTS — every test below pins a specific bug fixed in
# the audit sweep so the same bug cannot silently re-appear. These deliberately
# avoid mocks: each test exercises real data through the real code path so the
# protection still holds if a future refactor swaps internals around. (A
# regression test that mocks the very thing it claims to verify is worse than
# no test at all -- it gives false confidence and doesn't catch real bugs.)
# =============================================================================


class _AuditTestBase(unittest.TestCase):
    """Common setup used across the audit regression tests.

    The crawler's ``__init__`` is heavy (creates real network sessions,
    spawns the autotuner, opens log files). For unit tests that only
    poke at logic-level behaviour we bypass __init__ via ``__new__`` and
    populate just the attributes the unit under test reads. This is the
    same pattern the existing test suite uses, so the audit tests stay
    consistent with that convention. We never mock the unit under test
    itself -- only the surrounding scaffolding it would otherwise need.
    """

    def _bare_scraper(self):
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s.lock = RLock()
        s.proxies = []
        s.domain_proxy_map = {}
        s._proxy_strikes = {}
        s._dead_proxy_strikes = 3
        s.homepage_analysis_done = set()
        s.completed_domains = set()
        s.found_emails = defaultdict(set)
        s.SETTINGS = {
            "crawler_settings": {
                "common_email_providers": {
                    "gmail.com", "yahoo.com", "outlook.com",
                },
            }
        }
        s.COMMON_PROVIDERS = s.SETTINGS["crawler_settings"]["common_email_providers"]
        s.robots_cache = {}
        s._robots_fetch_lock = RLock()
        s._robots_domain_locks = OrderedDict()
        s._ROBOTS_LOCKS_MAX = 1024
        s.crawl_queue = deque()
        s.queued_urls = set()
        s._QUEUE_SOFT_CAP = 100_000
        s._session_pool = _SessionPool(proxies=s.proxies, size=4)
        return s


class TestAuditTlsVerifyDefault(_AuditTestBase):
    """Audit fix #1: ``--insecure-tls`` flips TLS verification OFF;
    default keeps it ON. Real ``_StealthSession`` instance, real
    ``verify`` attribute -- no mocks."""

    @classmethod
    def setUpClass(cls):
        cls._prev_insecture_tls = INSECURE_TLS

    @classmethod
    def tearDownClass(cls):
        INSECURE_TLS = cls._prev_insecture_tls

    def test_default_tls_verify_is_on(self):
        global INSECURE_TLS
        INSECURE_TLS = False
        sess = _StealthSession()
        try:
            self.assertTrue(
                sess._verify,
                "default _StealthSession must keep TLS verification ON; "
                "audit fix mandates verify=True unless --insecure-tls "
                "is passed",
            )
        finally:
            sess.close()

    def test_insecure_flag_disables_verify(self):
        global INSECURE_TLS
        INSECURE_TLS = True
        sess = _StealthSession()
        try:
            self.assertFalse(
                sess._verify,
                "--insecure-tls (INSECURE_TLS=True) must disable verify",
            )
        finally:
            sess.close()


class TestAuditTlsPlumbedToSmtpVerifier(unittest.TestCase):
    """Regression (#5): ``--insecure-tls`` must also disable TLS
    verification in the SMTP verifier's ``_smtp_handshake_once``,
    not just in the HTTP crawler's ``_StealthSession``."""

    def test_insecure_tls_overrides_smtp_verify_tls_in_handshake(self):
        import inspect as _inspect
        src = _inspect.getsource(AsyncEmailVerifier._smtp_handshake_once)
        # The production code must read INSECURE_TLS inside the handshake
        # and, when the flag is set, force ``smtp_verify_tls`` to False
        # BEFORE the TLS context is created. Two independent assertions
        # are too loose — a future refactor could leave the strings
        # scattered and still pass. We pin the EXACT two consecutive
        # lines (with correct indentation) so any change to the override
        # logic is detected immediately.
        self.assertIn(
            "if INSECURE_TLS:\n            smtp_verify_tls = False",
            src,
            "INSECURE_TLS must force smtp_verify_tls=False immediately "
            "after reading the per-service setting",
        )

    def test_insecure_tls_forces_cert_none_at_runtime(self):
        """When ``smtp_verify_tls=True`` in settings AND
        ``INSECURE_TLS=True`` (--insecure-tls), the SSL context created
        inside ``_smtp_handshake_once`` must have ``CERT_NONE``.

        We patch ONLY ``ssl.create_default_context`` to capture the
        returned context object — no network I/O is performed because
        ``_smtp_handshake_once`` catches connection errors internally
        (the MX host is picked to fail quickly). This exercises the
        real TLS-context creation code path without a mock on SMTP."""
        from unittest.mock import patch as _patch

        verifier = AsyncEmailVerifier({
            "verifier_settings": {
                "smtp_verify_tls": True,  # user explicitly enabled strict TLS
                "direct_check_user": "info",
                "direct_check_host": "example.com",
            },
        })
        captured_contexts = []

        real_create_context = ssl.create_default_context
        def _capturing_context(*a, **kw):
            ctx = real_create_context(*a, **kw)
            captured_contexts.append(ctx)
            return ctx

        global INSECURE_TLS
        prev_ins = INSECURE_TLS
        INSECURE_TLS = True
        try:
            with _patch("ssl.create_default_context", _capturing_context):
                asyncio.run(
                    verifier._smtp_handshake_once(
                        "test@insecure-tls-test.example",
                        "127.0.0.1",  # will fail quickly, no actual SMTP
                        1,            # port 1 is almost certainly closed
                    )
                )
        except Exception as e:
            logger.debug("Suppressed exception in test: %s", e, exc_info=True)
            # _smtp_handshake_once internally catches connection errors
            # and returns (None, reason). Any exception here means the
            # code path changed — but the context may still have been
            # captured before the error occurred. We check below.
        finally:
            INSECURE_TLS = prev_ins

        self.assertGreater(
            len(captured_contexts), 0,
            "_smtp_handshake_once must create at least one SSL context "
            "when INSECURE_TLS=True and smtp_verify_tls=True",
        )
        for ctx in captured_contexts:
            self.assertEqual(
                ctx.verify_mode, ssl.CERT_NONE,
                "even with smtp_verify_tls=True, INSECURE_TLS=True "
                "must force CERT_NONE on every SSL context",
            )
            self.assertFalse(
                ctx.check_hostname,
                "even with smtp_verify_tls=True, INSECURE_TLS=True "
                "must disable hostname check on every SSL context",
            )


class TestAuditCsvInjectionGuard(unittest.TestCase):
    """Audit fix #2: cells starting with =/+/-/@ get prefixed with a
    single quote so Excel/Sheets don't evaluate them as formulas. Real
    CSV write -> real file -> real read; the test exercises the
    production helpers (``_csv_safe_value`` / ``_csv_safe_row`` /
    ``_csv_safe_dict`` / ``_SafeCsvWriter``) so a regression in the
    real escaping logic is caught."""

    @classmethod
    def setUpClass(cls):
        cls._prev_csv_guard = CSV_INJECTION_GUARD

    @classmethod
    def tearDownClass(cls):
        CSV_INJECTION_GUARD = cls._prev_csv_guard

    def test_csv_safe_value_escapes_formula_triggers(self):
        global CSV_INJECTION_GUARD
        CSV_INJECTION_GUARD = True
        for trigger in ("=SUM(A1)", "+CMD", "-100", "@cmd", "\tinj", "\rinj"):
            self.assertEqual(
                _csv_safe_value(trigger), "'" + trigger,
                f"_csv_safe_value must prepend a quote to {trigger!r}",
            )
        # Strings that don't start with a formula trigger pass
        # through verbatim.
        self.assertEqual(_csv_safe_value("normal text"), "normal text")
        # Non-strings (numbers, None, bools) are returned unchanged.
        self.assertEqual(_csv_safe_value(42), 42)
        self.assertIsNone(_csv_safe_value(None))
        self.assertEqual(_csv_safe_value(True), True)

    def test_csv_safe_row_and_dict_apply_to_every_cell(self):
        global CSV_INJECTION_GUARD
        CSV_INJECTION_GUARD = True
        row = _csv_safe_row(["=evil", "+1", "ok", "-2", "@x", 7, None])
        self.assertEqual(
            row,
            ["'=evil", "'+1", "ok", "'-2", "'@x", 7, None],
        )
        d = _csv_safe_dict({"a": "=evil", "b": "ok", "c": "+pwn", "n": 1})
        self.assertEqual(
            d, {"a": "'=evil", "b": "ok", "c": "'+pwn", "n": 1},
        )

    def test_real_csv_write_uses_production_guard_end_to_end(self):
        """Drive the production helper through a real ``csv.writer`` and
        read the bytes back. This is the highest-fidelity test we have:
        if any future refactor breaks the escaping, the value Excel
        would interpret as a formula will round-trip back through
        ``csv.reader`` unquoted and the assertion will fail."""
        global CSV_INJECTION_GUARD
        CSV_INJECTION_GUARD = True
        tmp = tempfile.NamedTemporaryFile(
            "w", suffix=".csv", delete=False, newline="",
        )
        try:
            w = csv.writer(tmp)
            # Pass each cell through the production helper.
            w.writerow(_csv_safe_row([
                "=SUM(A1:A2)",
                "+1234",
                "-100",
                "@cmd",
                "normal",
            ]))
            tmp.close()
            with open(tmp.name, "r") as f:
                row = next(csv.reader(f))
            self.assertEqual(row[0], "'=SUM(A1:A2)")
            self.assertEqual(row[1], "'+1234")
            self.assertEqual(row[2], "'-100")
            self.assertEqual(row[3], "'@cmd")
            self.assertEqual(row[4], "normal")
        finally:
            os.unlink(tmp.name)

    def test_safe_csv_writer_wraps_writer_and_dictwriter(self):
        """The on-the-wire writer wrapper (``_SafeCsvWriter``) must
        apply the guard automatically so callers using it don't need
        to remember to wrap each row by hand."""
        global CSV_INJECTION_GUARD
        CSV_INJECTION_GUARD = True
        tmp = tempfile.NamedTemporaryFile(
            "w", suffix=".csv", delete=False, newline="",
        )
        try:
            writer = _SafeCsvWriter(csv.writer(tmp))
            writer.writerow(["=evil", "ok", "+1"])
            writer.writerows([["=again", "fine"], ["-2", "@x"]])
            tmp.close()
            with open(tmp.name, "r") as f:
                rows = list(csv.reader(f))
            self.assertEqual(rows[0], ["'=evil", "ok", "'+1"])
            self.assertEqual(rows[1], ["'=again", "fine"])
            self.assertEqual(rows[2], ["'-2", "'@x"])
        finally:
            os.unlink(tmp.name)

    def test_no_csv_escape_flag_disables_production_guard(self):
        global CSV_INJECTION_GUARD
        CSV_INJECTION_GUARD = False
        # With the guard off, ``_csv_safe_value`` is a pure
        # pass-through -- the same byte-for-byte string flows out.
        self.assertEqual(_csv_safe_value("=danger"), "=danger")
        self.assertEqual(
            _csv_safe_row(["=danger", "+pwn"]),
            ["=danger", "+pwn"],
        )


class TestAuditEmailRegexAsciiOnly(unittest.TestCase):
    """Audit fix #3: ``EMAIL_REGEX`` only matches ASCII. Unicode
    homoglyphs (greek alpha that looks like 'a') would have masqueraded
    as legit emails and poisoned the verifier. Real regex, real strings."""

    def test_ascii_email_matches(self):
        self.assertTrue(EMAIL_REGEX.match("alice@example.com"))

    def test_greek_alpha_homoglyph_is_rejected(self):
        # Greek alpha (U+03B1) and Cyrillic small a (U+0430) both render
        # like Latin 'a' but are NOT ASCII. EMAIL_REGEX must reject.
        self.assertFalse(EMAIL_REGEX.match("\u03b1lice@example.com"))
        self.assertFalse(EMAIL_REGEX.match("\u0430lice@example.com"))

    def test_emoji_in_localpart_is_rejected(self):
        self.assertFalse(EMAIL_REGEX.match("alice\U0001F600@example.com"))


class TestAuditExtractDomainLowercase(_AuditTestBase):
    """Audit fix #4 (HIGH-5): ``_extract_domain`` always lowercases the
    netloc so per-domain maps don't double-key on case. Real method,
    real inputs."""

    def test_mixed_case_collapses_to_one(self):
        s = self._bare_scraper()
        a = s._extract_domain("https://Example.com/contact")
        b = s._extract_domain("https://EXAMPLE.COM/about")
        c = s._extract_domain("https://example.com/")
        self.assertEqual(a, "example.com")
        self.assertEqual(b, "example.com")
        self.assertEqual(c, "example.com")

    def test_port_is_stripped(self):
        s = self._bare_scraper()
        self.assertEqual(s._extract_domain("https://Example.COM:8443/x"),
                         "example.com")

    def test_invalid_url_returns_none(self):
        s = self._bare_scraper()
        self.assertIsNone(s._extract_domain("not a url"))


class TestAuditIsTargetDomainEtld(_AuditTestBase):
    """Audit fix #5 (HIGH-4): ``is_target_domain`` classification uses
    ``_is_same_domain`` (eTLD+1) instead of substring. Previously the
    naive first-label substring matched ``acm`` against ``acmecorp.com``
    -- a target/non-target classification flip-flop that polluted the
    output. Real call into the real method on the real class."""

    def test_acm_is_not_subdomain_of_acmecorp(self):
        # Replicate the exact comparison the production code does:
        # _is_same_domain compares eTLD+1, so acm.com and acmecorp.com
        # must classify as different.
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        # _is_same_domain uses get_tld which we already imported.
        self.assertFalse(s._is_same_domain("https://acm.com/a", "acmecorp.com"))
        self.assertTrue(s._is_same_domain("https://www.acmecorp.com/a", "acmecorp.com"))

    def test_subdomain_is_same_etld(self):
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        self.assertTrue(s._is_same_domain("https://api.example.com/", "example.com"))
        self.assertTrue(s._is_same_domain("https://blog.staging.example.com/", "example.com"))


class TestAuditRobotsCachesEmptyOnFailure(_AuditTestBase):
    """Audit fix #6 (HIGH-6): ``_get_robots_rules`` caches empty
    _RobotsRules() on network failure so we don't refetch
    robots.txt on every URL. Real cache, real parser."""

    def test_empty_rules_does_not_block_anything(self):
        rules = _RobotsRules()
        # An empty ruleset must allow every path. Without this the
        # cached-on-failure behaviour would block every URL on a
        # transient outage. ``is_allowed`` takes a path only; UA
        # matching is folded into the parser at construction time.
        self.assertTrue(rules.is_allowed("/"))
        self.assertTrue(rules.is_allowed("/admin/secret"))

    def test_cached_failure_value_is_truthy_dictlike(self):
        s = self._bare_scraper()
        s.robots_cache["example.com"] = _RobotsRules()
        # A None entry would force a refetch every call (caller does
        # ``if cached is not None: ...``). _RobotsRules() is the right
        # cached-on-failure sentinel.
        self.assertIsNotNone(s.robots_cache["example.com"])
        self.assertIsInstance(s.robots_cache["example.com"], _RobotsRules)


class TestAuditCaptchaDetection(_AuditTestBase):
    """Audit fix #7 (HIGH-9): ``_detect_captcha`` only fires on
    specific challenge markers, not on bare ``cloudflare`` (which
    appears on every CF-fronted page). Real method, real HTML."""

    def test_cf_turnstile_fires(self):
        s = self._bare_scraper()
        self.assertTrue(s._detect_captcha("<div class='cf-turnstile'></div>"))

    def test_g_recaptcha_fires(self):
        s = self._bare_scraper()
        self.assertTrue(s._detect_captcha('<div class="g-recaptcha"></div>'))

    def test_just_a_moment_fires(self):
        s = self._bare_scraper()
        self.assertTrue(s._detect_captcha("<title>Just a moment...</title>"))

    def test_bare_cloudflare_token_does_not_fire(self):
        s = self._bare_scraper()
        # Audit found this was the production bug: pages mentioning
        # Cloudflare in marketing copy / privacy policies were being
        # tagged as captcha-walled and uselessly rerouted to Tier-2.
        self.assertFalse(s._detect_captcha(
            "We use Cloudflare to keep our site fast and secure."
        ))

    def test_bare_captcha_word_does_not_fire(self):
        # Regression test for the ``'captcha'`` removal from
        # ``_CAPTCHA_INDICATORS``. The bare word ``captcha`` appears in
        # countless legitimate non-challenge contexts: privacy policies
        # ("We use CAPTCHA to prevent spam"), help articles, FAQ
        # navigation, blog posts about bot detection, etc. Every such
        # page was falsely flagged and rerouted to Tier-2, burning CPU
        # and RAM for no benefit.
        s = self._bare_scraper()
        # Privacy policy mentioning captchas in prose:
        self.assertFalse(s._detect_captcha(
            "This site uses CAPTCHA to prevent automated form submissions."
        ))
        # Help / FAQ article:
        self.assertFalse(s._detect_captcha(
            "What is a CAPTCHA and how does it work?"
        ))
        # Blog post discussing captchas:
        self.assertFalse(s._detect_captcha(
            "In this article we compare different captcha solutions."
        ))
        # Footer disclaimer mentioning privacy policy (not a widget):
        self.assertFalse(s._detect_captcha(
            "This page uses captcha technology for spam prevention."
        ))
        # Note: we deliberately do NOT test "reCAPTCHA" here — that is a
        # legitimate widget name that the ``'recaptcha'`` indicator in
        # ``_CAPTCHA_INDICATORS`` is supposed to catch. The bare word
        # ``captcha`` is what was removed from the indicator list because
        # it appears in countless non-widget contexts.
        # The word in a navigation / page heading:
        self.assertFalse(s._detect_captcha(
            "<a href='/help/captcha'>Captcha troubleshooting</a>"
        ))
        # Sanity: widget markers must still fire.
        self.assertTrue(s._detect_captcha(
            "<div class='cf-turnstile'></div>"
        ))


