        prev_j, prev_t = _CF_BYPASS_HUMANISH_JITTER, _CF_BYPASS_CHALLENGE_TIMEOUT
        _CF_BYPASS_HUMANISH_JITTER = False
        _CF_BYPASS_CHALLENGE_TIMEOUT = 0.05  # so the test is fast
