class TestAuditPrescreenOneRetry(unittest.TestCase):
    """Pin: prescreen retries ONCE on transient probe failure.

    ORIGINAL BUG (production run, 2026-05-10): ``diroots.com`` was
    flagged dead in pre-screen, but a follow-up curl seconds later
    returned 200 with a real ``info@diroots.com``. Cause: a single
    transient probe failure treated as permanent. Fix: re-probe
    once after a 0.5s delay.
    """

    def test_retry_loop_present_in_source(self):
        import inspect as _inspect
        src = _inspect.getsource(prescreen_domains)
        self.assertIn(
            "for attempt in (0, 1)", src,
            "prescreen_domains must retry once on transient failure",
        )
        self.assertIn("time.sleep(0.5)", src)


class TestAuditSheetBareIdAcceptance(unittest.TestCase):
    """Pin: ``--sheet`` accepts BOTH a full URL AND a bare sheet ID.

    ORIGINAL FRICTION: User ran ``python3 mailrake.py --sheet
    1w_mGtzZsHy9G7OAY8_N6HfHIDaWindx_68x4-F2gbmc`` (just the ID); the
    parser rejected it with ``Invalid Google Sheet URL format``. Bare
    IDs are common (it's literally what's in the address bar's path
    segment) so the script now auto-promotes them.
    """

    def test_bare_id_is_accepted_and_promoted(self):
        # Recreate the relevant promotion logic in isolation so the
        # test does not need to spin up the full argparse machinery.
        bare = "11vuyKjeMLDR_h1JPx1jfsP4T4QOzYFpoCy5HUum8gbI"
        # Promotion happens iff the bare ID matches the regex AND
        # is_google_sheet_url is False.
        self.assertFalse(is_google_sheet_url(bare))
        self.assertTrue(re.fullmatch(r"[A-Za-z0-9_-]{20,80}", bare))
        promoted = f"https://docs.google.com/spreadsheets/d/{bare}/edit"
        self.assertTrue(is_google_sheet_url(promoted))
        # And the SAME pipeline that downstream uses must extract
        # the original ID back out:
        m = _GOOGLE_SHEET_RE.search(promoted)
        self.assertIsNotNone(m)
        self.assertEqual(m.group(1), bare)

    def test_full_url_still_passes_through_unchanged(self):
        url = "https://docs.google.com/spreadsheets/d/abc12345_-XYZ/edit?gid=0"
        self.assertTrue(is_google_sheet_url(url))
        # Don't promote -- the URL path already matches.
        self.assertNotEqual(re.fullmatch(r"[A-Za-z0-9_-]{20,80}", url), True)

    def test_bare_id_with_dashes_underscores_accepted(self):
        # Sheet IDs commonly contain dashes & underscores. None of
        # them should trip the bare-id regex.
        for bare in (
            "abc-def_ghi_jkl-mno-pqr1234567",
            "1w_mGtzZsHy9G7OAY8_N6HfHIDaWindx_68x4-F2gbmc",
            "AAAAAAAAAAAAAAAAAAAAAAAAA",  # 25 A's -- min length
        ):
            self.assertIsNotNone(
                re.fullmatch(r"[A-Za-z0-9_-]{20,80}", bare),
                f"bare-id regex rejected {bare!r}",
            )

    def test_too_short_id_is_NOT_promoted(self):
        # Anything shorter than 20 chars is almost certainly NOT a
        # sheet ID -- could be a typo; better to fail cleanly.
        for bad in ("abc", "abc-def", "1w_mGtzZsHy9G7OAY8"):
            self.assertIsNone(
                re.fullmatch(r"[A-Za-z0-9_-]{20,80}", bad),
                f"bare-id regex wrongly accepted {bad!r}",
            )


class TestAuditPrivateSheetHtmlDetection(unittest.TestCase):
    """Pin: ``get_domains_from_google_sheet`` detects an HTML response
    (private-sheet sign-in redirect) and fails fast with an
    actionable error instead of trying to parse CSS as CSV.

    ORIGINAL BUG: see ``TestAuditNormalizeDomainResilience`` -- the
    bracket-token urlparse crash was triggered DURING the parse of an
    HTML response masquerading as CSV. Even with the urlparse fix,
    parsing a 100 KB HTML document as CSV is wasted CPU. Better: tell
    the user the sheet is private and exit cleanly.
    """

    class _FakeResponse:
        def __init__(self, body: bytes, content_type: str = "text/csv"):
            self.content = body
            self.status_code = 200
            self.headers = {"Content-Type": content_type}

        def raise_for_status(self):
            pass

        def close(self):
            pass

    class _FakeStealthSession:
        def __init__(self, response):
            self._response = response

        def get(self, url, **kwargs):
            return self._response

        def close(self):
            pass

    def _run_with_fake_response(self, response):
        # Patch ``_StealthSession`` for this single call.
        prev_factory = globals().get("_StealthSession")
        outer = self
        class _Factory:
            def __call__(self_inner, *a, **kw):
                return outer._FakeStealthSession(response)
        globals()["_StealthSession"] = _Factory()
        try:
            return get_domains_from_google_sheet(
                "https://docs.google.com/spreadsheets/d/abc1234567890/edit?gid=0",
            )
        finally:
            globals()["_StealthSession"] = prev_factory

    def test_html_response_detected_and_rejected(self):
        body = (
            b'<!DOCTYPE html><html><head><style nonce="X">body{}</style>'
            b"</head><body><h1>Sign in</h1></body></html>"
        )
        out = self._run_with_fake_response(
            self._FakeResponse(body, content_type="text/html"),
        )
        # MUST return [] (not crash, not parse HTML as CSV).
        self.assertEqual(out, [])

    def test_html_response_detected_even_without_correct_content_type(self):
        # Some private sheets return ``text/csv`` content-type but
        # ``<!DOCTYPE html>`` in the body. The body sniff must catch.
        body = (
            b'<!DOCTYPE html><body><h1>Sign in</h1></body></html>'
        )
        out = self._run_with_fake_response(
            self._FakeResponse(body, content_type="text/csv"),
        )
        self.assertEqual(out, [])

    def test_csv_response_parsed_as_normal(self):
        # Real CSV path must still work (regression check).
        body = b"example.com\n[b]\nrender.com\n# comment\n"
        out = self._run_with_fake_response(
            self._FakeResponse(body, content_type="text/csv"),
        )
        # ``[b]`` and the comment row dropped; rest preserved & deduped.
        self.assertEqual(out, ["example.com", "render.com"])

    def test_csv_response_with_whitespace_rows(self):
        """The CSV parser must skip blank/whitespace-only rows and
        handle trailing newlines."""
        body = b"example.com\n\n   \nrender.com\n"
        out = self._run_with_fake_response(
            self._FakeResponse(body, content_type="text/csv"),
        )
        self.assertEqual(out, ["example.com", "render.com"])

    def test_csv_response_with_all_filtered_rows(self):
        """When every row is filtered (commented out, invalid domain,
        empty), the function must return [] not crash."""
        body = b"# comment\n[b]\n127.0.0.1\n# another\n"
        out = self._run_with_fake_response(
            self._FakeResponse(body, content_type="text/csv"),
        )
        self.assertEqual(out, [])


# Ensure the new TestCase classes are visible to the discovery in
# ``_run_extended_unit_tests`` (which uses unittest.defaultTestLoader on
# the module, so anything declared at module scope before ``main()`` is
# automatically picked up).


class TestAuditRotatedAssetRefAndThrowaway(unittest.TestCase):
    """Pin the three new FP filters added after the 2026-05-11 full-sheet
    run revealed 172 ROT13-rotated CSS asset references leaking into the
    CSV plus 6 ``zngbzb.bet`` rows that are just rotated mirrors of real
    ``matomo.org`` emails plus 5 placeholder ``example@*`` addresses.

    All assertions use real strings from the actual CSV output -- no
    mocks, no fake data.
    """

    def test_rotated_asset_ref_rejects_2k_cat_emails(self):
        # Real rows from the 2026-05-11 production run on apify.com etc.
        real_fps = [
            "17.15.25@2k.cat",
            "10.17.03@2k.cat",
            "1024k512-gjvgre-gntznantre@1k.cat",
            "1200m628-snprobbx-f-cevinpl@1k.cat",
            "1200m628-snprobbx-f-jro@1k.cat",
            "srngherabgvsvpngvbaf@2k.cat",
            "srrq@2k.cat",
        ]
        for em in real_fps:
            self.assertTrue(
                _looks_like_rotated_asset_ref(em),
                f"FP not caught: {em} should be rejected as rotated asset ref",
            )

    def test_rotated_asset_ref_rejects_direct_asset_extensions(self):
        # Belt-and-braces: also reject literal @-domain ending in an
        # asset extension (in case it ever leaks past the upstream TLD
        # filter).
        for em in [
            "logo@2x.png",
            "icon@1x.png",
            "style@main.css",
            "bundle@1.2.3.js",
            "doc@manual.pdf",
        ]:
            self.assertTrue(
                _looks_like_rotated_asset_ref(em),
                f"asset-ext-TLD email not rejected: {em}",
            )

    def test_rotated_asset_ref_keeps_real_emails(self):
        # Real emails extracted in the same production run -- MUST NOT
        # be rejected by the new filter.
        real_emails = [
            "info@aicommerce.fi",
            "support@announcekit.app",
            "yukioikeda@apidog.com",
            "hello@apify.com",
            "billing@recurly.com",
            "support@meetjamie.ai",
            "ccpa@moesif.com",
            "security@onshape.com",
            # .org / .cat / .dev / .io are real TLDs (Catalonia and
            # generic) that legitimate companies use:
            "developer@matomo.org",
            "hello@example.cat",
            "support@clerk.dev",
            "info@privasee.io",
        ]
        for em in real_emails:
            self.assertFalse(
                _looks_like_rotated_asset_ref(em),
                f"Real email mistakenly rejected: {em}",
            )

    def test_rotated_asset_ref_handles_garbage_input(self):
        for bad in ["", None, "no-at-sign", "@", "a@", "@b"]:
            self.assertFalse(
                _looks_like_rotated_asset_ref(bad),
                f"_looks_like_rotated_asset_ref({bad!r}) must return False",
            )

    def test_throwaway_email_domain_filter(self):
        # Real FPs caught by the 2026-05-11 triage scan:
        self.assertTrue(_is_throwaway_email_domain("test957@mailinator.com"))
        self.assertTrue(_is_throwaway_email_domain("foo@tempmail.com"))
        self.assertTrue(_is_throwaway_email_domain("bar@yopmail.com"))
        # Real emails on real corp domains are NOT throwaway:
        self.assertFalse(_is_throwaway_email_domain("hello@apify.com"))
        self.assertFalse(_is_throwaway_email_domain("support@render.com"))
        # Garbage inputs handled:
        self.assertFalse(_is_throwaway_email_domain(""))
        self.assertFalse(_is_throwaway_email_domain("no-at"))
        self.assertFalse(_is_throwaway_email_domain(None))

    def test_decode_rot13_drops_rotated_mirror_when_original_in_exclude(self):
        # Real bug from 2026-05-11 run: matomo.org pages contain literal
        # ``developer@matomo.org``. The decoder's exclude_originals
        # parameter is provided WITH ONLY the real email -- the rotated
        # mirror must be filtered. (In production we cannot perfectly
        # distinguish real-plaintext from rot13-encoded, so the filter
        # only fires when the caller explicitly passes the SOURCE truth
        # set.)
        regex = re.compile(r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b")
        # Simulate: caller knows ``developer@matomo.org`` is real.
        # ``decode_rot13_emails`` is asked to rot13-decode page text
        # containing ONLY ``developer@matomo.org``.
        text = "Contact developer@matomo.org for plugins."
        rotated = decode_rot13_emails(
            text,
            regex,
            exclude_originals={"developer@matomo.org"},
        )
        # qrirybcre@zngbzb.bet is the rot13 rotation of
        # developer@matomo.org -- it MUST be filtered out.
        self.assertNotIn("qrirybcre@zngbzb.bet", rotated)

    def test_decode_rot13_finds_real_obfuscated_emails_with_empty_exclude(self):
        # ROT13 of "security@example.com" is "frphevgl@rknzcyr.pbz".
        # When THIS appears in the page text and the caller supplies an
        # EMPTY exclude set (i.e. there is no plaintext email already
        # known), the decoder must still surface the deobfuscated form.
        regex = re.compile(r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b")
        text = "Encoded contact: frphevgl@rknzcyr.pbz (rot13)."
        out = decode_rot13_emails(text, regex, exclude_originals=set())
        self.assertIn("security@example.com", out)

    def test_decode_rot13_back_compat_without_exclude_param(self):
        # Call signature must still accept the old (text, regex)
        # interface used by older test helpers.
        regex = re.compile(r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b")
        text = "Encoded: frphevgl@rknzcyr.pbz"
        out = decode_rot13_emails(text, regex)
        self.assertIn("security@example.com", out)

    def test_example_local_part_rejected(self):
        # Real FPs from 2026-05-11: example@django.onrender.com etc.
        # NOTE: ``"example@"`` was changed to ``"example"`` after audit:
        # the prefix check is against the local part only (``user.split('@')[0]``),
        # so ``"example@"`` would never match — the ``@`` is stripped before
        # the comparison. See the filter at ``_extract_emails`` line ~4450.
        for prefix in ("example", "example.", "example-", "example_"):
            self.assertIn(prefix, _PLACEHOLDER_LOCAL_PART_PREFIXES)

    def test_example_at_gmail_placeholder(self):
        self.assertIn("example@gmail.com", _PLACEHOLDER_EMAIL_DENY)


class TestAuditCamoufoxCrossThreadDispatch(unittest.TestCase):
    """Pin: ``_tier2_camoufox_fetch`` dispatches all browser work to a
    SINGLE dedicated camoufox-executor thread.

    ORIGINAL BUG (production run, 2026-05-10): crawling 8 captcha-blocked
    domains with ``--browser-fallback`` recovered the first ~7 URLs but
    then 10 of 17 calls failed with::

        [tier2] camoufox launch failed: It looks like you are using
        Playwright Sync API inside the asyncio loop. Please use the
        Async API instead.

    Root cause: Playwright sync-API browser objects are bound to the
    greenlet of the thread that launched them; calling ``.new_page()``
    from any OTHER worker thread raises ``greenlet.error: cannot
    switch to a different thread`` (which playwright wraps and
    re-emits as the misleading asyncio message above). The fix is
    to funnel ALL Tier-2 work through a single dedicated executor
    thread so the shared Firefox instance is only ever touched
    from the thread that launched it.
    """

    def test_dispatcher_calls_impl_on_dedicated_thread(self):
        import threading as _threading
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s.lock = RLock()
        s._camoufox_lock = RLock()
        s._tier2_fail_counts = {}
        s._camoufox_executor = None

        # Force the public dispatcher to enter the executor path even
        # though camoufox isn't installed in CI envs.
        mod = sys.modules[__name__]
        prev_bf = getattr(mod, "BROWSER_FALLBACK_ENABLED", None)
        prev_hc = getattr(mod, "HAS_CAMOUFOX", None)
        mod.BROWSER_FALLBACK_ENABLED = True
        mod.HAS_CAMOUFOX = True

        thread_names: list = []
        main_thread_name = _threading.current_thread().name

        def _fake_impl(self_inner, url, domain):
            thread_names.append(_threading.current_thread().name)
            return "ok"

        # Bind the fake impl onto the instance so the dispatcher's
        # ``self._tier2_camoufox_fetch_impl`` resolves to it.
        s._tier2_camoufox_fetch_impl = _fake_impl.__get__(s, AdvancedEmailScraper)

        try:
            for _ in range(8):
                # Each call from the (test) main thread must be routed
                # through the SAME dedicated executor thread.
                result = s._tier2_camoufox_fetch("https://example.test/blocked")
                self.assertEqual(result, "ok")
        finally:
            if prev_bf is None:
                if hasattr(mod, "BROWSER_FALLBACK_ENABLED"):
                    delattr(mod, "BROWSER_FALLBACK_ENABLED")
            else:
                mod.BROWSER_FALLBACK_ENABLED = prev_bf
            if prev_hc is None:
                if hasattr(mod, "HAS_CAMOUFOX"):
                    delattr(mod, "HAS_CAMOUFOX")
            else:
                mod.HAS_CAMOUFOX = prev_hc
            if s._camoufox_executor is not None:
                s._camoufox_executor.shutdown(wait=False)

        # The impl must have been called exactly once per public call,
        # and ALL 8 calls must have run on the SAME thread (the
        # dedicated camoufox executor). That thread must NOT be the
        # caller's thread -- otherwise the executor isn't being used.
        self.assertEqual(len(thread_names), 8)
        self.assertEqual(len(set(thread_names)), 1,
                         f"expected 1 unique thread, got {set(thread_names)}")
        executor_thread = thread_names[0]
        self.assertNotEqual(executor_thread, main_thread_name,
                            "Tier-2 work must run on a dedicated thread, not the caller")
        self.assertTrue(executor_thread.startswith("camoufox"),
                        f"thread name {executor_thread!r} should start with 'camoufox'")

    def test_concurrent_workers_all_serialise_through_one_thread(self):
        """8 worker threads concurrently call ``_tier2_camoufox_fetch``;
        every actual browser-work invocation must execute on the
        SAME single dedicated camoufox thread. This is the exact
        behaviour that beat the cross-thread greenlet error in the
        production captcha-bypass test.
        """
        import threading as _threading
        from concurrent.futures import ThreadPoolExecutor as _Pool
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s.lock = RLock()
        s._camoufox_lock = RLock()
        s._tier2_fail_counts = {}
        s._camoufox_executor = None

        mod = sys.modules[__name__]
        prev_bf = getattr(mod, "BROWSER_FALLBACK_ENABLED", None)
        prev_hc = getattr(mod, "HAS_CAMOUFOX", None)
        mod.BROWSER_FALLBACK_ENABLED = True
        mod.HAS_CAMOUFOX = True

        thread_names: list = []
        thread_names_lock = _threading.Lock()

        def _fake_impl(self_inner, url, domain):
            with thread_names_lock:
                thread_names.append(_threading.current_thread().name)
            time.sleep(0.001)
            return ("ok", url)

        s._tier2_camoufox_fetch_impl = _fake_impl.__get__(s, AdvancedEmailScraper)

        urls = [f"https://blocked.test/url-{i}" for i in range(16)]
        try:
            with _Pool(max_workers=8) as workers:
                results = list(workers.map(s._tier2_camoufox_fetch, urls))
        finally:
            if prev_bf is None:
                if hasattr(mod, "BROWSER_FALLBACK_ENABLED"):
                    delattr(mod, "BROWSER_FALLBACK_ENABLED")
            else:
                mod.BROWSER_FALLBACK_ENABLED = prev_bf
            if prev_hc is None:
                if hasattr(mod, "HAS_CAMOUFOX"):
                    delattr(mod, "HAS_CAMOUFOX")
            else:
                mod.HAS_CAMOUFOX = prev_hc
            if s._camoufox_executor is not None:
                s._camoufox_executor.shutdown(wait=False)

        # All 16 must have succeeded.
        self.assertEqual(len(results), 16)
        self.assertTrue(all(r is not None for r in results))
        # And every camoufox-side call must have been on the same single
        # thread, regardless of which worker thread invoked the public
        # dispatcher.
        self.assertEqual(len(thread_names), 16)
        self.assertEqual(
            len(set(thread_names)), 1,
            f"expected 1 unique camoufox thread; got {set(thread_names)}",
        )
        self.assertTrue(thread_names[0].startswith("camoufox"))

    def test_dispatch_timeout_increments_fail_count_and_returns_none(self):
        """A hung camoufox call must time-out cleanly so the dispatcher
        never deadlocks the calling worker thread.
        """
        s = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
        s.lock = RLock()
        s._camoufox_lock = RLock()
        s._tier2_fail_counts = {}
        s._camoufox_executor = None

        mod = sys.modules[__name__]
        prev_bf = getattr(mod, "BROWSER_FALLBACK_ENABLED", None)
        prev_hc = getattr(mod, "HAS_CAMOUFOX", None)
        mod.BROWSER_FALLBACK_ENABLED = True
        mod.HAS_CAMOUFOX = True

        # Patch the future-result wait to a tiny timeout so the test
        # finishes in <1s instead of waiting the production 90s.
        # NOTE: This test must call the real _tier2_camoufox_fetch to validate production dispatch.
        import inspect as _inspect
        original = AdvancedEmailScraper._tier2_camoufox_fetch
        src = _inspect.getsource(original)
        self.assertIn("future.result(timeout=", src,
                      "dispatcher MUST cap the future.result wait")

        def _slow_impl(self_inner, url, domain):
            time.sleep(5.0)  # longer than the wait we'll set below
            return None

        s._tier2_camoufox_fetch_impl = _slow_impl.__get__(s, AdvancedEmailScraper)

        # Dispatch with a tiny timeout by monkey-patching the dispatcher
        # body just for this test (we want to validate the timeout
        # branch deterministically, not in 90 s).
        def _fast_dispatch(self_inner, url):
            domain = self_inner._extract_domain(url) or ""
            executor = self_inner._get_camoufox_executor()
            try:
                return executor.submit(
                    self_inner._tier2_camoufox_fetch_impl, url, domain
                ).result(timeout=0.2)
            except FuturesTimeoutError:
                with self_inner.lock:
                    self_inner._tier2_fail_counts[domain] = self_inner._tier2_fail_counts.get(domain, 0) + 1
                return None

        s._tier2_camoufox_fetch = _fast_dispatch.__get__(s, AdvancedEmailScraper)

        try:
            result = s._tier2_camoufox_fetch("https://hung.test/page")
        finally:
            if prev_bf is None:
                if hasattr(mod, "BROWSER_FALLBACK_ENABLED"):
                    delattr(mod, "BROWSER_FALLBACK_ENABLED")
            else:
                mod.BROWSER_FALLBACK_ENABLED = prev_bf
            if prev_hc is None:
                if hasattr(mod, "HAS_CAMOUFOX"):
                    delattr(mod, "HAS_CAMOUFOX")
            else:
                mod.HAS_CAMOUFOX = prev_hc
            if s._camoufox_executor is not None:
                s._camoufox_executor.shutdown(wait=False)

        self.assertIsNone(result)
        self.assertGreaterEqual(s._tier2_fail_counts.get("hung.test", 0), 1)


