class TestSmokeMeasureInternetSpeed(unittest.TestCase):
    def test_returns_dict_with_expected_keys(self):
        from unittest.mock import patch, MagicMock
        fake_resp = MagicMock()
        fake_resp.ok = True
        fake_resp.content = b"x" * 100000
        # Ensure context manager entry returns the same object so
        # resp.ok / resp.content are available inside the with block.
        fake_resp.__enter__.return_value = fake_resp
        with patch("requests.get", return_value=fake_resp) as _mock_get:
            result = measure_internet_speed(timeout=5.0)
        self.assertIsInstance(result, dict)
        for key in ("ok", "rtt_ms", "mbps", "bytes", "elapsed"):
            self.assertIn(key, result, f"missing key {key!r}")
        self.assertIsInstance(result["ok"], bool)
        self.assertIsInstance(result["rtt_ms"], float)
        self.assertIsInstance(result["mbps"], float)
        self.assertGreaterEqual(result["rtt_ms"], 0.0)
        self.assertGreaterEqual(result["mbps"], 0.0)
        self.assertGreaterEqual(result["bytes"], 0)
        self.assertGreaterEqual(result["elapsed"], 0.0)
        self.assertTrue(result["ok"])


class TestSmokeSelftestRun(unittest.TestCase):
    def test_passes_through_ok_result(self):
        report = _SelfTestReport()
        ok = _selftest_run(report, "mod", lambda: "all good")
        self.assertTrue(ok)
        self.assertIn(("mod", "PASS", "all good"), report.entries)

    def test_catches_exception_and_records_fail(self):
        report = _SelfTestReport()
        def _crash():
            raise ValueError("boom")
        ok = _selftest_run(report, "crash", _crash)
        self.assertFalse(ok)
        self.assertEqual(report.failed, 1)
        _, status, detail = report.entries[-1]
        self.assertEqual(status, "FAIL")
        self.assertIn("ValueError: boom", detail)

    def test_with_fail_fast_hint(self):
        report = _SelfTestReport()
        def _crash():
            raise RuntimeError("bad")
        _selftest_run(report, "hinted", _crash, fail_fast_hint="check line 42")
        _, status, detail = report.entries[-1]
        self.assertEqual(status, "FAIL")
        self.assertIn("bad", detail)
        self.assertIn("check line 42", detail)


