class TestProductionSessionPoolPopulate(unittest.TestCase):
    """_SessionPool._populate creates sessions with proxy/fingerprint."""

    def test_populate_fills_to_size(self):
        pool = _SessionPool(proxies=["http://p1"], size=3,
                            max_failures_before_retire=2, block_seconds_on_retire=30)
        pool._populate()
        self.assertEqual(len(pool._sessions), 3)

    def test_populate_without_proxies(self):
        pool = _SessionPool(proxies=[], size=2,
                            max_failures_before_retire=2, block_seconds_on_retire=30)
        pool._populate()
        self.assertEqual(len(pool._sessions), 2)
        for s in pool._sessions:
            self.assertIsNone(s.proxy)

    def test_acquire_returns_non_blocked(self):
        pool = _SessionPool(proxies=[], size=1,
                            max_failures_before_retire=2, block_seconds_on_retire=30)
        pool._populate()
        s = pool.acquire()
        self.assertIsNotNone(s)

    def test_report_ok_resets_failures(self):
        pool = _SessionPool(proxies=[], size=1,
                            max_failures_before_retire=2, block_seconds_on_retire=30)
        pool._populate()
        s = pool._sessions[0]
        pool.report(s, ok=False)
        self.assertEqual(s.failures, 1)
        pool.report(s, ok=True)
        self.assertEqual(s.failures, 0)
        self.assertEqual(s.successes, 1)

    def test_report_fail_blocks_after_max(self):
        pool = _SessionPool(proxies=["http://p1"], size=1,
                            max_failures_before_retire=2, block_seconds_on_retire=300)
        pool._populate()
        s = pool._sessions[0]
        pool.report(s, ok=False)
        pool.report(s, ok=False)
        # Original session is blocked; a replacement was appended.
        self.assertGreater(s.blocked_until, time.time())
        self.assertGreaterEqual(len(pool._sessions), 1)
        # The pool maintains at least 'size' active sessions by
        # replacing blocked ones.
        live = [x for x in pool._sessions if x.blocked_until <= time.time()]
        self.assertGreaterEqual(len(live), 1)


class TestProductionPersistedQueueConcurrency(unittest.TestCase):
    """_PersistedRequestQueue correctness under concurrent access."""

    def test_enqueue_mark_resume_roundtrip(self):
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "q.sqlite3")
            q = _PersistedRequestQueue(path)
            try:
                self.assertTrue(q.enabled())
                q.enqueue("https://a.test/1", 0)
                q.enqueue("https://a.test/2", 0)
                q.mark("https://a.test/1", "done")
                pending = q.resume_pending()
                self.assertEqual(pending, [("https://a.test/2", 0)])
            finally:
                q.close()

    def test_resume_empty_when_nothing_pending(self):
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "q.sqlite3")
            q = _PersistedRequestQueue(path)
            try:
                self.assertEqual(q.resume_pending(), [])
            finally:
                q.close()

    def test_close_idempotent(self):
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "q.sqlite3")
            q = _PersistedRequestQueue(path)
            q.close()
            try:
                q.close()
            except Exception as e:
                self.fail(f"second close raised: {e!r}")

    def test_duplicate_enqueue_does_not_duplicate_row(self):
        with tempfile.TemporaryDirectory() as td:
            path = os.path.join(td, "q.sqlite3")
            q = _PersistedRequestQueue(path)
            try:
                q.enqueue("https://a.test/u", 0)
                q.enqueue("https://a.test/u", 0)
                pending = q.resume_pending()
                self.assertEqual(len(pending), 1,
                                 "duplicate enqueue must not create duplicate rows")
            finally:
                q.close()


class TestProductionAdaptiveConcurrency(unittest.TestCase):
    """_AdaptiveConcurrency controller."""

    def test_initial_target_is_ceiling(self):
        ac = _AdaptiveConcurrency(ceiling=5, floor=1, window=50)
        self.assertEqual(ac.target(10), 5)

    def test_record_success_increases_target(self):
        ac = _AdaptiveConcurrency(ceiling=20, floor=1, window=50)
        for _ in range(50):
            ac.record(ok=True)
        self.assertGreater(ac.target(10), 5)

    def test_record_failure_reduces_target(self):
        ac = _AdaptiveConcurrency(ceiling=20, floor=1, window=50)
        for _ in range(50):
            ac.record(ok=True)
        high = ac.target(10)
        for _ in range(50):
            ac.record(ok=False)
        self.assertLess(ac.target(10), high,
                        "failures should reduce concurrency target")

    def test_target_never_below_floor(self):
        ac = _AdaptiveConcurrency(ceiling=20, floor=3, window=50)
        for _ in range(100):
            ac.record(ok=False)
        self.assertGreaterEqual(ac.target(10), 3)

    def test_low_queue_limits_concurrency(self):
        ac = _AdaptiveConcurrency(ceiling=20, floor=1, window=50)
        for _ in range(50):
            ac.record(ok=True)
        self.assertLessEqual(ac.target(1), 1)


