    # ---- Captcha CSV cleanup tests ----
    def test_remove_captcha_entry_removes_url_from_csv(self):
        """_remove_captcha_entry must delete the row matching the URL
        from captcha_detected.csv while preserving other rows."""
        tmpdir = tempfile.mkdtemp()
        try:
            csv_path = os.path.join(tmpdir, "captcha_detected.csv")
            # Write a mini CSV with two captcha entries
            with open(csv_path, "w", newline="", encoding="utf-8") as f:
                w = csv.writer(f)
                w.writerow(["Timestamp", "URL/Domain", "Reason"])
                w.writerow(["2026-05-17 02:28:30",
                            "https://beehiiv.com/features/podcasts",
                            "Captcha Detected"])
                w.writerow(["2026-05-17 02:28:38",
                            "https://ipxo.com",
                            "Captcha Detected"])
            # Build a minimal scraper to access _remove_captcha_entry
            scraper = AdvancedEmailScraper.__new__(AdvancedEmailScraper)
            scraper.lock = RLock()
            scraper.captcha_log_path = csv_path
            scraper._tier2_bypassed_urls = set()
            # Act: remove the beehiiv entry
            scraper._remove_captcha_entry(
                "https://beehiiv.com/features/podcasts")
            # Assert: only ipxo.com row remains
            with open(csv_path, newline="", encoding="utf-8") as f:
                rows = list(csv.reader(f))
            self.assertEqual(len(rows), 2, "header + 1 data row must remain")
            row_urls = [r[1] for r in rows[1:]]
            self.assertNotIn("https://beehiiv.com/features/podcasts", row_urls)
            self.assertIn("https://ipxo.com", row_urls)
        finally:
            import shutil
            shutil.rmtree(tmpdir, ignore_errors=True)

