    # ---- Failed task tuple validation tests ----
    def test_urls_failed_during_outage_handles_malformed_tasks(self):
        """URLs collected during outage must handle malformed task tuples gracefully.

        This tests the validation logic added at lines ~5009 and ~4836-4838
        to prevent ValueError when unpacking malformed task tuples.
        """
        from collections import deque

        # Simulate the snapshot from urls_failed_during_outage_check
        # Some entries are malformed (not (url, depth) tuples)
        snapshot = [
            ("https://valid.com", "error"),
            ("not-a-tuple", "error"),  # string, not tuple
            (123, "error"),  # int, not tuple
            ("url-only",),  # single-element tuple
            ("url", "reason", "extra"),  # 3-element tuple
            ("https://last.com", "timeout"),
        ]

        # Split like the real code does
        failure_streak_threshold = 3
        failed_before_outage = snapshot[:-failure_streak_threshold]
        outage_urls = snapshot[-failure_streak_threshold:]
        crawl_queue = deque()

        # This simulates the fixed code at lines ~4836-4838
        # The fix adds isinstance check before unpacking
        for item in failed_before_outage:
            if isinstance(item, tuple) and len(item) == 2:
                failed_task, reason = item
                failed_url = failed_task
            else:
                failed_url = str(item) if item else "unknown"

        # This simulates the fixed code at lines ~5009-5012
        # The fix adds validation before appendleft
        for item in reversed(outage_urls):
            if not isinstance(item, tuple) or len(item) != 2:
                continue
            crawl_queue.appendleft(item)

        # Verify only valid (url, depth) tuples ended up in queue
        self.assertEqual(len(crawl_queue), 1)
        self.assertEqual(crawl_queue[0], ("https://last.com", "timeout"))

